# -*- coding: utf-8 -*-
"""translations_ne.py — Nepali literal + paraphrase translations for Gita verses.
Keyed by "ch.verse" (e.g. "1.01"). Missing entries fall back to English.
Filled chapter by chapter."""

TRANS_NE = {
"1.01": ("धृतराष्ट्रले भन्नुभयो: धर्मक्षेत्र कुरुक्षेत्रमा, युद्धका लागि उत्सुक भई भेला भएका — मेरा मानिसहरू र पाण्डुका छोराहरू — तिनीहरूले के गरे, हे सञ्जय?",
         "राजा धृतराष्ट्रले सोध्छन्: “कुरुक्षेत्रको पवित्र मैदानमा मेरा छोराहरू र पाण्डुका छोराहरू लड्न तयार भएर जम्मा भएका छन्। सञ्जय, बताऊ — के भयो?”"),
"1.02": ("सञ्जयले भने: पाण्डव सेनालाई युद्ध-व्यूहमा सजिएको देखेर, दुर्योधन त्यसपछि आफ्नो गुरुकहाँ गएर यी वचन बोले, हे राजन्।",
         "सञ्जयले जवाफ दिन्छन्: “पाण्डवहरूको सेना व्यूहमा सजिएको देखेर दुर्योधन आफ्ना गुरु द्रोणकहाँ गएर भन्छन्, हे राजा…”"),
"1.03": ("हेर, हे गुरु, पाण्डुका छोराहरूको यो विशाल सेना, द्रुपदका छोरा — तपाईंकै विद्वान् शिष्यले युद्धका लागि सजाएका छन्।",
         "“हेर्नुहोस्, गुरुजी — पाण्डुपुत्रहरूको यो विशाल सेना, तपाईंकै चतुर शिष्य द्रुपदपुत्र धृष्टद्युम्नले व्यूहबद्ध गरेका छन्।”"),
"1.04": ("यहाँ वीरहरू, महान् धनुर्धारीहरू छन् — युद्धमा भीम र अर्जुनका समान: युयुधान, विराट, र महारथी द्रुपद।",
         "“तिनीहरूको पङ्क्तिमा भीम र अर्जुनसरहका वीर र धनुर्धारीहरू छन्: युयुधान, राजा विराट, र महान् योद्धा द्रुपद।”"),
"1.05": ("र धृष्टकेतु, चेकितान, वीर्यवान् काशीका राजा, पुरुजित्, कुन्तिभोज, र मानिसहरूमा श्रेष्ठ शैब्य।",
         "“अनि त्यहाँ पनि: धृष्टकेतु, चेकितान, वीर काशीराज, पुरुजित्, कुन्तिभोज, र अतुलनीय शैब्य।”"),
"1.06": ("पराक्रमी युधामन्यु र वीर्यवान् उत्तमौजा, सुभद्राका छोरा, र द्रौपदीका छोराहरू — सबै महारथीहरू।",
         "“निर्भीक युधामन्यु, बलशाली उत्तमौजा, सुभद्रापुत्र अभिमन्यु, र द्रौपदीका पाँच छोरा — सबै रथकला सिपालु।”"),
"1.07": ("तर जान्नुहोस्, हे द्विजश्रेष्ठ, हामीतर्फ जो विशिष्ट छन् — मेरो सेनाका नायकहरू; तपाईंलाई जानकारीका लागि तिनको नाम बताउँछु।",
         "“तर हे गुरुजी, हाम्रो पक्षमा जो प्रमुख छन् — मेरा सेनाका कमान्डरहरू — तिनको नाम भनिदिन्छु, ताकि तपाईंलाई थाहा होस् कि हामीलाई को-को नेतृत्व गर्छन्।”"),
"1.08": ("तपाईं आफैं, भीष्म, कर्ण, युद्धमा विजयी कृप, अश्वत्थामा, विकर्ण, र सौमदत्तिका छोरा पनि।",
         "“तपाईं, मेरा गुरु; र भीष्म, कर्ण, युद्धविजयी कृप, अश्वत्थामा, विकर्ण, र सौमदत्तिका छोरा — सबै युद्धमा अपराजित।”"),
"1.09": ("र अरू धेरै वीरहरू, मेरो निम्ति जीवन दिन तयार, विभिन्न हतियार लिएर, सबै युद्धकलामा निपुण।",
         "“हामीसँग अझ धेरै वीरहरू छन्, मेरो लागि मर्न तयार, हरेक प्रकारका हतियार चलाउने — सबै युद्धमा पोख्त।”"),
"1.10": ("हाम्रो त्यो शक्ति, भीष्मले रक्षा गरे पनि, अपर्याप्त छ; तिनीहरूको यो शक्ति, भीमले रक्षा गरेको, पर्याप्त छ।",
         "“भीष्मले रक्षा गरे पनि हाम्रो सेना पर्याप्त छैन; भीमले रक्षा गरेको तिनीहरूको सेना अझ बढी छ।”"),
"1.11": ("सबै दिशाहरूमा खडा भएर, आ-आफ्ना विभागमा स्थान लिनुहोस् — र सबैभन्दा माथि, सबैले भीष्मकै रक्षा गर्नुहोस्।",
         "“हरेक मोर्चामा आ-आफ्नो स्थान लिनुहोस् — र सबैले भीष्मको विशेष रक्षा गर्नुहोस्।”"),
"1.12": ("उनलाई हर्षित गर्न, कुरुवंशका पितामह, तेजस्वी भीष्मले सिंहनाद गरे र ठूलो स्वरमा शङ्ख बजाए।",
         "दुर्योधनको हौसला बढाउन वृद्ध पितामह भीष्मले सिंहको गर्जना निकाले र पूरै शक्तिले आफ्नो महाशङ्ख बजाए।"),
"1.13": ("त्यसपछि शङ्ख, नगारा, ढोल, मृदङ्ग र सिंहनादहरू एकैसाथ बजे — त्यो ध्वनि भयङ्कर बन्यो।",
         "तुरुन्तै शङ्ख र नगारा, ढोल र तुरहीहरू एकैपटक बजे, र कोलाहल विशाल गर्जनमा परिणत भयो।"),
"1.14": ("त्यसपछि, सेता घोडाले जुताइएको विशाल रथमा उभिएर, माधव र पाण्डुपुत्रले आफ्ना दिव्य शङ्ख बजाए।",
         "अनि सेता घोडाले तानिएको महारथमा कृष्ण (माधव) र अर्जुनले आफ्ना दिव्य शङ्ख फुके।"),
"1.15": ("हृषीकेशले पाञ्चजन्य बजाए; धनञ्जयले देवदत्त; र हेराकुली पराक्रमी भीमले महाशङ्ख पाञ्चजन्य… पौण्ड्र बजाए।",
         "कृष्णले आफ्नो शङ्ख पाञ्चजन्य, अर्जुनले देवदत्त, र महान् पराक्रमी भीमले विशाल पौण्ड्र बजाए।"),
"1.16": ("राजा युधिष्ठिर, कुन्तीका छोरा, ले अनन्तविजय बजाए; नकुल र सहदेवले सुघोष र मणिपुष्पक।",
         "कुन्तीपुत्र राजा युधिष्ठिरले अनन्तविजय बजाए, जबकि नकुल र सहदेवले आ-आफ्ना शङ्ख सुघोष र मणिपुष्पक फुके।"),
"1.17": ("र काशीका राजा, सर्वश्रेष्ठ धनुर्धारी, महारथी शिखण्डी, धृष्टद्युम्न, विराट, र अपराजित सात्यकि।",
         "त्यस्तै काशीका महाधनुर्धारी, पराक्रमी शिखण्डी, धृष्टद्युम्न, राजा विराट, र कहिल्यै नहार्ने सात्यकि।"),
"1.18": ("द्रुपद र द्रौपदीका छोराहरू, हे पृथ्वीपति, र महाबाहु सुभद्रापुत्र — सबैले आ-आफ्ना शङ्ख बजाए।",
         "द्रुपद, द्रौपदीका छोरा, र बलशाली सुभद्रापुत्र — प्रत्येकले, हे राजा, आफ्नो शङ्ख बजाए।"),
"1.19": ("त्यो गर्जनले धृतराष्ट्रका छोराहरूको हृदय चिरिदियो, आकाश र पृथ्वीमा गुञ्जिरहेको भयानक ध्वनिले।",
         "बहिरो बनाउने त्यो ध्वनिले धृतराष्ट्रका छोराहरूको हृदय चिर्यो र स्वर्ग र पृथ्वी दुवैमा प्रतिध्वनित भयो।"),
"1.20": ("त्यसपछि, धार्तराष्ट्रहरूलाई व्यूहमा खडा देखेर, हतियार ठोक्किनै लाग्दा, बाँदर-ध्वज भएका पाण्डवले धनुष उठाए।",
         "युद्ध सुरु हुनै लाग्दा, हनुमान चिह्न भएको ध्वज भएका अर्जुनले शत्रु सेना हेरे र आफ्नो धनुष उठाए।"),
"1.21": ("हे पृथ्वीपति, उनले अनि हृषीकेशलाई यो वचन भने: “मेरो रथ दुवै सेनाको बीचमा राख, हे अच्युत।”",
         "अनि, हे राजा, अर्जुनले कृष्णलाई भने: “मेरो रथ दुवै सेनाको बीचमा राख, हे अविनाशी प्रभु।”"),
"1.22": ("“ताकि म यहाँ युद्धका लागि उत्सुक उभिएकाहरूलाई देखूँ — यस महायुद्धमा मैले कससँग लड्नुपर्छ भनी जान्न।”",
         "“लड्न आएकाहरूलाई देखूँ, र यस आउँदो युद्धमा मैले कसको सामना गर्नुपर्छ भनी थाहा पाऊँ।”"),
"1.23": ("“म युद्धमा लड्न आएकाहरूलाई हेर्न चाहन्छु — जो यहाँ दुष्टबुद्धि धृतराष्ट्रपुत्रलाई खुसी पार्न भेला भएका छन्।”",
         "“म यहाँ जम्मा भएका योद्धाहरूलाई देख्न चाहन्छु — जो दुष्ट दुर्योधनलाई खुसी पार्न यो युद्ध गर्न आएका छन्।”"),
"1.24": ("सञ्जयले भने: गुडाकेशद्वारा यसरी सम्बोधित भएर, हृषीकेशले, हे भरतवंशी, त्यो उत्तम रथ दुवै सेनाको बीचमा राखे।",
         "सञ्जय अगाडि भन्छन्: “अर्जुनको आदेश पाएर, हे धृतराष्ट्र, कृष्णले उत्तम रथ दुवै सेनाको बीचमा लगे।”"),
"1.25": ("भीष्म, द्रोण, र पृथ्वीका सबै राजाहरूका अगाडि उनले भने: “हे पार्थ, यहाँ भेला भएका यी कुरुहरूलाई हेर।”",
         "भीष्म, द्रोण, र संसारका सबै राजाहरूका अगाडि कृष्णले भने: “हेर, अर्जुन — तिम्रा अगाडि सम्पूर्ण कुरु वंश भेला भएको।”"),
"1.26": ("त्यहाँ अर्जुनले खडा देखे: पिता, पितामह, गुरुहरू, मामाहरू, भाइहरू, छोराहरू, नातिहरू, र मित्रहरू पनि।",
         "त्यहाँ, सेनाहरूको बीचमा, अर्जुनले आफ्ना पिता र पितामह, गुरु र मामा, भाइ, छोरा, नाति र मित्रहरू देखे।"),
"1.27": ("दुवै सेनामा ससुराहरू र हितैषीहरू — ती सबै नातेदारहरूलाई त्यहाँ खडा देखेर, कुन्तीका छोरा…",
         "दुवै पक्षमा ससुरा र प्रिय साथीहरू — अर्जुन, कुन्तीपुत्र, युद्धका लागि खडा आफ्ना सबै कुटुम्बलाई हेर्दा…"),
"1.28": ("गहिरो करुणाले भरिएर, शोक गर्दै, उनले भने — अर्जुनले भने: “मेरा यी आफ्नै मानिसहरूलाई देखेर, हे कृष्ण, यहाँ युद्धका लागि उभिएका…”",
         "गहिरो दयाले भरिएर, शोकमा डुबेर अर्जुनले भने: “हे कृष्ण, आफ्नै परिवारलाई मेरो अगाडि लड्न तयार देखेर…”"),
"1.29": ("“मेरा अङ्गहरू थकित हुन्छन्, मेरो मुख सुक्छ, मेरो शरीर काँप्छ, र मेरो रौँ ठाडो हुन्छ।”",
         "“मेरा खुट्टा लर्कन्छन्, मुख सुक्छ, सारा शरीर काँप्छ, र डरले रौँ ठाडो हुन्छ।”"),
"1.30": ("“गाण्डीव मेरो हातबाट चिप्लिन्छ, छाला बल्छ; म उभिन सक्दिनँ, र मेरो मन भड्किन्छ।”",
         "“गाण्डीव मेरो हातबाट खस्छ, छाला पोल्छ; म उभिनै सक्दिनँ, र मेरो मन नियन्त्रण बाहिर घुम्छ।”"),
"1.31": ("“र म अशुभ शकुनहरू देख्छु, हे केशव; आफ्नै कुटुम्बलाई युद्धमा मारेर केही भलो हुने पनि देख्दिनँ।”",
         "“म केवल खराब शकुन देख्छु, कृष्ण — र आफ्नै मानिसहरूलाई युद्धमा मारेर आउने कुनै भलो पनि देख्दिनँ।”"),
"1.32": ("“म विजय चाहन्नँ, हे कृष्ण, न राज्य, न भोगहरू। हामीलाई राज्यको के काम, हे गोविन्द — भोगको के काम, वा जीवनकै के काम?”",
         "“मलाई विजय चाहिँदैन, कृष्ण — न राज्य, न सुख। अब हामीलाई राज्य, आनन्द वा जीवनकै के अर्थ छ, गोविन्द?”"),
"1.33": ("“जसका लागि हामी राज्य, भोग र सुख चाहन्थ्यौं — तिनीहरू नै यहाँ युद्धमा खडा छन्, जीवन र धन दुवै त्यागेर।”",
         "“जसका निम्ति हामी राज्य, आराम र खुसी चाहन्थ्यौं — ती नै यहाँ आफ्नो ज्यान र सम्पत्ति सुम्पिन तयार उभिएका छन्।”"),
"1.34": ("“गुरुहरू, पिता, छोरा, र त्यस्तै पितामह, मामा, ससुरा, नाति, साला र अन्य नातेदारहरू।”",
         "“मेरा गुरु, पिता, छोरा र पितामह, मामा र ससुरा, नाति, साला र सबै कुटुम्ब — सबै यहाँ छन्।”"),
"1.35": ("“म तिनीहरूलाई मार्न चाहन्नँ, चाहे तिनीहरूले मलाई मारून्, हे मधुसूदन — तीन लोकको राज्यका निम्ति पनि होइन, पृथ्वीकै निम्ति त के।”",
         "“म तिनीहरूलाई मार्ने छैन, मधुसूदन — चाहे तिनीहरूले मलाई मारून्। तीनै लोकको अधिकारका लागि पनि होइन, यो पृथ्वीको निम्ति त झन् होइन।”"),
"1.36": ("“धृतराष्ट्रका छोराहरूलाई मारेर हामीलाई के खुसी मिल्नेछ, हे जनार्दन? यी आक्रमणकारीहरूलाई मारेको पाप नै हामीलाई लाग्नेछ।”",
         "“यदि हामीले धृतराष्ट्रका छोराहरूलाई नष्ट गर्यौं भने पनि, जनार्दन, हामीलाई के आनन्द हुनेछ? यी हत्याराहरूलाई मारेको पाप मात्र हामीसँग टाँसिनेछ।”"),
"1.37": ("“त्यसैले हामीले आफ्ना नातेदार धृतराष्ट्रका छोराहरूलाई मार्नु हुँदैन; किनकि आफ्नै मानिसहरूलाई मारेर हामी कसरी खुसी हुन सक्छौं, हे माधव?”",
         "“त्यसैले हाम्रा लागि आफ्नै परिवार — धृतराष्ट्रका छोराहरूलाई मार्नु गलत छ। आफ्नै कुटुम्बको हत्या गरेर हामी कहिल्यै खुसी हुन सक्दैनौं, माधव।”"),
"1.38": ("“यद्यपि यी मानिसहरू, जसका मन लोभले ग्रस्त छन्, कुलको विनाशमा दोष देख्दैनन् र मित्रद्रोहमा पाप पनि देख्दैनन्…”",
         "“साँचो हो, यी मानिसहरू — जसका हृदय लोभले अन्धा छन् — परिवार भत्काउनमा कुनै गल्ती र मित्रको विश्वासघातमा कुनै पाप देख्दैनन्…”"),
"1.39": ("“तर हामीले कसरी नजान्ने — जो कुलविनाशको दोष देख्छौं — कि हामीले यस पापबाट फर्कनुपर्छ, हे जनार्दन?”",
         "“तर हामी परिवारको नाशले आउने विनाश देख्न सक्छौं — त्यसैले हामी कसरी यस पापबाट पछि हट्न असफल हुन सक्छौं, जनार्दन?”"),
"1.40": ("“कुलको विनाशसँगै सनातन कुलधर्महरू लोप हुन्छन्; र धर्म नष्ट भएपछि अधर्मले सम्पूर्ण कुललाई निल्छ।”",
         "“जब परिवार नष्ट हुन्छ, उसका पुराना पवित्र परम्पराहरू पनि मर्छन्; र एकपटक धर्म हराएपछि अधर्मले सम्पूर्ण परिवारलाई ढाक्छ।”"),
"1.41": ("“अधर्मको उदयबाट, हे कृष्ण, कुलका स्त्रीहरू भ्रष्ट हुन्छन्; र भ्रष्ट स्त्रीहरूबाट, हे वार्ष्णेय, वर्णसङ्कर उत्पन्न हुन्छ।”",
         "“जब अधर्म फैलिन्छ, कृष्ण, परिवारका स्त्रीहरू भ्रष्ट हुन्छन्; र भ्रष्ट स्त्रीहरूबाट जात र वंशको मिश्रण उत्पन्न हुन्छ।”"),
"1.42": ("“यो सङ्करले कुलघातीहरूलाई र कुललाई नै नरकतर्फ लैजान्छ; तिनीहरूका पितृहरू झर्छन्, पिण्ड र जलका अर्घहरूबाट वञ्चित भएर।”",
         "“यस्तो मिश्रणले परिवारका नाशक र परिवार दुवैलाई नरकतिर तान्छ, र तिनका पितृहरू श्राद्ध-क्रियाबाट वञ्चित भई पतन हुन्छन्।”"),
"1.43": ("“कुलघातीहरूका यी दोषहरूबाट, जसले वर्णसङ्कर निम्त्याउँछ, समुदाय र कुलका सनातन धर्महरू नष्ट हुन्छन्।”",
         "“वर्णमिश्रण जन्माउने यी पापहरूद्वारा जाति र कुल दुवैका शाश्वत धर्महरू बगाइन्छन्।”"),
"1.44": ("“जसका कुलधर्म नष्ट भएका छन्, ती मानिसहरूको, हे जनार्दन, नरकमा बास हुन्छ भनिन्छ — यस्तो हामीले सुनेका छौं।”",
         "“र, जनार्दन, हामीले सुनेका छौं कि जसका पारिवारिक क्रियाहरू नष्ट हुन्छन्, तिनीहरूलाई नरकमा बस्नुपर्छ।”"),
"1.45": ("“हाय! हामीले कस्तो ठूलो पाप गर्ने निश्चय गरेका छौं — राज्य र सुखको लोभले अन्धा भएर, हामी आफ्नै कुटुम्ब मार्न तयार छौं।”",
         "“हामीले कस्तो भयानक गल्ती गर्न लागेका छौं! राजगद्दी र सुखको लालसाले अन्धा भएर, हामी आफ्नै परिवार मार्न तयार छौं।”"),
"1.46": ("“यदि धृतराष्ट्रका छोराहरू, हातमा हतियार लिएर, युद्धमा मलाई मार्छन् — मलाई निःशस्त्र र प्रतिरोधरहित — त्यो मेरा लागि राम्रो हुनेछ।”",
         "“यदि धृतराष्ट्रका छोराहरूले मलाई — निःशस्त्र र रक्षारहित — ढालिदिए भने, त्यो लड्नुभन्दा कैयौं गुणा राम्रो हुनेछ।”"),
"1.47": ("सञ्जयले भने: युद्धभूमिमा यसरी बोलेर, अर्जुन रथको आसनमा बसे, धनुष-बाण त्यागेर, मन शोकले भरिएको।",
         "सञ्जयले निष्कर्षमा भन्छन्: “यसरी भनेर, अर्जुन रथको आसनमा डुबे, धनुष-बाण छोडे, र हृदय शोकले च्यातिएर बसे।”"),
"2.01": ("सञ्जयले भने: यसरी करुणाले ग्रस्त, आँसु र आवेगले भरिएका आँखा भएका, शोकाकुल अर्जुनलाई देखेर मधुसूदनले यी वचन बोले।",
         "सञ्जय वर्णन गर्छन्: “करुणामा डुबेका, आँखाभरि आँसु र आवेग लिएका शोकाकुल अर्जुनलाई देखेर कृष्ण (मधुसूदन) ले उनलाई सम्बोधन गरे।”"),
"2.02": ("श्रीभगवान्ले भन्नुभयो: हे अर्जुन, यस सङ्कटको घडीमा तिमीलाई यो कहाँबाट आयो — यो अशोभनीय, आर्यलाई नसुहाउने, स्वर्गको ढोका बन्द गर्ने र अपमान ल्याउने निराशा?",
         "कृष्णले भन्नुभयो: “अर्जुन, यो कमजोरी तिमीलाई यही सङ्कटको घडीमा कहाँबाट आयो? यो तिमीलाई सुहाउँदैन, यसले स्वर्गको ढोका बन्द गर्छ र तिमीलाई अपमानित तुल्याउँछ।”"),
"2.03": ("हे पार्थ, कापुरुषता नअपनाऊ — त्यो तिमीलाई शोभादैन। हृदयको यो क्षुद्र दुर्बलता त्यागेर उठ, हे शत्रुतापन!",
         "“यो कायरताको अगाडि नझुक, अर्जुन — यो तिमीलाई शोभादैन। मनको यो सानो कमजोरी चटकाएर उठ, हे शत्रु जलाउने!”"),
"2.04": ("अर्जुनले भने: हे मधुसूदन, युद्धमा म कसरी भीष्म र द्रोणलाई मेरा वाणले हान्न सक्छु — जो पूजनीय छन्, हे शत्रुहन्ता?",
         "अर्जुन सोध्छन्: “कृष्ण, भीष्म र द्रोणलाई म कसरी मेरा वाण लगाउन सक्छु? उनीहरू मेरो आदरका पात्र हुन्, हतियारका होइनन्।”"),
"2.05": ("यस संसारमा यी महान् गुरुहरूलाई मार्नुभन्दा भिक्षा मागेर जीवन बिताउनु नै राम्रो। तिनलाई मारेर — सांसारिक लक्ष्यका निम्ति भए पनि — म रगतले लतपतिएका सुख मात्र चाख्नेछु।",
         "“यी पूजनीय गुरुजनलाई मार्नुभन्दा भोजनका लागि भीख माग्नु नै राम्रो। यदि मैले राज्य र भोगका निम्ति तिनलाई मारें भने रगतले रङ्गिएका सुख मात्र चाख्नेछु।”"),
"2.06": ("र हामीलाई थाहा छैन कि हाम्रो निम्ति के राम्रो — तिनलाई जित्नु वा तिनीसँग पराजित हुनु। धृतराष्ट्रका छोराहरू नै हाम्रो अगाडि उभिएका छन्; तिनलाई मारेपछि हामी जिउन चाहँदैनौं।",
         "“हामीलाई के उत्तम हो भनी छुट्याउन सकिँदैन — विजय वा पराजय। धृतराष्ट्रका यी छोराहरू हाम्रो अगाडि छन्, र तिनलाई मारेपछि हामी बाँच्नै चाहँदैनौं।”"),
"2.07": ("मेरो स्वभाव दयाले पराजित छ; कर्तव्यबारे मेरो बुद्धि भ्रमित छ। म तिमीलाई सोध्छु: निश्चय गरेर बताऊ के हितकर छ — म तिम्रो शिष्य हुँ; मलाई शिक्षा देऊ, मैले तिम्रो शरण लिएको छु।",
         "“दयाले मलाई हारेको छ र धर्मबारे म अलमलमा छु। के नै राम्रो हो, मलाई स्पष्ट भन। म तिम्रो शिष्य हुँ — मलाई मार्ग देखाऊ, म तिम्रो शरणमा आएको छु।”"),
"2.08": ("पृथ्वीको अद्वितीय राज्य वा देवताहरूमाथिको स्वामित्व पाए पनि — यो मेरा इन्द्रियहरू सुकाउने शोकलाई केले टाढा गर्छ, म देख्दिनँ।",
         "“यो मेरा इन्द्रिय सुकाउने शोक हटाउने कुनै उपाय म देख्दिनँ — न अविभाजित राज्यले, न देवताहरूको शासनले नै।”"),
"2.09": ("सञ्जयले भने: हृषीकेशलाई यसरी भनेर, शत्रुतापन अर्जुनले गोविन्दलाई 'म लड्नेछैन' भने — र मौन भए।",
         "सञ्जयले भन्छन्: “कृष्णलाई यसरी भनेर र 'म लड्दिनँ' घोषणा गरेर, शत्रुहरूको आतंक अर्जुन चुपचाप बसे।”"),
"2.10": ("दुवै सेनाको बीचमा शोक गरिरहेका उनलाई, हे भरतवंशी, हृषीकेशले मुस्कुराउँदैझैं यी वचन बोले।",
         "सञ्जय थप्छन्: “त्यसपछि, हे राजा, दुवै सेनाको बीचमा शोकमा बसेका अर्जुनलाई कृष्णले मुस्कुराएर भने।”"),
"2.11": ("श्रीभगवान्ले भन्नुभयो: जसका निम्ति शोक गर्नु हुँदैन, तिनीहरूका निम्ति तिमी शोक गर्छौ, तैपनि ज्ञानीका वचन बोल्छौ। ज्ञानीहरू न जीवितका निम्ति शोक गर्छन् न मृतकका निम्ति।",
         "कृष्णले भन्नुभयो: “जसको निम्ति शोक उचित छैन, उसैको निम्ति तिमी विलाप गर्छौ, तर ऋषिका वचन बोल्छौ। ज्ञानी न जिउँदाका निम्ति रुन्छन् न मरेकाका निम्ति।”"),
"2.12": ("यस्तो कुनै समय थिएन जब म थिइनँ, न तिमी थिएनौ, न यी राजाहरू; र भविष्यमा पनि हामीमध्ये कोही अस्तित्वहीन हुनेछैन भन्ने छैन।",
         "“कुनै समय थिएन जब म थिइनँ, न तिमी, न यी राजाहरू; र भविष्यमा पनि हामीमध्ये कोही नरहने होइन।”"),
"2.13": ("जसरी देहधारी आत्मा यस शरीरमा बाल्यावस्था, युवावस्था र वृद्धावस्थाबाट गुज्रन्छ, त्यसरी नै अर्को शरीरमा प्रवेश गर्छ; ज्ञानीहरू यसबाट भ्रमित हुँदैनन्।",
         "“जसरी शरीरभित्रको आत्मा बाल्यावस्था, जवानी र बुढ्यौली हुँदै जान्छ, मृत्युमा त्यसरी नै नयाँ शरीरमा पुग्छ। ज्ञानीहरू यसमा कहिल्यै अलमलिँदैनन्।”"),
"2.14": ("हे कुन्तीपुत्र, इन्द्रियहरूको विषयसँगको सम्पर्कले जाडो-गर्मी, सुख-दुःख दिन्छ; ती आउँछन् र जान्छन्, अनित्य छन् — हे भारत, तिनलाई सहन गर।",
         "“संसारसँगको सम्पर्कले जाडो-गर्मी, सुख-दुःख ल्याउँछ — यी आउँछन् र जान्छन्, अर्जुन; क्षणिक हुन्। तिनलाई सहन सिक।”"),
"2.15": ("जसलाई यीले विचलित पार्न सक्दैनन्, हे नरश्रेष्ठ — सुख-दुःखमा समान रहने ज्ञानी — ऊ नै अमरत्वका योग्य हुन्छ।",
         "“जसलाई यी कुराले हल्लाउन सक्दैनन् — सुख-दुःखमा एकनास रहने ज्ञानी — उही अमरत्वको अधिकारी हुन्छ।”"),
"2.16": ("असत्को अस्तित्व हुँदैन; सत् कहिल्यै अस्तित्वहीन हुँदैन। दुवैको यो तत्त्व तत्त्वदर्शीहरूले देखेका छन्।",
         "“जो वास्तविक होइन, त्यो कहिल्यै साँच्चै अस्तित्वमा रहँदैन; जो वास्तविक छ, त्यो कहिल्यै मेटिँदैन। सत्य देख्नेहरूले यी दुवैको सीमा बुझेका छन्।”"),
"2.17": ("जसद्वारा यो सबै व्याप्त छ, त्यो अविनाशी हो भनी जान। त्यस अक्षय पुरुषको विनाश कसैले गर्न सक्दैन।",
         "“यो सबैलाई व्याप्त गर्ने एक नै अविनाशी हो भनी जान। अस्तित्वमा कुनै पनि कुराले त्यो अपरिवर्तनीय तत्त्वलाई नष्ट गर्न सक्दैन।”"),
"2.18": ("अनन्त, अविनाशी, अमेय देहधारी आत्माका यी शरीरहरूको अन्त्य हुन्छ भनिएको छ; त्यसैले हे भारत, लड।",
         "“अनन्त, अविनाशी, अप्रमेय आत्माका शरीरहरू मात्र समाप्त हुन्छन् — आत्मा होइन। त्यसैले, अर्जुन, युद्ध गर।”"),
"2.19": ("जसले आत्मालाई मार्ने ठान्छ, र जसले आत्मा मारिन्छ भनी ठान्छ — दुवै साँच्चै बुझ्दैनन्: यसले न मार्छ न मारिन्छ।",
         "“जो आत्माले मार्न सक्छ भनी ठान्छ, र जो आत्मा मारिन सक्छ भनी ठान्छ — दुवै गलत छन्: आत्मा न मार्छ, न मारिन्छ।”"),
"2.20": ("यो कहिल्यै जन्मँदैन, कहिल्यै मर्दैन; भएपछि यो फेरि कहिल्यै नहुने होइन। अजन्मा, नित्य, शाश्वत र पुरातन — शरीर मारिए पनि यो मारिँदैन।",
         "“आत्मा कहिल्यै जन्मँदैन र कहिल्यै मर्दैन। एकपटक भएपछि त्यो कहिल्यै हुन छोड्दैन। अजन्मा, नित्य, कालातीत — शरीर मरे पनि आत्मा मर्दैन।”"),
"2.21": ("यस आत्मालाई अविनाशी, नित्य, अजन्मा र अक्षय जानेर — हे पार्थ, कुन मानिसले कसलाई मार्न लगाउन वा मार्न सक्छ?",
         "“जब कसैले आत्मालाई अविनाशी, नित्य, अजन्मा र अक्षय जान्दछ — त्यस्तो व्यक्तिले कसलाई मार्न वा मार्न लगाउन सक्छ र?”"),
"2.22": ("जसरी मानिसले जीर्ण लुगा फालेर नयाँ लुगा लगाउँछ, त्यसरी नै देहधारी आत्माले जीर्ण शरीर त्यागेर नयाँ शरीर प्राप्त गर्छ।",
         "“जसरी मानिसले पुराना वस्त्र फालेर नयाँ धारण गर्छ, त्यसरी नै आत्माले जीर्ण शरीर त्यागेर नयाँ शरीर लिन्छ।”"),
"2.23": ("शस्त्रले यसलाई काट्दैन, आगोले बाल्दैन, पानीले भिजाउँदैन, हावाले सुकाउँदैन।",
         "“कुनै हतियारले आत्मालाई चिर्न सक्दैन, कुनै आगोले बाल्न सक्दैन, कुनै पानीले भिजाउन सक्दैन, कुनै हावाले सुकाउन सक्दैन।”"),
"2.24": ("यो काटिन, बालिन, भिजाइन र सुकाइन सक्दैन। यो नित्य, सर्वव्यापी, स्थिर, अचल र सनातन छ।",
         "“आत्मा न काटिन्छ, न बालिन्छ, न भिज्छ, न सुक्छ। यो नित्य, सर्वव्यापी, स्थिर, अचल र पुरातन छ।”"),
"2.25": ("यो अव्यक्त, अचिन्त्य र विकारहीन भनिन्छ। यसरी जानेर तिमीलाई शोकको कुनै कारण छैन।",
         "“आत्मा अव्यक्त, अचिन्त्य र अपरिवर्तनीय कहिन्छ। यसरी बुझेपछि तिमीसँग शोक गर्ने कुनै कारण छैन।”"),
"2.26": ("तर यदि तिमीले आत्मा सधैं जन्मिने र सधैं मर्ने ठान्छौ भने पनि, हे महाबाहो, तैपनि तिमीले शोक गर्नु हुँदैन।",
         "“यदि तिमी गल्तीले आत्मा निरन्तर जन्मिरहेको र मर्दै गरेको ठान्छौ भने पनि, अर्जुन — तैपनि शोक गर्नु हुँदैन।”"),
"2.27": ("किनकि जन्मेकाको निम्ति मृत्यु निश्चित छ, र मरेकाको निम्ति जन्म निश्चित छ। त्यसैले, टार्न नसकिने विषयमा तिमीले शोक गर्नु हुँदैन।",
         "“जो जन्मेको छ, त्यो निश्चय मर्छ; जो मरेको छ, त्यो निश्चय फेरि जन्मिन्छ। त्यसैले यो अनिवार्य कुरामा शोकको ठाउँ छैन।”"),
"2.28": ("सबै प्राणीहरू सुरुमा अव्यक्त हुन्छन्, बीचमा व्यक्त हुन्छन्, र अन्तमा फेरि अव्यक्त हुन्छन्। हे भारत, यसमा शोक केको?",
         "“सबै प्राणी जन्मभन्दा अघि अदृश्य हुन्छन्, जीवनमा दृश्य हुन्छन्, र मृत्युपछि फेरि अदृश्य हुन्छन्। त्यसैले शोक गर्ने के नै छ र?”"),
"2.29": ("कोही आत्मालाई आश्चर्यरूप देख्छ, कोही आश्चर्यरूप वर्णन गर्छ, कोही आश्चर्यरूप सुन्छ — र सुनेर पनि कसैले साँच्चै जान्दैन।",
         "“कोही आत्मालाई चमत्कारका रूपमा देख्छन्, कोही वर्णन गर्छन्, कोही सुन्छन् — तर सुनेर पनि वास्तवमा कोही बुझ्दैन।”"),
"2.30": ("सबैको शरीरमा रहने देहधारी आत्मा सधैं अवध्य हुन्छ, हे भारत। त्यसैले तिमीले कुनै पनि प्राणीको निम्ति शोक गर्नु हुँदैन।",
         "“हरेक शरीरमा बस्ने आत्मा सदाका लागि अविनाशी छ, अर्जुन। त्यसैले तिमीले कसैको निम्ति पनि शोक गर्नु हुँदैन।”"),
"2.31": ("र आफ्नो धर्मलाई विचार गरेर पनि तिमीले विचलित हुनु हुँदैन; किनकि क्षत्रियका निम्ति धर्मयुद्धभन्दा उत्तम अरू केही छैन।",
         "“आफ्नो कर्तव्य हेरे पनि तिमी हिचकिचाउनु हुँदैन: योद्धाका निम्ति धर्मका निम्ति लडिएको युद्धभन्दा उत्तम अरू केही छैन।”"),
"2.32": ("हे पार्थ, धन्य ती क्षत्रियहरू — जसलाई यस्तो युद्ध आफैं प्राप्त हुन्छ — स्वर्गको खुला ढोका।",
         "“भाग्यमानी ती योद्धाहरू, अर्जुन, जसलाई यस्तो युद्ध प्राप्त हुन्छ — यो नबोलाइकनै आउँछ र स्वर्गको खुला द्वार हो।”"),
"2.33": ("तर यदि तिमीले यो धर्मयुद्ध लडेनौ भने, आफ्नो धर्म र कीर्ति त्यागेर तिमी पापमा फस्नेछौ।",
         "“तर यदि तिमीले यो धर्मयुद्ध लड्न अस्वीकार गर्यौ भने, तिमीले आफ्नो कर्तव्य र सम्मान दुवै गुमाउनेछौ — र पाप तिम्रो हुनेछ।”"),
"2.34": ("मानिसहरूले तिम्रो चिरस्थायी अपकीर्ति बोल्नेछन्; र सम्मानित व्यक्तिका निम्ति अपमान मृत्युभन्दा पनि कठोर हुन्छ।",
         "“संसारले तिम्रो चिरन्तन लाज फैलाउनेछ; र जो सम्मानित छ, उसका निम्ति अपमान मृत्युभन्दा नराम्रो हुन्छ।”"),
"2.35": ("महारथीहरूले तिमी डरले युद्धबाट भागेको ठान्नेछन्; र जसले तिमीलाई उच्च दृष्टिले हेर्थे, तिनीहरू तिमीलाई तुच्छ ठान्नेछन्।",
         "“ठूला रथीहरूले तिमी डरले पछि हटेको भन्नेछन्; तिम्रो प्रशंसा गर्नेहरू नै तिमीलाई हेला गर्न थाल्नेछन्।”"),
"2.36": ("तिम्रा शत्रुहरूले तिम्रो शक्तिको निन्दा गर्दै नभन्नुपर्ने कुराहरू बोल्नेछन्। त्योभन्दा कठोर अरू के हुन सक्छ?",
         "“तिम्रा शत्रुहरूले नभनिनुपर्ने कुरा भनेर तिम्रो साहसको खिल्ली उडाउनेछन्। त्यसभन्दा पीडादायक अरू के हुन सक्छ?”"),
"2.37": ("मारिएर तिमी स्वर्ग पाउनेछौ; विजयी भएर पृथ्वीको भोग गर्नेछौ। त्यसैले हे कुन्तीपुत्र, युद्धका निम्ति दृढ भएर उठ।",
         "“मर्दा तिमीले स्वर्ग पाउनेछौ; जित्दा पृथ्वीमाथि राज्य गर्नेछौ। त्यसैले, अर्जुन, युद्धको निश्चय गरेर उठ।”"),
"2.38": ("सुख-दुःख, लाभ-हानि, विजय-पराजयलाई समान गरेर त्यसपछि लड — यसरी लड्दा तिमीले पाप पाउनेछैनौ।",
         "“सुख-दुःख, लाभ-हानि, जित-हारलाई एकै ठानेर युद्ध गर — कुनै पापले तिमीलाई छुनेछैन।”"),
"2.39": ("हे पार्थ, यो साङ्ख्य बुद्धि तिमीलाई भनियो। अब योगबुद्धि सुन; यससँग जोडिएर तिमी कर्मबन्धन त्याग्नेछौ।",
         "“मैले तिमीलाई साङ्ख्यको विवेक सिकाएँ; अब योगको ज्ञान सुन। यसैमा जिउनेले कर्मको बन्धनबाट मुक्ति पाउँछ।”"),
"2.40": ("यहाँ आरम्भको नाश हुँदैन, न उल्टो फल नै हुन्छ। यस धर्मको अलिकति पनि ठूलो भयबाट रक्षा गर्छ।",
         "“यस मार्गमा कुनै प्रयास खेर जाँदैन, न कुनै बाधाले उसलाई फर्काउँछ। यस अभ्यासको अलिकति मात्रले पनि ठूलो भयबाट बचाउँछ।”"),
"2.41": ("हे कुरुनन्दन, यहाँ दृढनिश्चयीहरूको बुद्धि एक, एकाग्र हुन्छ; तर चञ्चलहरूका बुद्धिहरू अनन्त शाखामा फैलिन्छन्।",
         "“दृढ संकल्पको बुद्धि एक र स्थिर हुन्छ, अर्जुन; अनिश्चित मनहरूका बुद्धिहरू अनगिन्ती दिशामा छरिन्छन्।”"),
"2.42": ("वेदका फुलवारी वचनहरूमा रम्ने अज्ञानीहरू, क्रिया र भोगमा आसक्त, हे पार्थ, 'यसबाहेक अरू केही छैन' भनी घोषणा गर्छन्।",
         "“सतही मन भएकाहरू वेदका आकर्षक वचनहरूमा रम्छन् र तिनभन्दा पर केही छैन भनी दाबी गर्छन् — क्रिया र फलमा टाँसिएर।”"),
"2.43": ("कामनाले भरिएका, स्वर्गको आकाङ्क्षा गर्ने तिनीहरूले फलका रूपमा जन्म र कर्म बताउँछन्, र भोग र ऐश्वर्यका निम्ति धेरै विशेष क्रियाहरू सिकाउँछन्।",
         "“तिनीहरू कामनाले भरिएका, स्वर्ग चाहने हुन्छन्; पुनर्जन्म र पुरस्कारको आशा देखाउँछन्, र भोग-विलासका निम्ति जटिल अनुष्ठानहरूमा जोड दिन्छन्।”"),
"2.44": ("भोग र ऐश्वर्यमा आसक्त, त्यस्ता वचनले मन हराएकाहरूमा समाधिमा दृढ एकाग्र बुद्धि उत्पन्न हुँदैन।",
         "“जसको हृदय भोग र ऐश्वर्यले मोहित छ र यी वचनले हराएको छ, तिनमा समाधिको स्थिर बुद्धि जरा गाड्न सक्दैन।”"),
"2.45": ("वेदहरू तीन गुणका विषय हुन्; हे अर्जुन, तीन गुणभन्दा माथि उठ — द्वन्द्वरहित, नित्य सत्त्वमा स्थित, लाभ-स्वामित्वभन्दा पर, आत्मायुक्त होऊ।",
         "“वेदहरू तीन गुणभित्रै चल्छन्; तिनभन्दा माथि उठ, अर्जुन — द्वन्द्वभन्दा पर, शुद्धतामा टिकेर, मोह र अहंकारबाट मुक्त, आफ्नै स्वामी बनेर।”"),
"2.46": ("जति काम पानीले सर्वत्र बाढी आउँदा इनारको हुन्छ, बुझेका ब्राह्मणका निम्ति सबै वेदको त्यति नै उपयोग हुन्छ।",
         "“जमिन जलमग्न हुँदा इनारको अलिकति मात्र काम हुन्छ — त्यस्तै सत्य बुझेका ज्ञानीका निम्ति सबै वेदहरू।”"),
"2.47": ("तिम्रो अधिकार कर्ममा मात्र छ, फलमा कहिल्यै होइन। कर्मफललाई तिम्रो उद्देश्य नबनाऊ, र अकर्ममा आसक्त पनि नहोऊ।",
         "“तिमीलाई कर्म गर्ने अधिकार छ, तर फलमाथि कहिल्यै होइन। फलका निम्ति नगर, र केही नगर्ने आलस्यमा पनि नटाँसिनु।”"),
"2.48": ("हे धनञ्जय, योगमा स्थित भएर, आसक्ति त्यागेर कर्म गर; सिद्धि-असिद्धिमा समान रह — यो समत्व नै योग भनिन्छ।",
         "“योगमा जरा गाडेर, आसक्ति बिना आफ्नो काम गर, अर्जुन। जित-हारमा एकनास रह — त्यही सन्तुलन योग हो।”"),
"2.49": ("हे धनञ्जय, कर्म बुद्धियोगभन्दा धेरै निकृष्ट छ। बुद्धिमा शरण खोज; फलका निम्ति कर्म गर्नेहरू दयनीय हुन्।",
         "“सामान्य कर्म समझको योगभन्दा धेरै तल छ, अर्जुन। विवेकी बुद्धिमा शरण लेऊ — फलका निम्ति मात्र खट्नेहरू दयनीय हुन्।”"),
"2.50": ("बुद्धियुक्त व्यक्तिले यहीं यस लोकमा सुकृत र दुष्कृत दुवै त्याग्छ। त्यसैले योगमा आफूलाई समर्पित गर — योग नै कर्ममा कुशलता हो।",
         "“विवेकसँग एक हुँदा मानिस यही जीवनमा पुण्य र पाप दुवै छोड्छ। त्यसैले योगतिर लाग — किनकि योग नै कर्मको कला हो।”"),
"2.51": ("बुद्धियुक्त ज्ञानीहरूले कर्मफल त्यागेर जन्मबन्धनबाट मुक्त भई सबै दुःखभन्दा परको स्थान प्राप्त गर्छन्।",
         "“समझमा स्थापित ज्ञानीहरूले कर्मको फल छोडेर पुनर्जन्मको बन्धनबाट मुक्ति पाउँछन्, र कुनै दुःख नभएको अवस्थामा पुग्छन्।”"),
"2.52": ("जब तिम्रो बुद्धि मोहको हिलोभन्दा पार हुन्छ, तब तिमी सुनिएका र सुनिन बाँकी कुराहरूप्रति उदासीन हुनेछौ।",
         "“जब तिम्रो मन भ्रमको दलदलबाट पार हुन्छ, तब तिमी सुनिएका र सुनिन बाँकी शास्त्रहरूप्रति बेपरवाह हुनेछौ।”"),
"2.53": ("जब श्रुतिहरूले भ्रमित तिम्रो बुद्धि समाधिमा स्थिर र अचल हुन्छ, तब तिमीले योग प्राप्त गर्नेछौ।",
         "“जब तिम्रो बुद्धि, शास्त्रका विरोधाभासले नडग्मगाइकन, समाधिमा शान्त हुन्छ — तब तिमी योगमा पुगेका हुन्छौ।”"),
"2.54": ("अर्जुनले भने: हे केशव, समाधिमा स्थित, स्थिरप्रज्ञ पुरुषको लक्षण के हो? स्थिरबुद्धि कसरी बोल्छ, कसरी बस्छ, कसरी हिँड्छ?",
         "अर्जुन सोध्छन्: “हे कृष्ण, समाधिमा टिकेको स्थिर प्रज्ञाको मान्छेको विशेषता के हो? यस्तो मान्छे कसरी बोल्छ, कसरी बस्छ, कसरी हिँड्छ?”"),
"2.55": ("श्रीभगवान्ले भन्नुभयो: हे पार्थ, जब मानिसले मनका सबै कामनाहरू त्याग्छ, र आत्मामै आत्माले सन्तुष्ट हुन्छ — तब ऊ स्थिरप्रज्ञ भनिन्छ।",
         "कृष्णले जवाफ दिनुभयो: “जब मानिसले मनमा उठ्ने हरेक इच्छा छोड्छ र आत्मामै आत्माले सन्तोष पाउँछ — त्यही स्थिर बुद्धिको मान्छे हो।”"),
"2.56": ("दुःखमा जसको मन विचलित हुँदैन, सुखमा जो निःस्पृह छ, जसबाट राग, भय र क्रोध गएका छन् — त्यो नै स्थिरबुद्धि मुनि हो।",
         "“जसको मन दुःखले हल्लिँदैन र सुखमा मोह हुँदैन, जसले काम, डर र क्रोध छोडेको छ — त्यो स्थिर मनको ज्ञानी हो।”"),
"2.57": ("जो सर्वत्र आसक्तिरहित छ, शुभ वा अशुभ पाएर न रम्छ न रिसाउँछ — त्यसको बुद्धि दृढ स्थापित हुन्छ।",
         "“जो कुनै कुरामा टाँसिँदैन, जो राम्रोबाट उल्लासित र नराम्रोबाट विचलित हुँदैन — त्यसको समझ स्थिर हुन्छ।”"),
"2.58": ("जसरी कछुवाले चारैतिरबाट अङ्गहरू सङ्कोच गर्छ, त्यसरी नै जब मानिसले इन्द्रियहरूलाई विषयहरूबाट फर्काउँछ — त्यसको बुद्धि दृढ स्थापित हुन्छ।",
         "“जसरी कछुवाले आफ्ना अङ्ग भित्र तान्छ, त्यसरी जब मानिसले इन्द्रियलाई विषयबाट फर्काउँछ — त्यसको बुद्धि दृढ हुन्छ।”"),
"2.59": ("संयमी व्यक्तिबाट विषयहरू टाढिन्छन्, तर तिनको रस रहन्छ; र परम तत्त्व देखेपछि त्यो रस पनि जान्छ।",
         "“परहेज गर्नेबाट विषय टाढिन्छन्, तर तिनको लोभ लुकेर रहन्छ; तर परम सत्य देख्नेबित्तिकै त्यो लोभ पनि हराउँछ।”"),
"2.60": ("हे कुन्तीपुत्र, प्रयत्नशील ज्ञानीकै निम्ति पनि चञ्चल इन्द्रियहरूले बलपूर्वक मनलाई हरेर लैजान्छन्।",
         "“प्रयास गरिरहेका ज्ञानीको पनि, अर्जुन, बेचैन इन्द्रियहरूले मनलाई जबरजस्ती तानेर लैजान्छन्।”"),
"2.61": ("तिनलाई सबैलाई संयम गरेर, संयमी व्यक्ति ममा नै तत्पर भएर बस्नुपर्छ; जसको इन्द्रियहरू वशमा छन्, त्यसकै बुद्धि दृढ स्थापित हुन्छ।",
         "“सबै इन्द्रियलाई काबूमा राखेर योगी ममै ध्यान दिएर बस्नुपर्छ; जसको इन्द्रिय वशमा छ, त्यसकै समझ दृढ हुन्छ।”"),
"2.62": ("विषयहरूको चिन्तन गर्दा तिनमा आसक्ति जन्मिन्छ; आसक्तिबाट कामना उत्पन्न हुन्छ; कामनाबाट क्रोध आउँछ।",
         "“इन्द्रियविषयमा मन दिनुले आसक्ति जन्माउँछ; आसक्तिबाट इच्छा; इच्छाबाट क्रोध आउँछ।”"),
"2.63": ("क्रोधबाट मोह आउँछ; मोहबाट स्मृतिको भ्रम; स्मृतिभ्रमबाट बुद्धिको नाश; र बुद्धिनाशबाट मानिस विनष्ट हुन्छ।",
         "“क्रोधले मोह ल्याउँछ; मोहले स्मरण शक्ति अलमल्याउँछ; अलमलिएको स्मरणले विवेक नष्ट गर्छ; र विवेक नष्ट भएपछि मान्छे बरबाद हुन्छ।”"),
"2.64": ("तर जो राग-द्वेषरहित, वशमा गरिएका इन्द्रियहरूद्वारा विषयहरूका बीचमा विचरण गर्छ, संयमी — त्यो प्रसन्नता प्राप्त गर्छ।",
         "“तर आफूलाई नियन्त्रण गर्नेले इन्द्रियलाई वशमा राखेर, मन-पराई बिना, विषयहरूका बीच हिँड्छ — र शान्ति जित्छ।”"),
"2.65": ("त्यो प्रसन्नतामा उसका सबै दुःखहरू नष्ट हुन्छन्; किनकि प्रसन्नचित्तको बुद्धि छिट्टै दृढ हुन्छ।",
         "“त्यो शान्तिमा यस्तो मानिसका सबै कष्ट अन्त्य हुन्छन्; शान्त मन छिट्टै नै स्पष्टतामा टिक्छ।”"),
"2.66": ("असंयतका निम्ति बुद्धि छैन, असंयतका निम्ति भावना छैन; भावनारहितका निम्ति शान्ति छैन — शान्तिरहितलाई सुख कसरी हुन्छ?",
         "“अनुशासनहीनलाई विवेक हुँदैन, चञ्चललाई ध्यान हुँदैन; ध्यान बिना शान्ति हुँदैन, र शान्ति बिना सुख कसरी सम्भव?”"),
"2.67": ("किनकि चलायमान इन्द्रियहरूको पछि जाने मनले बुद्धिलाई हरेर लैजान्छ, जसरी हावाले पानीमा डुङ्गालाई लैजान्छ।",
         "“इन्द्रियलाई पछ्याउँदै डुल्ने मनले मानिसको विवेक बगाउँछ, जसरी हावाले समुद्रमा डुङ्गा बगाउँछ।”"),
"2.68": ("त्यसैले, हे महाबाहो, जसका इन्द्रियहरू विषयहरूबाट सबैतिर फर्काइएका छन् — त्यसकै बुद्धि दृढ स्थापित हुन्छ।",
         "“त्यसैले, अर्जुन, जसले इन्द्रियहरूलाई विषयबाट पूरै फर्काएको छ — त्यसैको समझ दृढ हुन्छ।”"),
"2.69": ("सबै प्राणीहरूका निम्ति जो रात हो, संयमी मुनिका निम्ति त्यो जागरण हो; प्राणीहरू जाग्ने जो कुरा हो, दर्शी मुनिका निम्ति त्यो रात हो।",
         "“सामान्य संसारलाई जो रात हो, संयमी ज्ञानीका निम्ति त्यो जागृति हो; र संसारले जसलाई दिन भन्छ, त्यो द्रष्टाका निम्ति रात हो।”"),
"2.70": ("जसरी पानीहरू चारैतिरबाट भरिएर पनि अचल रहने समुद्रमा प्रवेश गर्छन्, त्यसरी नै जसमा सबै कामनाहरू प्रवेश गर्छन्, त्यो शान्ति पाउँछ — कामना चाहनेले होइन।",
         "“जसरी नदीहरू समुद्रमा खस्छन् र समुद्र अचल भरिएको रहन्छ, त्यसरी नै जसमा सबै इच्छाहरू बगेर आउँछन्, ऊ शान्त रहन्छ — इच्छाकै लोभ गर्ने होइन।”"),
"2.71": ("जसले सबै कामनाहरू त्यागेर निःस्पृह, निर्मम र निरहंकार भएर विचरण गर्छ — त्यो मानिस शान्ति प्राप्त गर्छ।",
         "“जसले हरेक इच्छा छोडेर, लोभ, 'मेरो' र 'म' बिना जिउँछ — त्यो व्यक्तिले शान्ति पाउँछ।”"),
"2.72": ("हे पार्थ, यो ब्राह्मी अवस्था हो; यो प्राप्त गरेर मानिस फेरि मोहित हुँदैन। अन्त्यकालमा पनि यसमै स्थित रहेर ब्रह्मनिर्वाण पाउँछ।",
         "“यो ब्रह्मको अवस्था हो, अर्जुन। यसमा पुगेपछि कोही फेरि कहिल्यै मोहमा पर्दैन। मृत्युको घडीमा पनि यसैमा टिकेर, ब्रह्ममा मुक्ति पाउँछ।”"),
"3.01": ("अर्जुनले भने: हे जनार्दन, यदि तपाईंकै दृष्टिमा ज्ञान कर्मभन्दा श्रेष्ठ छ भने, हे केशव, किन तपाईं मलाई यस भयानक कर्ममा लगाउनुहुन्छ?",
         "अर्जुन सोध्छन्: “यदि तपाईं ज्ञानलाई कर्मभन्दा श्रेष्ठ ठान्नुहुन्छ भने, केशव, मलाई यो भयानक युद्धमा किन धकेल्नुहुन्छ?”"),
"3.02": ("मिल्दो-जुल्दो लाग्ने वचनले तपाईंले मेरो बुद्धिलाई अलमल्याउनुभएको छ। एउटै कुरा निश्चय गरेर भन्नुहोस्, जसद्वारा म हित प्राप्त गरूँ।",
         "“तपाईंका वचन मिश्रित र विरोधाभासी लाग्छन् — तीले मलाई मात्र अलमल्याउँछन्। साँचो हितमा पुर्‍याउने एउटै मार्ग स्पष्ट भन्नुहोस्।”"),
"3.03": ("श्रीभगवान्ले भन्नुभयो: हे निष्पाप, यस संसारमा पहिले नै मैले दुईवटा निष्ठाका मार्ग बताएको थिएँ: साङ्ख्यहरूका निम्ति ज्ञानयोग, र योगीहरूका निम्ति कर्मयोग।",
         "कृष्णले भन्नुभयो: “धेरै अघि मैले दुई मार्ग सिकाएको थिएँ, हे निष्पाप: चिन्तनशीलका निम्ति ज्ञानको मार्ग, र क्रियाशील योगीका निम्ति निःस्वार्थ कर्मको मार्ग।”"),
"3.04": ("कर्म नगरेर मानिस कर्मसंन्यास पाउँदैन, न केवल संन्यासले मात्र सिद्धि पाउँछ।",
         "“कर्म अस्वीकार गरेर तिमी कर्मबाट मुक्त हुँदैनौ, न संसार त्यागेर मात्र सिद्धि मिल्छ।”"),
"3.05": ("निश्चय नै कोही पनि एक क्षण पनि अकर्मी रहँदैन; प्रकृतिबाट जन्मेका गुणहरूले सबैलाई असहाय भई कर्म गराउँछन्।",
         "“कोही पनि एक सेकेन्ड पनि बेकाम बस्न सक्दैन — प्रकृतिका गुणहरूले सबैलाई, चाहँदा नचाहँदा पनि, कर्म गराउँछन्।”"),
"3.06": ("जसले कर्मेन्द्रियहरूलाई रोकेर पनि मनमा विषयहरूको चिन्तन गर्दै बस्छ — त्यो भ्रमित व्यक्ति कपटी भनिन्छ।",
         "“हातखुट्टा अकर्मी राखेर मनमा भोगका कुरा खेलाउने — त्यो आफैंलाई धोका दिने ढोंगी हो।”"),
"3.07": ("तर जसले मनद्वारा इन्द्रियहरूलाई नियन्त्रण गरेर, आसक्ति रहित भई कर्मेन्द्रियहरूद्वारा कर्मयोग गर्छ — ऊ नै उत्कृष्ट हुन्छ।",
         "“तर जसले मनले इन्द्रियलाई काबूमा राखेर शरीरले आसक्ति बिना कर्म गर्छ — त्यो व्यक्ति साँच्चै उत्कृष्ट हुन्छ।”"),
"3.08": ("तिमीले आफ्नो विहित कर्म गर, किनकि कर्म अकर्मभन्दा श्रेष्ठ छ; अकर्मले त शरीरको निर्वाह पनि हुँदैन।",
         "“तिमीलाई दिइएको कर्तव्य पालन गर, किनकि कर्म नै अकर्मभन्दा उत्तम — बिना कर्म शरीर जिउँदै राख्न पनि असम्भव छ।”"),
"3.09": ("यज्ञका निम्ति गरिएको कर्मबाहेक, संसार कर्मले बाँधिएको छ; त्यसैले हे कुन्तीपुत्र, आसक्ति रहित भई यज्ञका निम्ति कर्म गर।",
         "“स्वार्थका निम्ति गरिएको कर्मले बाँध्छ; यज्ञका रूपमा अर्पित कर्मले मुक्त गर्छ। त्यसैले, अर्जुन, आसक्ति बिना यसैका निम्ति कर्म गर।”"),
"3.10": ("प्रजापतिले सुरुमै प्राणीहरूलाई यज्ञसँगै सृष्टि गरेर भने: “यसबाट तिमीहरू फस्टाउनेछौ; यो तिमीहरूका निम्ति इच्छापूरक गाई होस्।”",
         "“सृष्टिकर्ताले सुरुमै मानवतालाई यज्ञको विधि दिए: ‘यसबाट तिमी फस्टाउनेछौ; यसले तिम्रा सबै आवश्यकता पूरा गर्नेछ।’”"),
"3.11": ("यसद्वारा देवताहरूलाई पोषण गर, र देवताहरूले तिमीलाई पोषण गरून्; यसरी परस्पर पोषण गरेर तिमीहरू परम हित प्राप्त गर्नेछौ।",
         "“यज्ञद्वारा उच्च शक्तिहरूको सेवा गर र तिनले बदलामा तिमीलाई धानून् — यस परस्पर दानमा सबै परम कल्याणमा पुग्छन्।”"),
"3.12": ("यज्ञले पोषित देवताहरूले तिमीलाई चाहेका भोगहरू दिनेछन्; तिनले दिएको उपभोग गर्ने तर बदलामा नदिने व्यक्ति चोर नै हो।",
         "“तिम्रा अर्पणले प्रसन्न देवताहरूले जीवनका असल वस्तु दिन्छन्। तिनको दान लिएर बदला नदिने — त्यो चोर हो।”"),
"3.13": ("यज्ञका बचेका प्रसाद खाने असल मानिसहरू सबै पापबाट मुक्त हुन्छन्; तर आफ्नै निम्ति मात्र पकाउने पापीहरू त पाप नै खान्छन्।",
         "“यज्ञको बचेको प्रसाद बाँडेर खानेहरू पापबाट शुद्ध हुन्छन्; आफ्नै निम्ति मात्र पकाउनेहरू पापबाहेक केही खाँदैनन्।”"),
"3.14": ("प्राणीहरू अन्नबाट उत्पन्न हुन्छन्; अन्न वर्षाबाट; वर्षा यज्ञबाट; यज्ञ कर्मबाट उत्पन्न हुन्छ।",
         "“जीवन अन्नबाट, अन्न वर्षाबाट, वर्षा यज्ञबाट, र यज्ञ असल कर्मबाट — सबै एउटै शृङ्खलामा जोडिएका छन्।”"),
"3.15": ("कर्म ब्रह्मबाट, र ब्रह्म अक्षरबाट उत्पन्न हुन्छ भनी जान; त्यसैले सर्वव्यापी ब्रह्म सधैं यज्ञमा प्रतिष्ठित छ।",
         "“सबै कर्म अनन्त ब्रह्मबाट उत्पन्न हुन्छन्; त्यसैले सर्वव्यापी परमात्मा सधैं निःस्वार्थ अर्पणमा विद्यमान छ।”"),
"3.16": ("हे पार्थ, जसले यहाँ यसरी घुमाइएको यो चक्र अनुसरण गर्दैन, जसको जीवन पापमय छ, इन्द्रियमा रम्ने — ऊ व्यर्थ बाँच्छ।",
         "“दिने र लिने यस चक्रमा सहभागी हुन अस्वीकार गर्यौ भने तिम्रो जीवन खेर जान्छ, अर्जुन — तिमी इन्द्रियका निम्ति मात्र बाँच्छौ।”"),
"3.17": ("तर जो आत्मामै रम्छ, आत्मामै तृप्त हुन्छ, र आत्मामै सन्तुष्ट छ — उसका निम्ति गर्नुपर्ने केही छैन।",
         "“जो आफूभित्रै पूर्ण खुसी छ, उसका निम्ति गर्न बाँकी केही छैन — उसका लागि कुनै कर्तव्य रहँदैन।”"),
"3.18": ("उसका निम्ति गरिएको वा नगरिएको कर्ममा कुनै प्रयोजन छैन, न उसलाई कुनै प्रयोजनका निम्ति कुनै प्राणीमाथि आश्रय छ।",
         "“यस्तो व्यक्तिलाई गर्ने वा नगर्नेबाट केही प्राप्त हुँदैन; न कुनै प्राणी वा लक्ष्यले उसलाई बाँध्न सक्छ।”"),
"3.19": ("त्यसैले आसक्ति रहित भएर सधैं कर्तव्यरूप कर्म नै गर; किनकि आसक्ति बिना कर्म गर्दा मानिस परम पद प्राप्त गर्छ।",
         "“त्यसैले कर्म गरिरह, तर फलमा कहिल्यै नटाँसिनु — आसक्ति बिनाको कर्म नै परमतिर पुर्‍याउने बाटो हो।”"),
"3.20": ("निश्चय नै कर्मद्वारा नै जनक आदिले सिद्धि प्राप्त गरे; लोकसंग्रहलाई ध्यानमा राखेर पनि तिमीले कर्म गर्नुपर्छ।",
         "“राजा जनक र अरू धेरैले कर्मबाटै सिद्धि पाए। संसारको हितका निम्ति तिमीले पनि कर्म गर्नैपर्छ।”"),
"3.21": ("श्रेष्ठ पुरुषले जे गर्छ, सामान्य मानिसले त्यही गर्छ; उसले जे प्रमाण मान्छ, संसारले त्यसैको अनुसरण गर्छ।",
         "“मानिसहरू आफ्ना नेताको अनुकरण गर्छन्। तिमीमध्ये श्रेष्ठले जे गर्छ, त्यही अरूका निम्ति नियम बन्छ।”"),
"3.22": ("हे पार्थ, मेरा निम्ति तीनै लोकमा गर्नुपर्ने केही छैन, न प्राप्त गर्न बाँकी केही छ — तैपनि म कर्ममा लागिरहन्छु।",
         "“तीनै लोकमा मलाई प्राप्त गर्न बाँकी केही छैन — तैपनि म काम गरिरहन्छु।”"),
"3.23": ("यदि म कहिल्यै अकर्मी भएर, थकित नभई कर्म नगरें भने, हे पार्थ, मानिसहरूले सबै कुरामा मेरै मार्ग अनुसरण गर्नेछन्।",
         "“यदि मैले कहिल्यै काम गर्न छोडें भने, सबैले मेरै उदाहरण पछ्याएर आफ्ना कर्तव्य पनि छोडिदिनेछन्।”"),
"3.24": ("यदि मैले कर्म नगरें भने यी लोकहरू नष्ट हुन्छन्; म सङ्करको कर्ता हुनेछु र यी प्राणीहरूलाई नष्ट गर्नेछु।",
         "“यदि मैले कर्म गर्न छोडें भने संसार भत्किनेछ — र त्यसको विनाश गर्ने म नै हुनेछु।”"),
"3.25": ("हे भारत, जसरी अज्ञानीहरू आसक्त भई कर्म गर्छन्, त्यसरी नै ज्ञानीले पनि आसक्ति रहित भई, लोकसंग्रहका निम्ति कर्म गर्नुपर्छ।",
         "“अज्ञानीहरू आफ्नो काममा टाँसिएर काम गर्छन्; ज्ञानी पनि त्यति नै काम गर्छ, तर टाँसिएर होइन — सबैको हितका निम्ति।”"),
"3.26": ("कर्ममा आसक्त अज्ञानीहरूको बुद्धिमा खलल नपारोस्; आफैं योगयुक्त भएर कर्म गर्दै सबै कर्म गराओस्।",
         "“आफ्ना कर्तव्यमा टाँसिएकाहरूलाई अलमल्याउने काम नगर। आफ्नो काम भक्तिसाथ गर — र उनीहरूले तिम्रो उदाहरणबाटै सिकून्।”"),
"3.27": ("सबै कर्महरू सबैतिर प्रकृतिका गुणहरूद्वारा नै सम्पन्न हुन्छन्; अहंकारले भ्रमित व्यक्तिले 'म कर्ता हुँ' भनी सोच्छ।",
         "“प्रकृतिका शक्तिहरूले नै तिमीबाट सबै काम गराउँछन्। अहंकारी मानिसले झूटो विश्वास गर्छ — ‘यो सब म गर्दैछु।’”"),
"3.28": ("तर हे महाबाहो, गुण र कर्मको विभाग र गुणहरू गुणहरूमै विचरण गर्छन् भनी जान्ने तत्त्वज्ञ आसक्त हुँदैन।",
         "“ज्ञानीहरू बुझ्छन् कि गुणहरू गुणहरूसँगै क्रियाशील हुन्छन् — तिनीहरू आफूलाई कर्मसँग कहिल्यै जोड्दैनन्।”"),
"3.29": ("प्रकृतिका गुणहरूले भ्रमित ती मानिसहरू गुणजन्य कर्महरूमा आसक्त हुन्छन्; पूर्णज्ञानीले मन्दबुद्धि, अल्पज्ञहरूलाई विचलित नगरोस्।",
         "“अज्ञानी मानिसहरू आफ्नो काममा टाँसिन्छन्; ज्ञानीले संन्यासको उपदेश दिएर तिनलाई खलबलाउनु हुँदैन।”"),
"3.30": ("सबै कर्महरू ममा अर्पण गरेर, मनलाई आत्मामा स्थिर गरेर, आशा र ममता रहित भएर, ज्वरोरहित — लड।",
         "“हरेक कर्म मलाई अर्पण गर, मन आत्मामा राख, सबै लोभ र मोह छोड — र बिना आवेग युद्ध गर।”"),
"3.31": ("जसले मेरो यो उपदेशलाई सधैं श्रद्धापूर्वक, दोष नदेखी अनुसरण गर्छन् — ती मानिसहरू कर्मबन्धनबाट पनि मुक्त हुन्छन्।",
         "“जसले मेरो यो शिक्षालाई विश्वाससाथ र कुनै गुनासो बिना पछ्याउँछ — उनीहरू कर्मको पकडबाट मुक्त हुन्छन्।”"),
"3.32": ("तर जसले दोष देखेर मेरो यो उपदेश अनुसरण गर्दैनन् — तिनलाई सबै ज्ञानबाट वञ्चित, नष्ट र अविवेकी जान।",
         "“जो मेरो शिक्षाप्रति गुनासो गर्छन् र अस्वीकार गर्छन् — तिनीहरू हराएका हुन्; ज्ञानविहीन भई आफैंलाई नष्ट गर्छन्।”"),
"3.33": ("ज्ञानी मानिस पनि आफ्नै स्वभावअनुसार कर्म गर्छ; प्राणीहरू स्वभावको अनुसरण गर्छन् — संयमले के हुन्छ?",
         "“सबैले, ज्ञानीले पनि, आफ्नै स्वभावअनुसार काम गर्छन्। प्राणीहरू आफ्नो प्रकृतिलाई पछ्याउँछन् — जबरजस्ती रोक्नुको के अर्थ?”"),
"3.34": ("हरेक इन्द्रियको विषयमा राग र द्वेष स्थिर छन्; मानिस तिनको वशमा नपरोस्, किनकि ती नै उसका बाटो छेक्ने हुन्।",
         "“हरेक इन्द्रियविषयमा मनपर्ने र नमनपर्ने झुन्डिएका छन्। तिनलाई आफूमाथि हावी हुन नदेऊ — ती आध्यात्मिक मार्गका लुटेरा हुन्।”"),
"3.35": ("आफ्नो धर्म, यद्यपि दोषपूर्ण छ, पराया सुसम्पन्न धर्मभन्दा राम्रो; आफ्नै धर्ममा मर्नु पनि राम्रो — पराया धर्मले भय ल्याउँछ।",
         "“आफ्नो कर्तव्य त्रुटिपूर्ण भए पनि अरूको कर्तव्य पूर्ण रूपमा गर्नुभन्दा राम्रो। आफ्नै ठाउँमा मर्नु पनि राम्रो — अरूको काम गरेर डरमा बाँच्नुभन्दा।”"),
"3.36": ("अर्जुनले भने: तब हे वार्ष्णेय, केले प्रेरित गरेर मानिस आफ्नो इच्छाविपरीत, मानौं बलले जबरजस्ती गरिएर पनि पाप गर्छ?",
         "अर्जुन सोध्छन्: “के शक्तिले मानिसलाई नचाहँदा नचाहँदै पनि, जबरजस्ती तानेर, पाप गराउँछ?”"),
"3.37": ("श्रीभगवान्ले भन्नुभयो: यो कामना हो, यो क्रोध हो — रजोगुणबाट जन्मेको; सबै निल्ने, महापापी — यसलाई नै यहाँ शत्रु जान।",
         "कृष्णले भन्नुभयो: “यो कामना हो — र त्यसबाट जन्मेको क्रोध — रजोगुणबाट उठेको। अतृप्त र अत्यन्त पापी: यसलाई नै आफ्नो साँचो शत्रु जान।”"),
"3.38": ("जसरी आगो धुवाँले ढाकिन्छ, ऐना धुलोले, र भ्रूण झिल्लीले ढाकिन्छ — त्यसरी नै यो (ज्ञान) त्यस (कामना)ले ढाकिएको छ।",
         "“कामनाले ज्ञानलाई त्यसरी ढाक्छ, जसरी धुवाँले आगो, धुलोले ऐना, र झिल्लीले भ्रूणलाई।”"),
"3.39": ("ज्ञानीहरूको यो शाश्वत शत्रु — कामनाको रूपधारी, अतृप्त, हे कुन्तीपुत्र, आगोजस्तै — ले ज्ञानलाई ढाक्छ।",
         "“यो चिर शत्रु — कामना — ले ज्ञानलाई ढाक्छ। यो कहिल्यै तृप्त हुँदैन; यो आगोजस्तै बल्छ, अर्जुन।”"),
"3.40": ("इन्द्रियहरू, मन र बुद्धि यसको आसन भनिन्छ; यसले यिनीहरूद्वारा ज्ञानलाई ढाकेर देहधारीलाई मोहित गर्छ।",
         "“कामना इन्द्रिय, मन र बुद्धिमा बस्छ — र तिनैद्वारा देहधारीलाई अन्धो र मोहित पार्छ।”"),
"3.41": ("त्यसैले, हे भरतश्रेष्ठ, पहिले इन्द्रियहरूलाई वशमा गरेर, ज्ञान र विवेकको नाश गर्ने यस पापीलाई फ्याँकिदेऊ।",
         "“त्यसैले, अर्जुन, पहिले आफ्ना इन्द्रियलाई काबूमा राख — र ज्ञान र विवेक दुवै नष्ट गर्ने यस दुष्टलाई मार।”"),
"3.42": ("इन्द्रियहरू श्रेष्ठ भनिन्छन्; इन्द्रियभन्दा श्रेष्ठ मन; मनभन्दा श्रेष्ठ बुद्धि; तर बुद्धिभन्दा पनि श्रेष्ठ उही (आत्मा) हो।",
         "“क्रमशः माथि उठ: इन्द्रियभन्दा पर मन, मनभन्दा पर बुद्धि — र बुद्धिभन्दा पर आत्मा नै।”"),
"3.43": ("यसरी बुद्धिभन्दा परको उहाँलाई जानेर, हे महाबाहो, आत्माद्वारा आत्मालाई स्थिर गरेर, जित्न गाह्रो कामनारूपी शत्रुलाई मार।",
         "“बुद्धिभन्दा परको आत्मालाई चिनेर, आफैंलाई आफैंले स्थिर गरेर, जित्न कठिन कामनारूपी शत्रुलाई मार, अर्जुन।”"),
"4.01": ("श्रीभगवान्ले भन्नुभयो: यो अविनाशी योग मैले विवस्वान्लाई भनेको थिएँ; विवस्वान्ले मनुलाई भने; मनुले इक्ष्वाकुलाई प्रचार गरे।",
         "कृष्णले भन्नुभयो: “धेरै अघि मैले यो नित्य योग सूर्यदेव विवस्वान्लाई सिकाएको थिएँ; उनले मनुलाई दिए, र मनुले राजा इक्ष्वाकुलाई।”"),
"4.02": ("यसरी परम्पराले ग्रहण गरेर राजर्षिहरूले यसलाई जाने; तर लामो समयको क्रममा, हे शत्रुतापन, यो योग लोप भयो।",
         "“गुरुबाट शिष्यमा हस्तान्तरण हुँदै राजा-ऋषिहरूले यसलाई जाने — तर धेरै लामो समयपछि यो हरायो, अर्जुन।”"),
"4.03": ("यही प्राचीन योग आज म तिमीलाई बताउँछु, किनकि तिमी मेरो भक्त र मित्र हौ — साँच्चै, यो परम गोप्य हो।",
         "“त्यही प्राचीन योग म अहिले तिमीलाई सिकाउँछु, किनकि तिमी मप्रति भक्त छौ र मेरा मित्र हौ — यो सबैभन्दा ठूलो गोप्य कुरा हो।”"),
"4.04": ("अर्जुनले भने: तिम्रो जन्म पछि, र विवस्वान्को जन्म पहिले; तब तिमीले सुरुमा यो सिकाएको थियौ भनी म कसरी बुझूँ?",
         "अर्जुन सोध्छन्: “तपाईं सूर्यदेव विवस्वान्ले जन्मेको धेरै पछि जन्मनुभयो। सुरुमै उहाँलाई यो योग कसरी सिकाउनुभयो?”"),
"4.05": ("श्रीभगवान्ले भन्नुभयो: मेरा धेरै जन्महरू बितिसकेका छन्, हे अर्जुन, र तिम्रा पनि; म ती सबै जान्दछु, तर तिमी जान्दैनौ, हे शत्रुतापन।",
         "कृष्णले भन्नुभयो: “हामी दुवैका अनगिन्ती जन्म बितिसके, अर्जुन। म ती सबै सम्झन्छु; तिमी सम्झँदैनौ।”"),
"4.06": ("यद्यपि अजन्मा, अविनाशी आत्मा, प्राणीहरूको स्वामी — आफ्नै प्रकृतिलाई आश्रय गरेर, आफ्नै मायाद्वारा म उत्पन्न हुन्छु।",
         "“म अजन्मा र नित्य छु, सबै प्राणीका स्वामी — तैपनि, आफ्नै प्रकृति उठाएर, आफ्नै दिव्य शक्तिले संसारमा प्रकट हुन्छु।”"),
"4.07": ("हे भारत, जब-जब धर्मको ह्रास र अधर्मको वृद्धि हुन्छ, तब-तब म आफैंलाई प्रकट गर्छु।",
         "“जब-जब धर्म क्षीण हुन्छ र अधर्म बढ्छ, अर्जुन, तब-तब म प्रकट हुन्छु।”"),
"4.08": ("असलहरूको रक्षा, दुष्टहरूको विनाश, र धर्मको स्थापनाका निम्ति म हरेक युगमा जन्म लिन्छु।",
         "“धार्मिकको रक्षा, दुष्टको विनाश, र धर्मको पुनर्स्थापनाका निम्ति म हरेक युगमा जन्मिन्छु।”"),
"4.09": ("जसले यसरी साँच्चै मेरो दिव्य जन्म र कर्म जान्दछ — शरीर त्यागेर ऊ फेरि जन्मँदैन; ऊ मकहाँ आउँछ, हे अर्जुन।",
         "“जसले साँच्चै मेरो दिव्य जन्म र कर्म बुझ्छ, ऊ मृत्युपछि फेरि कहिल्यै जन्मिँदैन — ऊ मकहाँ आउँछ, अर्जुन।”"),
"4.10": ("आसक्ति, भय र क्रोधबाट मुक्त, ममा भरिएका, मेरो शरण लिने धेरै — ज्ञानरूपी तपस्या (तप)ले शुद्ध भएर — मेरो अवस्था प्राप्त गरेका छन्।",
         "“जो मोह, डर र क्रोधबाट मुक्त छन्, जसले मेरो शरण लिन्छन् — तिनीहरू ज्ञानको आगोले शुद्ध भएर मेरै स्वरूपमा पुग्छन्।”"),
"4.11": ("मानिसहरू जसरी जसरी मकहाँ आउँछन्, त्यसरी नै म उनीहरूलाई स्वीकार गर्छु; हे पार्थ, मानिसहरू सबै तरिकाले मेरो मार्ग अनुसरण गर्छन्।",
         "“जसरी पनि तिमी मकहाँ आउँछौ, म त्यसरी नै तिमीलाई ग्रहण गर्छु। हरेक बाटो फेरि मकहाँ फर्कन्छ, अर्जुन।”"),
"4.12": ("यस संसारमा कर्मको सिद्धि चाहनेहरू देवताहरूको पूजा गर्छन्; किनकि मानव लोकमा कर्मजन्य सिद्धि छिट्टै आउँछ।",
         "“छिटो फल चाहनेहरू देवताको पूजा गर्छन्; मानव संसारमा कर्मबाट फल छिट्टै पनि आउँछ।”"),
"4.13": ("गुण र कर्मको विभागअनुसार मैले चार वर्ण सृष्टि गरेको हुँ; यद्यपि म यसको कर्ता हुँ, मलाई अकर्ता र अविनाशी जान।",
         "“मैले गुण र कर्मअनुसार समाजका चार वर्ग बनाएँ — तैपनि म ती सबैभन्दा पर, अपरिवर्तनीय अकर्ता हुँ।”"),
"4.14": ("कर्मले मलाई लाग्दैन, न मलाई कर्मफलको कामना नै छ; जसले मलाई यसरी जान्दछ, ऊ पनि कर्मले बाँधिँदैन।",
         "“म फलको इच्छा गर्दिनँ, त्यसैले कर्मले मलाई कहिल्यै छुँदैन। जसले यो बुझ्छ, ऊ पनि उति नै स्वतन्त्र हुन्छ।”"),
"4.15": ("यो जानेर, प्राचीन मुक्तिकामीहरूले कर्म गरे; त्यसैले तिमीले पनि कर्म गर, जसरी पुरातनकालमा गरिएको थियो।",
         "“पहिलेका ज्ञानीहरू, मुक्ति चाहनेहरू, यसरी नै कर्म गर्थे। तिमीले पनि, अर्जुन, तिनीहरूझैं कर्म गर्नुपर्छ।”"),
"4.16": ("के कर्म, के अकर्म — यहाँ ज्ञानीहरू पनि मोहित छन्; म तिमीलाई त्यो कर्म बताउनेछु, जसलाई जानेर तिमी दुःखबाट मुक्त हुनेछौ।",
         "“साँच्चै के कर्म हो, के अकर्म? विद्वान्हरू पनि अलमलमा छन्। म तिमीलाई कर्मको सत्य सिकाउनेछु — यो जानेर तिमी सबै हानिबाट मुक्त हुनेछौ।”"),
"4.17": ("निश्चय नै कर्मको स्वरूप बुझ्नुपर्छ, र विकर्मको पनि, र अकर्मको पनि; कर्मको गति रहस्यमय छ।",
         "“तिमीले कर्म, दुष्कर्म, र अकर्म — तीनै बुझ्नुपर्छ; कर्मका बाटो गहिरा र अगाध छन्।”"),
"4.18": ("जसले कर्ममा अकर्म देख्छ, र अकर्ममा कर्म देख्छ — ऊ मानिसहरूमा बुद्धिमान् हो; ऊ योगमा संलग्न छ र सबै कर्म गर्छ।",
         "“जसले गरिरहेको काममा कर्ता देख्दैन, र शान्तिमा कर्म देख्छ — ऊ साँच्चै ज्ञानी हो; कर्म गर्दै पनि उसले गर्नुपर्ने सबै गर्छ।”"),
"4.19": ("जसका सबै आरम्भहरू इच्छा र सङ्कल्परहित छन्, र जसका कर्महरू ज्ञानाग्निले बालिएका छन् — उसलाई नै ज्ञानीहरू पण्डित भन्छन्।",
         "“जसको हरेक काम मोह र स्वार्थबाट मुक्त छ, जसको कर्म ज्ञानले भस्म भएको छ — विद्वान्हरू उसैलाई साँच्चै ज्ञानी भन्छन्।”"),
"4.20": ("कर्मफलप्रति आसक्ति त्यागेर, सधैं सन्तुष्ट, कुनै आश्रय बिना — कर्ममा संलग्न भए पनि ऊ वास्तवमा केही गर्दैन।",
         "“फलको मोहबाट मुक्त, सधैं सन्तोषी, केही नचाहने — यस्तो व्यक्ति कर्म गर्छ, तर उसबाट केही गरिएको हुँदैन।”"),
"4.21": ("आशा रहित, मन र आत्मा संयत गरेर, सबै परिग्रह त्यागेर, केवल शारीरिक कर्म गर्दा ऊ पापमा लाग्दैन।",
         "“इच्छा रहित, आत्मसंयमी, केही नभएको — शरीरले मात्र काम गर्छ, र कुनै पापले उसलाई छुँदैन।”"),
"4.22": ("अनायास आएको कुरामा सन्तुष्ट, द्वन्द्वभन्दा पर, डाह रहित, सिद्धि-असिद्धिमा समान — कर्म गर्दा पनि ऊ बाँधिँदैन।",
         "“जे आइपर्छ त्यसैमा खुसी, जाडो-गर्मी र जित-हारभन्दा पर, ईर्ष्यारहित — उसका कर्मले उसलाई कहिल्यै बाँध्दैन।”"),
"4.23": ("आसक्ति रहित, मुक्त, ज्ञानमा स्थित मन भएको, यज्ञका निम्ति कर्म गर्ने व्यक्तिका कर्महरू — ती पूर्ण रूपमा विलीन हुन्छन्।",
         "“जो आसक्ति रहित र स्वतन्त्र छ, जसको मन ज्ञानमा टिक्छ र जसको काम अर्पण हो — उसको कर्म पूरै पग्लिन्छ।”"),
"4.24": ("ब्रह्म नै हविस् (अर्पण) हो, ब्रह्म नै आहुति हो, ब्रह्मरूपी अग्निमा ब्रह्मद्वारा अर्पण गरिन्छ; ब्रह्मकर्ममा तल्लीन हुनेले ब्रह्म नै प्राप्त गर्छ।",
         "“जब अर्पण, आगो, दिने र दिने क्रिया — सबै ब्रह्मका रूपमा देखिन्छन्, कर्म नै ब्रह्मतिरको बाटो बन्छ।”"),
"4.25": ("केही योगीहरू यज्ञद्वारा देवताहरूको पूजा गर्छन्; अरूहरू यज्ञलाई नै, यज्ञद्वारा, ब्रह्मरूपी अग्निमा अर्पण गर्छन्।",
         "“कोही देवतालाई भौतिक पूजा चढाउँछन्; कोही जीवनकै सम्पूर्णतालाई परमात्माको आगोमा अर्पण गर्छन्।”"),
"4.26": ("केहीले श्रवण आदि इन्द्रियहरूलाई संयमरूपी अग्निमा अर्पण गर्छन्; अरूले शब्द आदि विषयहरूलाई इन्द्रियरूपी अग्निमा अर्पण गर्छन्।",
         "“केही साधकहरूले आफ्ना इन्द्रियलाई आत्मसंयमको आगोमा चढाउँछन्; अरूले इन्द्रियका विषयहरूलाई नै।”"),
"4.27": ("र अरूहरूले इन्द्रियका सबै क्रियाहरू र प्राणका क्रियाहरूलाई, ज्ञानले प्रज्वलित आत्मसंयमयोगरूपी अग्निमा अर्पण गर्छन्।",
         "“अरूले इन्द्रियका हरेक क्रिया र श्वासका क्रियालाई, ज्ञानले बालेको आत्म-संयमको आगोमा समर्पण गर्छन्।”"),
"4.28": ("अरूहरू द्रव्ययज्ञ, तपोयज्ञ, योगयज्ञ र स्वाध्याययज्ञ गर्छन् — दृढ व्रत भएका तपस्वीहरू।",
         "“कोही धन दान गरेर, कोही तपस्या, कोही ध्यान, कोही शास्त्र अध्ययनले यज्ञ गर्छन् — सबै दृढ संकल्पका खोजीहरू।”"),
"4.29": ("केहीले प्राणलाई अपानमा र अपानलाई प्राणमा अर्पण गर्छन्, प्राण-प्राणको गति रोकेर, प्राणायाममा तत्पर भएर।",
         "“अरूले प्राणायाम गर्छन् — एक श्वासलाई अर्कोमा अर्पण गरेर, जीवनशक्तिको बहाव शान्त पारेर।”"),
"4.30": ("अरूहरू, मिताहार भएर, प्राणलाई प्राणमै अर्पण गर्छन्; यी सबै यज्ञका ज्ञाता हुन्, जसका पाप यज्ञले भस्म हुन्छन्।",
         "“अरू, कम खाएर, श्वासलाई श्वासमै अर्पण गर्छन्। यज्ञ बुझ्ने सबैका पाप त्यसैले जलिन्छन्।”"),
"4.31": ("यज्ञको बचेको अमृत चाखेर तिनीहरू अनन्त ब्रह्ममा पुग्छन्; हे कुरुश्रेष्ठ, यो संसार नै यज्ञरहितको होइन — परलोक त के?",
         "“अर्पणको पवित्र बचेको भागमा बाँच्नेहरू नित्य ब्रह्ममा पुग्छन्। यज्ञ बिना यो संसार पनि भोग्न सकिँदैन — परलोक त झन्।”"),
"4.32": ("यसरी शास्त्रमा धेरै प्रकारका यज्ञहरू बताइएका छन्; ती सबै कर्मबाट जन्मेका हुन् भनी जान — यो जानेर तिमी मुक्त हुनेछौ।",
         "“शास्त्रहरूले धेरै किसिमका यज्ञ वर्णन गर्छन्। ती सबै कर्मबाट उठ्छन् भनी जान — र यो बुझ्नुले तिमीलाई मुक्त गर्छ।”"),
"4.33": ("हे शत्रुतापन, द्रव्यमय यज्ञभन्दा ज्ञानयज्ञ श्रेष्ठ छ; हे पार्थ, सम्पूर्ण कर्म ज्ञानमै पर्यवसान हुन्छ।",
         "“ज्ञानको अर्पण कुनै पनि भौतिक अर्पणभन्दा ठूलो छ — सबै कर्म, अपवाद बिना, ज्ञानमै अन्त्य हुन्छ।”"),
"4.34": ("तत्त्वज्ञानलाई प्रणिपात, प्रश्न र सेवाद्वारा जान; सत्य देखेका तत्त्वदर्शीहरूले तिमीलाई उपदेश गर्नेछन्।",
         "“नम्रतासाथ ज्ञानीहरूकहाँ जाऊ, इमान्दारीसाथ सोध, र सेवा गर — सत्य देख्नेहरूले तिमीलाई ज्ञान दिनेछन्।”"),
"4.35": ("त्यो जानेर, हे पाण्डुपुत्र, तिमी फेरि मोहमा पर्नेछैनौ; यसद्वारा तिमी सबै प्राणीलाई आफूमा र ममा देख्नेछौ।",
         "“यो ज्ञान पाएपछि तिमी फेरि कहिल्यै मोहमा पर्नेछैनौ — तिमी सबै प्राणीलाई आफूभित्र र मभित्र देख्नेछौ।”"),
"4.36": ("यदि तिमी सबै पापीहरूमा सबैभन्दा पापी पनि भएँ भने, ज्ञानरूपी डुङ्गाले नै तिमी सबै पाप पार गर्नेछौ।",
         "“यदि तिमी सबैभन्दा नराम्रो पापी पनि भएँ भने, ज्ञानको डुङ्गाले तिमीलाई सबै पाप पारि पुर्‍याउनेछ।”"),
"4.37": ("जसरी प्रज्वलित आगोले इन्धनलाई खरानी बनाउँछ, हे अर्जुन, त्यसरी नै ज्ञानाग्निले सबै कर्मलाई खरानी बनाउँछ।",
         "“जसरी आगोले इन्धन जलाएर खरानी बनाउँछ, ज्ञानको आगोले सबै कर्म जलाउँछ।”"),
"4.38": ("निश्चय नै यहाँ ज्ञानजस्तो पवित्र गर्ने अरू केही छैन; समयमा, योगमा सिद्ध व्यक्तिले यसलाई आफैं, आफ्नै आत्मामा पाउँछ।",
         "“ज्ञानजस्तो पवित्र गर्ने अरू केही छैन। तयार योगीले समयमा यसलाई आफूभित्रै उठेको पाउँछ।”"),
"4.39": ("श्रद्धावान्, तत्पर, इन्द्रिय संयत व्यक्तिले ज्ञान प्राप्त गर्छ; र ज्ञान पाएर ऊ छिट्टै परम शान्तिमा पुग्छ।",
         "“जसमा श्रद्धा, लक्ष्यप्रति समर्पण, र इन्द्रियमाथि विजय छ — उसले ज्ञान पाउँछ; र ज्ञानसँगै गहिरो, टिकाउ शान्ति।”"),
"4.40": ("तर अज्ञानी, श्रद्धारहित, सन्देहमा डुबेको मानिस नष्ट हुन्छ; सन्देही आत्माका निम्ति न यो लोक छ, न परलोक, न सुख।",
         "“अज्ञानी र श्रद्धारहित, सन्देहले च्यातिएकाहरू हराउँछन् — सन्देहीलाई यहाँ वा पर, कतै सुख छैन।”"),
"4.41": ("योगद्वारा कर्म त्यागेको, ज्ञानले सन्देह नष्ट भएको, आत्मायुक्त व्यक्तिलाई कर्मले बाँध्दैन, हे धनञ्जय।",
         "“जसले योगद्वारा आफ्नो कर्म समर्पण गरेको छ, जसका सन्देह ज्ञानले काटिएका छन् — उसलाई केहीले बाँध्न सक्दैन, अर्जुन।”"),
"4.42": ("त्यसैले, हृदयमा बसेको अज्ञानजन्य यस सन्देहलाई ज्ञानरूपी तरबारले काटेर, योगमा दृढ भएर उठ, हे भारत!",
         "“त्यसैले हृदयको सन्देहलाई ज्ञानको तरबारले काट, योगमा आफ्नो अडान लेऊ — र उठ, अर्जुन!”"),
"5.01": ("अर्जुनले भने: हे कृष्ण, तपाईं कर्मसंन्यासको प्रशंसा गर्नुहुन्छ, र कर्मयोगको पनि; यी दुईमध्ये कुन एक राम्रो हो, निश्चय गरेर भन्नुहोस्।",
         "अर्जुन सोध्छन्: “कृष्ण, तपाईंले कर्म त्याग्ने र कर्मलाई योगका रूपमा गर्ने — दुवैको प्रशंसा गर्नुहुन्छ; दुईमध्ये कुन राम्रो हो, स्पष्ट भन्नुहोस्।”"),
"5.02": ("श्रीभगवान्ले भन्नुभयो: संन्यास र कर्मयोग दुवै परम हितका कारक हुन्; तर दुईमध्ये कर्मयोग कर्मसंन्यासभन्दा श्रेष्ठ छ।",
         "कृष्णले भन्नुभयो: “दुवै मार्गले मुक्ति दिन्छन्, तर दुईमध्ये निःस्वार्थ कर्मको योग नै उत्तम हो।”"),
"5.03": ("जो न द्वेष गर्छ न कामना — ऊ सदा संन्यासी भनिनुपर्छ; द्वन्द्वरहित, हे महाबाहो, ऊ बन्धनबाट सजिलै मुक्त हुन्छ।",
         "“साँचो संन्यासी त्यो हो जो मन-पराईभन्दा मुक्त छ — सबै द्वन्द्वभन्दा पर, ऊ बन्धनबाट सजिलै चिप्लिन्छ।”"),
"5.04": ("बालकहरूले मात्र, ज्ञानीले होइन, साङ्ख्य र योगलाई फरक भन्छन्; एउटामा पनि ठीकसँग स्थित व्यक्तिले दुवैको फल पाउँछ।",
         "“अपरिपक्व मानिसहरू मात्र ज्ञान र कर्मलाई फरक बाटो ठान्छन्। कुनै एकमा साँच्चै जरा गाडे पनि दुवैको फल मिल्छ।”"),
"5.05": ("साङ्ख्यहरूले प्राप्त गर्ने पद योगीहरूले पनि पाउँछन्; जसले साङ्ख्य र योगलाई एक देख्छ — उसैले साँच्चै देख्छ।",
         "“ज्ञान र कर्म एउटै लक्ष्यतिर लैजान्छन्। जसले तिनलाई एकै देख्छ, ऊ साँच्चै देख्ने हो।”"),
"5.06": ("तर हे महाबाहो, योग बिना संन्यास पाउन गाह्रो छ; योगयुक्त ऋषि छिट्टै ब्रह्ममा पुग्छ।",
         "“भित्री योग बिना कर्म त्याग्नु धेरै कठिन छ; तर कर्मयोगी छिट्टै ब्रह्ममा पुग्छ।”"),
"5.07": ("कर्मयोगमा तत्पर, शुद्ध आत्मा भएको, आत्मविजयी, इन्द्रियजित, सबै प्राणीको आत्मा — कर्म गर्दा पनि ऊ लिप्त हुँदैन।",
         "“कर्मयोगी, शुद्ध र आत्मसंयमी, आफूलाई सबै प्राणीमा देख्ने — ऊ कर्म गर्दा पनि कहिल्यै दागिँदैन।”"),
"5.08": ("'म केही पनि गर्दिनँ' — तत्त्वज्ञले यसरी नै सोच्नुपर्छ, देख्दा, सुन्दा, छुँदा, सुँघ्दा, खाँदा, हिँड्दा, सुत्दा, श्वास फेर्दा —",
         "“ज्ञानीले 'म केही गर्दिनँ' भन्ने सोच्छ — देख्दा, सुन्दा, छुँदा, चाख्दा, हिँड्दा, सुत्दा, श्वास फेर्दा पनि,”"),
"5.09": ("बोल्दा, त्याग्दा, समात्दा, आँखा खोल्दा र चिम्लिँदा — इन्द्रियहरू इन्द्रियका विषयहरूमा विचरण गर्छन् भनी बुझेर।",
         "“बोल्दा, दिँदा, लिँदा, आँखा खोल्दा र चिम्लिँदा — इन्द्रियहरू आफ्ना विषयसँग भेटिरहेका छन् भन्ने जानेर।”"),
"5.10": ("जसले सबै कर्म ब्रह्ममा अर्पण गरेर, आसक्ति त्यागेर कर्म गर्छ — ऊ पापले लाग्दैन, जसरी कमलको पात पानीले भिज्दैन।",
         "“हरेक कर्म ब्रह्ममा अर्पण गर र आसक्ति छोड — पापले तिमीलाई छुन सक्दैन, जसरी पानीले कमलको पात भिजाउन सक्दैन।”"),
"5.11": ("योगीहरूले शरीर, मन, बुद्धि वा केवल इन्द्रियद्वारा पनि, आसक्ति त्यागेर, आत्मशुद्धिका निम्ति कर्म गर्छन्।",
         "“योगीहरू शरीर, मन वा इन्द्रियले, आसक्ति बिना — आफूलाई शुद्ध गर्न मात्र काम गर्छन्।”"),
"5.12": ("योगमा स्थित व्यक्तिले कर्मफल त्यागेर स्थायी शान्ति पाउँछ; योगमा नस्थित, इच्छाले प्रेरित, फलमा आसक्त व्यक्ति बाँधिन्छ।",
         "“फल छोड्ने योगीले स्थिर शान्ति पाउँछ; फलमा टाँसिएको, मोहले चलाइएको व्यक्ति बाँधिएरै रहन्छ।”"),
"5.13": ("मनबाटै सबै कर्म त्यागेर, आत्मसंयमी देहधारी नौ ढोकाको सहरमा सुखपूर्वक बस्छ — न कर्म गर्छ न गराउँछ।",
         "“आत्मविजयी आत्मा शरीर — नौ ढोकाको सहर — मा खुसीसाथ बस्छ, मनमै सबै कर्म समर्पण गरेर, न केही गर्छ न केही गराउँछ।”"),
"5.14": ("भगवान्ले न लोकको कर्तृत्व सिर्जना गर्छन् न कर्म, न कर्मफलको संयोग; प्रकृति नै कर्म गर्छे।",
         "“भगवान् न कर्तापन बनाउँछन्, न कर्म, न फल — प्रकृति नै सबै गर्छे।”"),
"5.15": ("सर्वव्यापी परमात्मा न कसैको पाप ग्रहण गर्छन् न पुण्य; ज्ञान अज्ञानले ढाकिएको हुन्छ, र त्यसैले प्राणीहरू मोहित हुन्छन्।",
         "“भगवान् कसैको पाप वा पुण्य स्वीकार गर्दैनन्। अज्ञानले ज्ञानलाई ढाक्छ, र त्यसैले प्राणीहरू अलमलिन्छन्।”"),
"5.16": ("तर जसको अज्ञान आत्मज्ञानले नष्ट भएको छ, तिनको त्यो ज्ञान सूर्यझैं चम्किएर परम तत्त्व प्रकट गर्छ।",
         "“जब अज्ञान आत्मज्ञानले नष्ट हुन्छ, ज्ञान सूर्यझैं बलेर परम तत्त्व देखाउँछ।”"),
"5.17": ("जसको बुद्धि त्यसमा, आत्मा त्यसमा, शरण त्यसमा, लक्ष्य त्यो नै — ज्ञानले पाप धोइएका ती फर्केर आउँदैनन्।",
         "“जसको सम्पूर्ण अस्तित्व ब्रह्ममा टिक्छ, ज्ञानले शुद्ध भएका ती कहिल्यै फर्कदैनन् — ती सधैंका निम्ति मुक्त हुन्छन्।”"),
"5.18": ("ज्ञानीहरूले विद्या र विनययुक्त ब्राह्मण, गाई, हात्ती, कुकुर र चाण्डाललाई पनि समान दृष्टिले हेर्छन्।",
         "“समान दृष्टिले ज्ञानीहरू विद्वान्, गाई, हात्ती, कुकुर — र चाण्डाल — सबैलाई एकै देख्छन्।”"),
"5.19": ("जसका मन समतामा टिकेका छन्, तिनले यहीं यस लोकमा जन्म-मृत्युलाई जितिसके; ब्रह्म निर्दोष र समान छ — त्यसैले तिनीहरू ब्रह्ममै स्थित हुन्छन्।",
         "“जसका मन सन्तुलित छन्, तिनले यही संसार जितिसके — किनकि ब्रह्म निष्कलङ्क र समान छ, र तिनीहरू त्यसैमा बस्छन्।”"),
"5.20": ("प्रिय वस्तु पाएर न रम्छ, अप्रिय पाएर न विचलित हुन्छ; स्थिर बुद्धि, अमोहित — ब्रह्मज्ञ त्यो ब्रह्ममै स्थित रहन्छ।",
         "“सुखले उसलाई उल्लासित गर्दैन, दुःखले विचलित गर्दैन — ब्रह्मज्ञ ब्रह्ममै अचल उभिन्छ।”"),
"5.21": ("बाह्य सम्पर्कहरूमा आसक्ति नराखेर, उसले आत्मामा रहेको सुख पाउँछ; ब्रह्मयोगमा जोडिएर उसले अविनाशी आनन्द भोग्छ।",
         "“बाह्य सुखमा नटाँसिएर उसले भित्रको आनन्द खोज्छ — र ब्रह्मसँग एक भएर अमर आनन्द चाख्छ।”"),
"5.22": ("निश्चय नै इन्द्रियसम्पर्कबाट जन्मेका सुखहरू दुःखका गर्भ हुन् मात्र; तिनको आदि र अन्त्य हुन्छ, हे कुन्तीपुत्र — ज्ञानीहरू तिनमा रम्दैनन्।",
         "“इन्द्रियजन्य सुखले दुःख मात्र जन्माउँछ — ती आउँछन् र जान्छन्। ज्ञानीहरू तिनमा आनन्द लिँदैनन्।”"),
"5.23": ("जसले यहीं, शरीर छोड्नुअघि नै, कामना र क्रोधबाट उठ्ने वेग सहन सक्छ — ऊ युक्त छ, ऊ सुखी मानिस हो।",
         "“जसले यहीं अहिले नै इच्छा र क्रोधको वेग सहन सक्छ — ऊ साँचो योगी हो, सुखी आत्मा।”"),
"5.24": ("जो भित्रै सुखी छ, भित्रै रम्छ, भित्रै प्रकाशित छ — त्यो योगी, ब्रह्मभूत भएर, ब्रह्मनिर्वाण प्राप्त गर्छ।",
         "“जसको सुख, आनन्द र प्रकाश सबै भित्र छन् — त्यो योगी, ब्रह्मसँग एक भएर, ब्रह्ममा मुक्ति पाउँछ।”"),
"5.25": ("जसका पाप नष्ट छन्, सन्देह काटिएका छन्, आत्मा वशमा छ, र सबै प्राणीको हितमा रम्छन् — ती ऋषिहरू ब्रह्मनिर्वाण पाउँछन्।",
         "“पापबाट शुद्ध, सन्देहरहित, आत्मविजयी, सबैको हितमा लाग्ने ऋषिहरू — तिनीहरू ब्रह्ममा मुक्ति पाउँछन्।”"),
"5.26": ("इच्छा र क्रोधबाट मुक्त, मन संयत, आत्मज्ञानी तपस्वीहरूका निम्ति — ब्रह्मनिर्वाण चारैतिर छ।",
         "“इच्छा र क्रोधबाट मुक्त, मनमाथि विजय पाएका, आत्मालाई चिन्नेहरूका निम्ति — ब्रह्ममा मुक्ति नजिकै छ।”"),
"5.27": ("बाह्य विषयहरूलाई फर्काएर, दृष्टिलाई भ्रूमध्यमा स्थिर गरेर, नासिकाभित्र प्राण र अपानको गति समान गरेर —",
         "“बाह्य विषयबाट फर्केर, दृष्टि भौंको बीचमा राखेर, श्वास समान र सन्तुलित बगाएर —”"),
"5.28": ("— इन्द्रिय, मन र बुद्धि संयत, मुक्तिमा तत्पर, इच्छा, भय र क्रोधरहित ऋषि — ऊ सधैं मुक्त छ।",
         "“— आत्मसंयमी, मोह, डर र क्रोधबाट मुक्त, मुक्तिका निम्ति समर्पित ऋषि — ऊ सधैंका निम्ति स्वतन्त्र छ।”"),
"5.29": ("मलाई यज्ञ र तपस्या भोग्ने, सबै लोकको महान् स्वामी, सबै प्राणीको मित्र जानेर — ऊ शान्ति प्राप्त गर्छ।",
         "“मलाई सबै अर्पण ग्रहण गर्ने, सबै लोकको स्वामी, हरेक प्राणीको मित्र भनेर चिन — र तिमीले शान्ति पाउनेछौ।”"),
"6.01": ("श्रीभगवान्ले भन्नुभयो: जसले फलको आशा नराखी आफ्नो कर्तव्य कर्म गर्छ — ऊ नै संन्यासी पनि हो, योगी पनि; अग्नि र क्रियारहित मात्र भएको व्यक्ति होइन।",
         "कृष्णले भन्नुभयो: “जसले फलमा नटाँसिएर आफ्नो कर्तव्य गर्छ — ऊ साँचो संन्यासी र योगी दुवै हो — अनुष्ठान त्याग्ने मात्र व्यक्ति होइन।”"),
"6.02": ("हे पाण्डुपुत्र, जसलाई संन्यास भनिन्छ, त्यसलाई नै योग जान; किनकि सङ्कल्प त्याग नगरेको व्यक्ति योगी हुँदैन।",
         "“जसलाई मानिसहरू संन्यास भन्छन्, त्यही योग हो — स्वार्थी योजना नछोडी कोही योगी हुन सक्दैन।”"),
"6.03": ("योगमा चढ्न चाहने ऋषिका निम्ति कर्म नै साधन भनिन्छ; चढिसकेकाका निम्ति शान्ति (उपरम) साधन भनिन्छ।",
         "“योगतिर चढ्न कर्म नै बाटो हो; एकपटक स्थापित भएपछि भित्री शान्ति नै बाटो बन्छ।”"),
"6.04": ("जब मानिस न विषयहरूमा आसक्त हुन्छ न कर्ममा, र सबै सङ्कल्प त्यागेको हुन्छ — तब ऊ योगमा चढेको भनिन्छ।",
         "“जब तिमी न भोगमा टाँसिन्छौ न काममा, सबै स्वार्थी लक्ष्य छोडेर — तब तिमी साँच्चै योगमा उक्लेका हुन्छौ।”"),
"6.05": ("आत्माद्वारा आत्मालाई उठाऊ, र आत्मालाई नढलाऊ; किनकि आत्मा नै आत्माको मित्र हो, र आत्मा नै आत्माको शत्रु हो।",
         "“आफैंलाई आफ्नै आत्माले माथि उठाऊ, कहिल्यै नडुब्न देऊ। आत्मा तिम्रो आफ्नै सबैभन्दा राम्रो मित्र हो — वा सबैभन्दा ठूलो शत्रु।”"),
"6.06": ("जसले आत्माद्वारा आत्मालाई जितेको छ, उसका निम्ति आत्मा मित्र हुन्छ; तर जसले आत्मालाई जितेको छैन, उसका निम्ति आत्मा शत्रुझैं विरोधी रहन्छ।",
         "“आफूलाई जित — आत्मा मित्र बन्छ; आफूलाई नजित — आत्मा शत्रु बन्छ।”"),
"6.07": ("आत्मजित, शान्त व्यक्ति परमात्मामा स्थित हुन्छ — जाडो-गर्मी, सुख-दुःख, मान-अपमानमा समान।",
         "“आत्मविजयी ऋषि, शान्त र सन्तुलित, जाडो-गर्मी, सुख-दुःख, प्रशंसा-निन्दामा एकनास रहन्छ।”"),
"6.08": ("जो ज्ञान र विज्ञानमा सन्तुष्ट, अचल, इन्द्रियजित छ, जसलाई माटो, ढुङ्गा र सुन समान छन् — ऊ युक्त भनिन्छ।",
         "“ज्ञानमा सन्तुष्ट, स्थिर, इन्द्रिय वशमा भएको, माटो, ढुङ्गा र सुनलाई एकै देख्ने — त्यस्तो व्यक्ति साँच्चै योगमा जोडिएको हुन्छ।”"),
"6.09": ("जो हितैषी, मित्र, शत्रु, उदासीन, मध्यस्थ, घृणा गर्ने, नातेदार र धार्मिक — सबैप्रति समान छ, ऊ नै श्रेष्ठ हुन्छ।",
         "“मित्र र शत्रु, तटस्थ र विरोधी, आफन्त र अपरिचित — सबैलाई समान हेर्ने — यस्तो व्यक्ति सबैभन्दा उच्च हुन्छ।”"),
"6.10": ("योगीले एकान्त ठाउँमा, एक्लै, मन र आत्मा संयत गरेर, आशा र परिग्रहरहित भएर निरन्तर अभ्यास गर्नुपर्छ।",
         "“एकान्त ठाउँमा एक्लै योगको अभ्यास गर — मन र हृदय वशमा, मोह र ममताबाट मुक्त।”"),
"6.11": ("शुद्ध भूमिमा आफ्ना निम्ति स्थिर आसन स्थापित गरेर — न धेरै अग्लो न धेरै होचो — वस्त्र, मृगछाला र कुशले ढाकेर,",
         "“सफा ठाउँमा दृढ आसन बनाऊ — न अग्लो न होचो — कपडा, छाला र पवित्र घाँसले बिछ्याएर —”"),
"6.12": ("मनलाई एकाग्र गरेर, मन र इन्द्रियका क्रियाहरूलाई रोकेर, त्यस आसनमा बसेर आत्मशुद्धिका निम्ति योगको अभ्यास गरोस्।",
         "“त्यहाँ बसेर मनलाई केन्द्रित गर, विचार र इन्द्रियलाई शान्त पार, र आफूलाई शुद्ध गर्न योगको अभ्यास गर।”"),
"6.13": ("शरीर, शिर र घाँटीलाई सीधा र अचल राखेर, आफ्नै नासिकाको अग्रभागमा दृष्टि स्थिर गरेर, वरिपरि नहेरी,",
         "“शरीर, शिर र घाँटी सीधा र स्थिर राख; दृष्टि नाकको टुप्पोमा गाड, वरिपरि नहेरी —”"),
"6.14": ("प्रसन्न मन, निर्भय, ब्रह्मचर्य व्रतमा दृढ, मन संयत, ममै विचारमा टिकेको — युक्त योगी मप्रति समर्पित भएर बसोस्।",
         "“शान्त र निर्भय, संयमी र आत्मनियन्त्रित, ममै विचारमा — मेरो भक्तिमा बसेर ध्यान गर।”"),
"6.15": ("यसरी सधैं आत्मालाई संयत गर्दै, संयत मनको योगीले ममा अवस्थित निर्वाणको शान्ति प्राप्त गर्छ।",
         "“यसरी अभ्यास गर्दा, शान्त मनको योगीले ममा विश्राम गर्ने मुक्तिको शान्ति पाउँछ।”"),
"6.16": ("हे अर्जुन, न धेरै खानेले योग पाउँछ, न बिल्कुल नखानेले; न धेरै सुत्नेले, न धेरै ब्यूँझनेले।",
         "“योग धेरै खाने वा भोकै बस्नेको होइन, न धेरै सुत्ने वा कहिल्यै नसुत्नेको — सबैमा सन्तुलन, अर्जुन।”"),
"6.17": ("जो आहार र विहारमा संयमित छ, कर्ममा संयमित छ, निद्रा र जागरणमा संयमित छ — उसका निम्ति योग दुःखको नाश गर्ने बन्छ।",
         "“खान, आराम, काम र निद्रामा सन्तुलित — यस्तो व्यक्तिका निम्ति योगले सबै कष्ट पगाल्छ।”"),
"6.18": ("जब सुसंस्कृत मन आत्मामै स्थिर हुन्छ, सबै कामनाका विषयहरूप्रति निःस्पृह हुन्छ — तब ऊ युक्त भनिन्छ।",
         "“जब तालिमप्राप्त मन आत्मामै बस्छ, हरेक लोभबाट मुक्त — त्यही योगमा साँच्चै स्थापित हुनु हो।”"),
"6.19": ("जसरी हावा नभएको ठाउँमा राखिएको बत्ती चलमलाउँदैन — संयत मनको, आत्मयोगको अभ्यास गर्ने योगीको यही उपमा भनिएको छ।",
         "“हावा नलाग्ने ठाउँको बत्ती कहिल्यै चलमलाउँदैन — त्यस्तै हुन्छ आत्मामा शान्त मन भएको योगी।”"),
"6.20": ("जसमा योगाभ्यासले मन शान्त हुन्छ, र आत्माद्वारा आत्मालाई देखेर मानिस आत्मामै सन्तुष्ट हुन्छ —",
         "“जब अभ्यासले मन शान्त हुन्छ, र भित्रको आत्मा देखेर तिमी आफ्नै आत्मामा रम्छौ —”"),
"6.21": ("— जसलाई इन्द्रियभन्दा परको बुद्धिले ग्रहण गरेर अनन्त सुखको रूपमा जानिन्छ, र जसमा स्थित भएर मानिस सत्यबाट चल्दैन —",
         "“— जब तिमी इन्द्रियभन्दा परको त्यो असीम आनन्द चाख्छौ, र कुनै कुराले तिमीलाई त्यसबाट चलाउन सक्दैन —”"),
"6.22": ("— जसलाई पाएर अरू कुनै लाभ श्रेष्ठ लाग्दैन, जसमा ठूलो दुःखले पनि विचलित गर्दैन — त्यो अवस्था योग भनिन्छ, दुःखसंयोगको विच्छेद।",
         "“— यस्तो लाभ जसभन्दा पर केही मायना हुँदैन, गहिरो शोकले पनि नहल्लिने — त्यही योग हो, सबै शोकको अन्त्य।”"),
"6.23": ("दुःखसंयोगको विच्छेदरूपी त्यो योग दृढ संकल्प र निरुत्साहित मनले अभ्यास गर्नुपर्छ।",
         "“यो योग — जसले तिमीलाई शोकबाट छुट्याउँछ — दृढ संकल्प र अथक हृदयले अभ्यास गर।”"),
"6.24": ("सङ्कल्पबाट जन्मेका सबै कामनाहरूलाई पूर्ण रूपमा त्यागेर, मनद्वारा नै चारैतिरबाट सम्पूर्ण इन्द्रिय-समूहलाई रोकेर —",
         "“सबै कल्पित इच्छाहरू छोड; मनले नै हरेक इन्द्रियलाई काबूमा ल्याऊ —”"),
"6.25": ("— बिस्तारै, क्रमशः, धैर्यले दृढ बुद्धिद्वारा शान्त हुँदै जाओस्; र मनलाई आत्मामै स्थिर गरेर अरू केही नसोचोस्।",
         "“— क्रमशः, संकल्पले दृढ बुद्धिले मनलाई आत्मामा विश्राम दिने गर — र अरू केही नसोच।”"),
"6.26": ("चञ्चल, अस्थिर मन जुन-जुन कारणले भड्किएर जान्छ, त्यहीबाट फर्काएर आत्माको वशमा ल्याओस्।",
         "“बेचैन मन जहाँ-जहाँ भड्किन्छ, त्यहीँबाट बारम्बार फर्काएर आत्माको नियन्त्रणमा ल्याऊ।”"),
"6.27": ("जसको मन शान्त छ, रज शान्त भएको छ, जो ब्रह्मभूत र निष्पाप भएको छ — त्यस योगीमा निश्चय नै परम आनन्द आउँछ।",
         "“ठूलो आनन्द आउँछ त्यो योगीमा — जसको मन शान्त, कामनाहरू शान्त, जो ब्रह्मभूत र निष्कलङ्क भइसकेको छ।”"),
"6.28": ("यसरी सधैं आत्मालाई संयत गर्ने, निष्पाप योगीले ब्रह्मसंयोगको अनन्त सुख सजिलै प्राप्त गर्छ।",
         "“यसरी सधैं अभ्यास गर्ने, शुद्ध योगीले ब्रह्मसँगको मिलनको असीम आनन्द सजिलै पाउँछ।”"),
"6.29": ("सबै प्राणीमा आत्मा र आत्मामा सबै प्राणी देख्ने, सबै कुरामा समान दृष्टि राख्ने — ऊ परम तत्त्व प्राप्त गर्छ।",
         "“सबैमा आत्मा र आत्मामा सबै देख्ने, सर्वत्र एकै देख्ने — यस्तो व्यक्ति सर्वोच्चमा पुग्छ।”"),
"6.30": ("जसले मलाई सर्वत्र देख्छ र सबै कुरा ममा देख्छ — उसका निम्ति म हराउँदिनँ, र ऊ पनि मबाट हराउँदैन।",
         "“जसले मलाई सबैमा र सबैलाई ममा देख्छ — म उसलाई कहिल्यै छोड्दिनँ, र ऊ पनि मलाई कहिल्यै छोड्दैन।”"),
"6.31": ("एकत्वमा स्थित, सबै प्राणीमा विद्यमान मेरो नै पूजा गर्ने योगी — त्यसैमा रहेर, जस्तोसुकै जीवनशैली भए पनि, ऊ ममै बाँच्छ।",
         "“जो योगी मलाई सबै प्राणीमा देख्छ र त्यहीं पूजा गर्छ — ऊ जे गरे पनि ममै बस्छ।”"),
"6.32": ("आत्मसादृश्यद्वारा सुख र दुःखमा सर्वत्र समान देख्ने — हे अर्जुन, ऊ नै परम योगी मानिन्छ।",
         "“जो अरूको सुख-दुःखलाई आफ्नैजस्तो महसुस गर्छ, सबैलाई समान देख्छ — ऊ नै महान् योगी हो, अर्जुन।”"),
"6.33": ("अर्जुनले भने: हे मधुसूदन, तपाईंले बताउनुभएको यो समत्वयोग — चञ्चलताका कारण यसको कुनै स्थिर आधार म देख्दिनँ।",
         "अर्जुन सोध्छन्: “तपाईंले वर्णन गर्नुभएको यो समबुद्धिको योग — यो कसरी टिक्छ, म देख्दिनँ, किनकि मन यति बेचैन छ।”"),
"6.34": ("हे कृष्ण, मन निश्चय नै चञ्चल, आवेगी, बलिष्ठ र अडिग छ; मलाई लाग्छ यसलाई रोक्नु हावा रोक्नुजस्तै कठिन छ।",
         "“मन जङ्गली, उथलपुथल, जिद्दी र बलियो छ — मलाई लाग्छ यसलाई काबू गर्नु हावा समात्नुजस्तै गाह्रो छ।”"),
"6.35": ("श्रीभगवान्ले भन्नुभयो: हे महाबाहो, मन चञ्चल र रोक्न कठिन छ भन्ने निश्चय हो; तर हे कुन्तीपुत्र, अभ्यास र वैराग्यद्वारा यसलाई रोक्न सकिन्छ।",
         "कृष्णले भन्नुभयो: “हो, मन चञ्चल र नियन्त्रण गर्न गाह्रो छ — तर अभ्यास र वैराग्यले यसलाई जित्न सकिन्छ।”"),
"6.36": ("आत्मा संयत नभएकाका निम्ति योग पाउन गाह्रो छ भन्ने मेरो धारणा छ; तर आत्मसंयमी, उचित साधनले प्रयत्न गर्नेले यसलाई पाउन सक्छ।",
         "“आत्मसंयम बिना योग धेरै कठिन छ; तर आत्मनियन्त्रित र उचित प्रयास गर्नेले यसलाई पाउनेछ।”"),
"6.37": ("अर्जुनले भने: हे कृष्ण, जो श्रद्धाले भरिएको तर आफूलाई नियन्त्रण गर्न नसकेको, जसको मन योगबाट च्युत भएको छ — योगमा सिद्धि नपाई — त्यो के गति पाउँछ?",
         "अर्जुन सोध्छन्: “जसले श्रद्धासाथ प्रयास गर्छ तर असफल हुन्छ — सिद्धिमा पुग्नुअघि नै जसको मन योगबाट खस्छ — त्यसको के हुन्छ, कृष्ण?”"),
"6.38": ("हे महाबाहो, दुवैबाट च्युत भएर, आधार बिना, ब्रह्मको मार्गमा मोहित भएर — ऊ च्यातिएको बादलझैं नष्ट हुँदैन र?",
         "“दुवै लोकबाट हराएर — के ऊ च्यातिएको बादलझैं नष्ट हुन्छ, केही नसमाती, ब्रह्मको बाटोमा अलमलिएर?”"),
"6.39": ("हे कृष्ण, तपाईंले नै मेरो यो सन्देह पूर्ण रूपमा मेट्नुपर्छ; यो सन्देह नष्ट गर्ने तपाईंबाहेक अरू कोही देखिँदैन।",
         "“कृपया मेरो यो सन्देह पूरै हटाउनुहोस्, कृष्ण — यसलाई समाधान गर्ने अरू कोही छैन।”"),
"6.40": ("श्रीभगवान्ले भन्नुभयो: हे पार्थ, न यस लोकमा न परलोकमा उसको विनाश हुन्छ; किनकि हे पुत्र, असल कर्म गर्ने कोही पनि दुर्गतिमा जाँदैन।",
         "कृष्णले भन्नुभयो: “कहिल्यै होइन, अर्जुन — न यहाँ न मृत्युपछि — यस्तो व्यक्ति नष्ट हुँदैन। असल गर्ने कोही नराम्रो अन्त्यमा पुग्दैन।”"),
"6.41": ("पुण्यकर्मीहरूका लोक प्राप्त गरेर, त्यहाँ असंख्य वर्ष बिताएर, योगबाट च्युत व्यक्ति शुद्ध र समृद्ध घरमा फेरि जन्मिन्छ।",
         "“ऊ सत्पुरुषहरूका लोकमा युगौंसम्म बस्छ, अनि शुद्ध र भाग्यशाली परिवारमा पुनर्जन्म लिन्छ।”"),
"6.42": ("वा ऊ बुद्धिमान् योगीहरूको घरमा जन्मिन्छ; साँच्चै, यस्तो जन्म यस संसारमा पाउन धेरै कठिन छ।",
         "“वा ऊ ज्ञानी योगीहरूका बीच जन्मिन्छ — यस्तो जन्म यस संसारमा पाउन धेरै गाह्रो छ।”"),
"6.43": ("हे कुरुनन्दन, त्यहाँ ऊ आफ्नो पूर्वशरीरको बुद्धि फेरि प्राप्त गर्छ, र त्यहीँबाट सिद्धिका निम्ति फेरि प्रयत्न गर्छ।",
         "“त्यहाँ उसको विगत जीवनको ज्ञान फर्कन्छ, र त्यही बिन्दुबाट ऊ सिद्धितिर अघि बढ्छ।”"),
"6.44": ("त्यही पूर्वाभ्यासले गर्दा ऊ अनिच्छाले पनि अघि बढ्छ; योग जान्न चाहने मात्रले पनि वेदको शब्दभन्दा माथि उक्लन्छ।",
         "“उसको पुरानो अभ्यासले उसलाई नचाहँदा पनि अगाडि बढाउँछ — योग जान्न चाहने मात्रले पनि शास्त्रको शब्दभन्दा पर जान्छ।”"),
"6.45": ("तर प्रयत्नपूर्वक अभ्यास गर्ने, पापबाट शुद्ध, धेरै जन्ममा क्रमशः सिद्ध भएको योगी त्यसपछि परम अवस्थामा पुग्छ।",
         "“तर इमान्दारीसाथ प्रयास गर्ने, पापबाट शुद्ध, धेरै जीवनमा परिपक्व भएको योगी — ऊ सर्वोच्च लक्ष्यमा पुग्छ।”"),
"6.46": ("योगी तपस्वीभन्दा श्रेष्ठ छ, ज्ञानीभन्दा पनि श्रेष्ठ मानिन्छ, र कर्मकाण्डीभन्दा पनि श्रेष्ठ; त्यसैले हे अर्जुन, योगी बन।",
         "“योगी तपस्वी, विद्वान् र अनुष्ठानी — सबैभन्दा माथि छ। त्यसैले, अर्जुन, योगी बन।”"),
"6.47": ("र सबै योगीहरूमा, जो श्रद्धाले भरिएर, आफ्नो अन्तरात्मा ममा स्थिर गरेर मेरो पूजा गर्छ — मेरो दृष्टिमा उसैलाई म सबैभन्दा युक्त मान्छु।",
         "“र सबै योगीहरूमा, जो गहिरो श्रद्धाले, आफ्नो सम्पूर्ण अस्तित्व ममा टिकाएर मेरो पूजा गर्छ — मेरो नजरमा उही सबैभन्दा ठूलो हो।”"),
"7.01": ("श्रीभगवान्ले भन्नुभयो: हे पार्थ, मनलाई ममा आसक्त गरेर, योगको अभ्यास गरेर र मेरो शरण लिएर — तिमीले कसरी, कुनै सन्देह बिना, मलाई पूर्ण रूपमा जान्नेछौ, त्यो सुन।",
         "कृष्णले भन्नुभयो: “मन ममा लगाऊ, योगको अभ्यास गर, मेरो शरण लेऊ — तब तिमीले मलाई पूरै चिन्नेछौ। त्यो कसरी, सुन।”"),
"7.02": ("म तिमीलाई यो ज्ञान र यसको विज्ञान (साक्षात्कार) नि:शेष रूपमा बताउनेछु; यसलाई जानेपछि यहाँ जान्न बाँकी अरू केही रहनेछैन।",
         "“म तिमीलाई यो ज्ञान — यसको प्रत्यक्ष अनुभवसँगै — पूरा सिकाउनेछु। यो जानेपछि सिक्न बाँकी अरू केही रहँदैन।”"),
"7.03": ("हजारौं मानिसमध्ये कोही एकले सिद्धिका निम्ति प्रयत्न गर्छ; र प्रयत्न गर्नेहरूमध्ये कोही एकले मलाई साँच्चै जान्दछ।",
         "“हजारौंमध्ये एकले सिद्धि खोज्छ; र सिद्ध हुनेहरूमध्ये एकले साँच्चै मलाई चिन्छ।”"),
"7.04": ("पृथ्वी, जल, अग्नि, वायु, आकाश, मन, बुद्धि र अहंकार — यसरी मेरो प्रकृति आठ भागमा विभक्त छ।",
         "“पृथ्वी, जल, अग्नि, वायु, आकाश, मन, बुद्धि र अहंकार — यी आठले मेरो अपर प्रकृति बनाउँछन्।”"),
"7.05": ("यो अपर प्रकृति हो; तर हे महाबाहो, यसभन्दा परको मेरो अर्को परा प्रकृति जान — जीवतत्त्व, जसद्वारा यो संसार धानिएको छ।",
         "“त्यो मेरो अपर प्रकृति हो। तर मेरो अझ उच्च प्रकृति पनि छ — जीवात्मा — जसद्वारा यो सम्पूर्ण संसार टिकेको छ।”"),
"7.06": ("यी दुई प्रकृतिहरू नै सबै प्राणीका गर्भ हुन् भनी जान; म नै सम्पूर्ण संसारको उत्पत्ति र विनाश पनि हुँ।",
         "“सबै कुरा मेरा यी दुई प्रकृतिबाट जन्मिन्छन्। म नै सम्पूर्ण ब्रह्माण्डको स्रोत र अन्त्य हुँ।”"),
"7.07": ("हे धनञ्जय, मभन्दा उच्च अरू केही छैन; यो सबै ममा गाँसिएको छ — जसरी धागोमा मोतीहरूको माला।",
         "“मभन्दा पर केही छैन। यो सबै ममा गाँसिएको छ, जसरी डोरीमा उनेका मणिहरू।”"),
"7.08": ("हे कुन्तीपुत्र, म जलमा रस हुँ; म चन्द्रमा र सूर्यको प्रकाश हुँ; सबै वेदमा पवित्र अक्षर ॐ हुँ; आकाशमा शब्द हुँ; पुरुषमा पौरुष हुँ।",
         "“म पानीको स्वाद हुँ, चन्द्रमा र सूर्यको प्रकाश, वेदहरूमा ॐ, आकाशमा ध्वनि, पुरुषत्वको शक्ति।”"),
"7.09": ("म पृथ्वीको शुद्ध गन्ध हुँ र अग्निको तेज; सबै प्राणीको जीवन र तपस्वीहरूको तपस्या पनि म नै हुँ।",
         "“म पृथ्वीको सुगन्ध हुँ, आगोको ताप, सबै प्राणीको जीवन, तपस्वीहरूको तपस्या।”"),
"7.10": ("सबै प्राणीको शाश्वत बीज मलाई नै जान; म बुद्धिमान्हरूको बुद्धि र तेजस्वीहरूको तेज हुँ।",
         "“मलाई सबैको शाश्वत बीज जान — ज्ञानीहरूको ज्ञान, तेजस्वीहरूको तेज।”"),
"7.11": ("र म बलवान्हरूको बल हुँ — कामना र आसक्तिरहित; हे भरतश्रेष्ठ, प्राणीहरूमा म धर्मविरुद्ध नभएको कामना हुँ।",
         "“म बलियाहरूको बल हुँ — लोभ र मोहरहित; र प्राणीहरूमा धर्मसँग मेल खाने इच्छा।”"),
"7.12": ("र जति पनि सात्त्विक, राजस वा तामस अवस्थाहरू छन् — ती सबै मबाटै हुन् भनी जान; तर म तिनमा छैन, ती ममा छन्।",
         "“सबै गुण — सत्त्व, रज, तम — मबाटै आउँछन्। तैपनि म तिनभन्दा पर छु, यद्यपि ती ममा विश्राम गर्छन्।”"),
"7.13": ("तीन गुणबाट बनेका यी अवस्थाहरूले मोहित भएर, यो सम्पूर्ण संसारले — तिनभन्दा पर, अविनाशी — मलाई चिन्दैन।",
         "“तीन गुणले मोहित भएर संसार मलाई चिन्दैन — जो तिनभन्दा पर, नित्य छु।”"),
"7.14": ("गुणहरूले बनेको मेरो यो दैवी माया पार गर्न गाह्रो छ; तर जो केवल मेरै शरण लिन्छन्, तिनीहरू यस मायाभन्दा पार हुन्छन्।",
         "“मेरो दिव्य माया पार गर्न गाह्रो छ — तर जो केवल ममै समर्पण हुन्छन्, ती यसभन्दा पर जान्छन्।”"),
"7.15": ("दुष्कर्मीहरू, मोहितहरू, नराधमहरू मेरो शरण आउँदैनन्; मायाले ज्ञान हराएकाहरू आसुरी स्वभावमा टाँसिन्छन्।",
         "“दुष्ट, मोहित, पतितहरू — मायाले ज्ञान खोसेका र आसुरी स्वभावका — मतिर फर्कदैनन्।”"),
"7.16": ("हे अर्जुन, चार प्रकारका असल कर्मीहरूले मेरो पूजा गर्छन्: दुःखी, ज्ञानको खोजी गर्ने, अर्थको खोजी गर्ने र ज्ञानी।",
         "“चार किसिमका असल मानिसहरूले मेरो पूजा गर्छन्: दुःखी, जिज्ञासु, महत्त्वाकाङ्क्षी र ज्ञानी।”"),
"7.17": ("तिनमा ज्ञानी, सधैं युक्त, एकनिष्ठ भक्त — उसैको सबैभन्दा राम्रो; किनकि म ज्ञानीका निम्ति अत्यन्त प्रिय छु, र ऊ मेरा निम्ति प्रिय छ।",
         "“तीमध्ये सबैभन्दा ज्ञानी — सधैं मसँग एक, एकचित्त — उत्तम हो। म उसका निम्ति गहिरो प्रिय छु, र ऊ मेरा निम्ति।”"),
"7.18": ("यी सबै उदार छन्; तर ज्ञानी मेरै स्वरूप हो, मेरो विचारमा; किनकि ऊ, आत्मायुक्त भएर, परम लक्ष्य ममै स्थित छ।",
         "“चारै जना श्रेष्ठ छन्, तर ज्ञानी मेरै स्वरूप हो — परम लक्ष्य ममै स्थापित भएर।”"),
"7.19": ("धेरै जन्मको अन्त्यमा, ज्ञानी मानिस 'वासुदेव नै सबै हो' भनी सोचेर मेरो शरण आउँछ; त्यो महात्मा अत्यन्त दुर्लभ हुन्छ।",
         "“धेरै जीवनपछि, ज्ञानीहरू 'वासुदेव नै सबै हुन्' जानेर मकहाँ आउँछन् — यस्तो महात्मा अत्यन्त दुर्लभ हुन्छ।”"),
"7.20": ("जसको ज्ञान कामनाले हरिएको छ, तिनीहरू आफ्नै स्वभावले बाध्य भई, यो वा त्यो विधि अपनाएर, अरू देवताहरूको शरण जान्छन्।",
         "“कामनाले बगाइएका मानिसहरू, आफ्नै प्रकृतिले बाँधिएर, विभिन्न नियम पछ्याउँदै अरू देवताको पूजा गर्छन्।”"),
"7.21": ("कुनै पनि भक्तले जुन देवरूपलाई श्रद्धासाथ पूजा गर्न चाहन्छ, म उसकै त्यो श्रद्धालाई स्थिर बनाउँछु।",
         "“भक्तले जुन पनि रूपलाई श्रद्धाले पूज्न चाहन्छ, म त्यही श्रद्धालाई दृढ र स्थिर बनाउँछु।”"),
"7.22": ("त्यो श्रद्धाले युक्त भएर ऊ त्यस देवताको पूजामा लाग्छ, र त्यसबाट आफ्ना इच्छित वस्तुहरू पाउँछ — जुन वास्तवमा मैले नै तोकेका हुन्छन्।",
         "“त्यो श्रद्धाले उसले पूजा गर्छ, र उसका इच्छाहरू पूरा हुन्छन् — यद्यपि पूरा गर्ने म नै हुँ।”"),
"7.23": ("तर ती पूजकहरूको फल सीमित हुन्छ; त्यो फल अल्पबुद्धिहरूकै हुन्छ। देवताका पूजकहरू देवतामा जान्छन्; मेरा भक्तहरू मकहाँ आउँछन्।",
         "“तर यस्तो पूजाले सीमित फल मात्र दिन्छ। देवपूजक देवतामा पुग्छन्; मेरा भक्तहरू मकहाँ पुग्छन्।”"),
"7.24": ("अज्ञानीहरू, मेरो परा प्रकृति — अविनाशी र अतुलनीय — नजानेर, अव्यक्त मलाई व्यक्त रूप धारण गरेको ठान्छन्।",
         "“मूर्खहरू मलाई — अव्यक्त — केवल प्रकट रूप मात्र ठान्छन्, मेरो उच्च, नित्य प्रकृति नजानेर।”"),
"7.25": ("योगमायाले ढाकिएको भएर म सबैलाई प्रकट हुँदिनँ; यो मोहित संसारले मलाई — अजन्मा, अविनाशी — चिन्दैन।",
         "“मेरो दिव्य शक्तिले लुकेको, म सबैलाई देखिँदिनँ; मोहित संसार मलाई — अजन्मा, नित्य — चिन्न असफल हुन्छ।”"),
"7.26": ("हे अर्जुन, म बितेका, अहिले भएका र आउने — सबै प्राणीलाई जान्दछु; तर मलाई कोही चिन्दैन।",
         "“म सबै प्राणीलाई जान्दछु — विगत, वर्तमान र भविष्य। तर मलाई साँच्चै कोही चिन्दैन।”"),
"7.27": ("इच्छा र द्वेषबाट उत्पन्न द्वन्द्वहरूको मोहले, हे भरतवंशी, हे शत्रुतापन, सबै प्राणीहरू जन्ममा नै मोहमा पर्छन्।",
         "“रुचि र अरुचिबाट जन्मेका द्वन्द्वहरूले सबै प्राणीलाई जन्मदेखि नै मोहित पार्छन्।”"),
"7.28": ("तर जसका पाप समाप्त भएका छन्, असल कर्म गर्ने ती मानिसहरू — द्वन्द्वको मोहबाट मुक्त — दृढ व्रतले मेरो पूजा गर्छन्।",
         "“जसका पाप सकिएका छन्, जसका कर्म असल छन् — द्वन्द्वको मोहबाट मुक्त ती दृढ संकल्पले मेरो पूजा गर्छन्।”"),
"7.29": ("जो बुढ्यौली र मृत्युबाट मुक्तिका निम्ति प्रयत्न गर्दै मेरो शरण लिन्छन् — तिनीहरू ब्रह्म, सम्पूर्ण अध्यात्म र सबै कर्म जान्दछन्।",
         "“जो बुढ्यौली र मृत्युबाट मुक्ति खोज्दै मेरो शरण लिन्छन् — तिनीहरू ब्रह्म, आत्मा र सम्पूर्ण कर्म चिन्न पुग्छन्।”"),
"7.30": ("जसले मलाई भूत, देवता र यज्ञका साथ जान्दछन् — तिनीहरू मृत्युकालमा पनि, स्थिर मन भएर, मलाई नै चिन्छन्।",
         "“जसले मलाई सबै प्राणी, सबै देवता र सबै यज्ञमा व्याप्त जान्दछन् — मृत्युको घडीमा पनि, स्थिर मनले, तिनीहरू मलाई चिन्छन्।”"),
"8.01": ("अर्जुनले भने: त्यो ब्रह्म के हो, अध्यात्म के हो, कर्म के हो, हे पुरुषोत्तम? अधिभूत के भनिन्छ, र अधिदैव के कहिन्छ?",
         "अर्जुन सोध्छन्: “ब्रह्म के हो? आत्मा के हो? कर्म के हो, कृष्ण? अधिभूत र अधिदैव के हुन्?”"),
"8.02": ("हे मधुसूदन, यस शरीरमा अधियज्ञ को हो र कसरी? र संयमीहरूले मृत्युकालमा तपाईंलाई कसरी चिन्न सक्छन्?",
         "“र यस शरीरमा अधियज्ञ के हो — र स्थिर मन भएकाहरूले मृत्युको घडीमा तपाईंलाई कसरी चिन्न सक्छन्?”"),
"8.03": ("श्रीभगवान्ले भन्नुभयो: अविनाशी ब्रह्म नै परम तत्त्व हो; आफ्नो स्वभाव अध्यात्म भनिन्छ; प्राणीहरूलाई जन्माउने सृष्टि-प्रेरणा कर्म भनिन्छ।",
         "कृष्णले भन्नुभयो: “अविनाशी नै परम ब्रह्म हो; आफ्नो अस्तित्व अध्यात्म हो; र सृष्टिको प्रेरणा कर्म हो।”"),
"8.04": ("अधिभूत क्षर (विनाशशील) स्वभाव हो; पुरुष अधिदैवत हो; हे देहधारीहरूमा श्रेष्ठ, यस शरीरमा म आफैं अधियज्ञ हुँ।",
         "“विनाशशील संसार अधिभूत हो; पुरुष अधिदैव हो; र यस शरीरमा म आफैं अधियज्ञ हुँ।”"),
"8.05": ("जसले अन्त्यकालमा केवल मलाई सम्झेर शरीर त्याग गर्छ — ऊ मेरो अवस्था प्राप्त गर्छ; यसमा कुनै सन्देह छैन।",
         "“जसले केवल मलाई सम्झेर शरीर छोड्छ, ऊ मेरै स्वरूपमा आउँछ — यसमा कुनै सन्देह छैन।”"),
"8.06": ("शरीर त्याग्दा अन्त्यकालमा जुन-जुन अवस्था सम्झिन्छ, त्यही अवस्थामा ऊ जान्छ — त्यही भावले सधैं व्याप्त भएर।",
         "“अन्तिम घडीमा तिमी जे सोच्छौ, त्यही बन्छौ — त्यही अन्तिम विचारले ढालेर।”"),
"8.07": ("त्यसैले सबै समय मलाई सम्झेर लड; मन र बुद्धि ममा अर्पण गरेर, तिमी निश्चय नै मकहाँ आउनेछौ।",
         "“त्यसैले सधैं मलाई सम्झेर युद्ध गर! मन र हृदय मलाई दिएर, तिमी निश्चय मकहाँ पुग्नेछौ।”"),
"8.08": ("अभ्यासयोगले युक्त, अरू कतै नजाने एकाग्र मनले — परम दिव्य पुरुषको चिन्तन गर्दै — ऊ त्यहाँ पुग्छ।",
         "“एकाग्र मनले अभ्यास गर्दै, परम दिव्य पुरुषको ध्यान गर्दै, योगी उहाँसम्म पुग्छ।”"),
"8.09": ("जो प्राचीन ऋषि, शासक, सूक्ष्मभन्दा सूक्ष्म, सबैको आधार, अचिन्त्य रूप, सूर्यझैं तेजस्वी, अन्धकारभन्दा पर — उहाँको ध्यान गर्छ —",
         "“जो प्राचीन द्रष्टा — सूक्ष्मभन्दा सूक्ष्म, सबैको आधार, अचिन्त्य रूप, अन्धकारभन्दा पर चम्कने — उहाँको चिन्तन गर्ने —”"),
"8.10": ("— मृत्युकालमा अविचलित मन, भक्ति र योगशक्तिले युक्त, भ्रूमध्यमा प्राण स्थिर गरेर — ऊ त्यो परम दिव्य पुरुषमा पुग्छ।",
         "“— मृत्युमा स्थिर मन, भक्ति र योगशक्तिले, भौंको बीचमा श्वास रोकेर — त्यो परम दिव्य पुरुषसम्म पुग्छ।”"),
"8.11": ("वेदज्ञहरूले अविनाशी भन्ने, इच्छारहित तपस्वीहरू प्रवेश गर्ने, जसका निम्ति तिनीहरू ब्रह्मचर्य गर्छन् — त्यो लक्ष्य म तिमीलाई संक्षेपमा भन्नेछु।",
         "“वेदका ज्ञानीहरूले घोषणा गरेको अविनाशी, इच्छारहित तपस्वीहरू प्रवेश गर्ने — त्यो लक्ष्य अब म तिमीलाई छोटकरीमा भन्छु।”"),
"8.12": ("शरीरका सबै ढोकाहरू रोकेर, मनलाई हृदयमा बन्द गरेर, प्राणलाई शिरमा स्थिर गरेर, योगधारणामा स्थित भएर —",
         "“शरीरका ढोकाहरू बन्द गरेर, मनलाई हृदयमा राखेर, श्वास शिरसम्म उठाएर — योग समाधिमा स्थित भएर —”"),
"8.13": ("— एकाक्षर ब्रह्म ॐ उच्चारण गर्दै, र मलाई सम्झँदै — जसले शरीर त्यागेर जान्छ, ऊ परम लक्ष्यमा पुग्छ।",
         "“— एकाक्षर ॐ जप गर्दै, मलाई सम्झँदै — जो यसरी शरीर छोड्छ, ऊ परम लक्ष्यमा पुग्छ।”"),
"8.14": ("हे पार्थ, जो सधैं एकाग्र मनले मलाई निरन्तर सम्झन्छ — त्यो सधैं युक्त योगीका निम्ति म सजिलै पाइन्छु।",
         "“जो सधैं, अविभाजित मनले, मलाई सम्झिरहन्छ — त्यो सदा-युक्त योगीका निम्ति म सजिलै पाइन्छु।”"),
"8.15": ("मकहाँ पुगेर, महात्माहरू फेरि जन्ममा फर्कदैनन् — दुःखको घर, अनित्य — तिनीहरू परम सिद्धि प्राप्त गरेका हुन्छन्।",
         "“मसम्म पुगेर, महात्माहरू दुःख र परिवर्तनको यस संसारमा फेरि फर्कदैनन् — तिनीहरू परम सिद्धिमा पुगेका हुन्छन्।”"),
"8.16": ("हे अर्जुन, ब्रह्मलोकदेखि तलका सबै लोकहरू फेरि फर्कन्छन्; तर हे कुन्तीपुत्र, मकहाँ पुगेपछि पुनर्जन्म हुँदैन।",
         "“ब्रह्माको लोकसम्मका सबै संसार घुमेर फर्कन्छन्; तर जो मसम्म पुग्छ, ऊ फेरि जन्मिँदैन।”"),
"8.17": ("जसले ब्रह्माको दिन हजार युगमा समाप्त हुन्छ र रात हजार युगमा — भनी जान्दछन्, तिनीहरू दिन-रात जान्दछन्।",
         "“जसले हजार युग ब्रह्माको दिन र हजार युग उनको रात हुन्छ भनी जान्दछन् — तिनीहरू दिव्य समयको माप जान्दछन्।”"),
"8.18": ("दिनको आगमनमा अव्यक्तबाट सबै व्यक्त वस्तुहरू उत्पन्न हुन्छन्; रातको आगमनमा तिनीहरू अव्यक्तमै विलीन हुन्छन्।",
         "“ब्रह्माको दिनको उदयमा सबै प्राणी अव्यक्तबाट उठ्छन्; उनको रातमा फेरि त्यसैमा विलीन हुन्छन्।”"),
"8.19": ("प्राणीहरूको यही समूह, बारम्बार उत्पन्न भएर, रातको आगमनमा विलीन हुन्छ, र दिनको आगमनमा फेरि उत्पन्न हुन्छ।",
         "“यो प्राणी-समूह बारम्बार जन्मेर रातमा पग्लिन्छ र दिनको उदयमा फेरि देखा पर्छ।”"),
"8.20": ("तर यस अव्यक्तभन्दा पर अर्को शाश्वत अव्यक्त छ — जो सबै प्राणीहरू नष्ट हुँदा पनि नष्ट हुँदैन।",
         "“तर यस अव्यक्तभन्दा पर अर्को, नित्य अव्यक्त छ — जो सबै प्राणी बिते पनि रहिरहन्छ।”"),
"8.21": ("त्यो अव्यक्त नै अविनाशी भनिन्छ; तिनीहरू यसलाई परम लक्ष्य भन्छन्; जुन पाएर फर्कदैनन् — त्यही मेरो परम धाम हो।",
         "“त्यही अविनाशी हो, परम लक्ष्य। त्यसमा पुगेर कोही फर्कदैन — त्यो मेरो सर्वोच्च निवास हो।”"),
"8.22": ("हे पार्थ, त्यो परम पुरुष अनन्य भक्तिले मात्र प्राप्त गर्न सकिन्छ; जसमा सबै प्राणी बस्छन्, र जसद्वारा यो सबै व्याप्त छ।",
         "“त्यो परम पुरुष एकनिष्ठ भक्तिले पुगिन्छ; सबै प्राणी उहाँमा बस्छन्, र उहाँले सबै व्याप्त गर्नुहुन्छ।”"),
"8.23": ("हे भरतश्रेष्ठ, अब म त्यो समय बताउँछु जसमा योगीहरू मरेर फर्कदैनन्, र जुन समयमा फर्कन्छन्।",
         "“अब म तिमीलाई, अर्जुन, प्रस्थानका समय बताउँछु — नफर्कने बाटो र फर्कने बाटो।”"),
"8.24": ("अग्नि, ज्योति, दिन, शुक्ल पक्ष, उत्तरायणका छ महिना — त्यस मार्गबाट गएर ब्रह्मज्ञहरू ब्रह्ममा पुग्छन्।",
         "“अग्नि र प्रकाशको बाटो, दिन र शुक्ल पक्ष र उत्तरायणको — ब्रह्मज्ञहरू यस बाटोबाट ब्रह्ममा जान्छन्।”"),
"8.25": ("धुवाँ, रात, कृष्ण पक्ष, दक्षिणायनका छ महिना — त्यस बाटोबाट चन्द्रलोकको ज्योति प्राप्त गरेर योगी फर्कन्छ।",
         "“धुवाँ र रातको बाटो, कृष्ण पक्ष र दक्षिणायनको — यस बाटोबाट योगी चन्द्रलोकको ज्योतिमा पुगेर फर्कन्छ।”"),
"8.26": ("यी दुई बाटो — शुक्ल र कृष्ण — संसारका सनातन मार्ग हुन्; एउटाबाट बिना फिर्ती जान्छ, अर्कोबाट फेरि फर्कन्छ।",
         "“यी दुई बाटो — उज्यालो र अन्धकार — संसारमा सनातन छन्। एउटा नफर्किनेतिर लैजान्छ, अर्कोले फर्काउँछ।”"),
"8.27": ("हे पार्थ, यी दुई बाटो जानेर योगी कहिल्यै मोहित हुँदैन; त्यसैले, हे अर्जुन, सबै समय योगमा युक्त रह।",
         "“दुवै बाटो जानेर योगी कहिल्यै भ्रमित हुँदैन — त्यसैले, अर्जुन, सधैं योगमा स्थिर रह।”"),
"8.28": ("वेद, यज्ञ, तपस्या र दानमा जति पुण्यफल भनिएको छ — ती सबै जान्ने योगी त्यो सबैभन्दा माथि उठेर परम आदिम धाममा पुग्छ।",
         "“यो सत्य जान्ने योगी वेद, यज्ञ, तप र दानका सबै पुण्यभन्दा माथि उठ्छ — र परम, आदिम निवासमा पुग्छ।”"),
"9.01": ("श्रीभगवान्ले भन्नुभयो: दोष नदेख्ने तिमीलाई म यो सबैभन्दा गोप्य रहस्य बताउनेछु — ज्ञान साक्षात्कारसहित; यसलाई जानेर तिमी पापबाट मुक्त हुनेछौ।",
         "कृष्णले भन्नुभयो: “किनकि तिमी इमान्दार छौ, अर्जुन, म तिमीलाई सबैभन्दा गहिरो रहस्य सिकाउनेछु — ज्ञान यसको प्रत्यक्ष अनुभवसहित। यो जानेर तिमी सबै पापबाट मुक्त हुनेछौ।”"),
"9.02": ("यो राजविद्या हो, राजगुह्य हो, परम पवित्र, प्रत्यक्ष अनुभवयोग्य, धर्मयुक्त, अभ्यास गर्न धेरै सजिलो र अविनाशी हो।",
         "“यो ज्ञान र रहस्यको राजा हो — सबैभन्दा शुद्ध, प्रत्यक्ष देखिने, धर्मसँग मेल खाने, पछ्याउन सजिलो र नित्य।”"),
"9.03": ("यस धर्ममा श्रद्धा नराख्ने मानिसहरू, हे शत्रुतापन, मकहाँ नपुगी मृत्यु र पुनर्जन्मको बाटोमा फर्कन्छन्।",
         "“यस शिक्षामा श्रद्धा नराख्नेहरू मृत्यु र पुनर्जन्मको बाटोमा फर्कन्छन्, कहिल्यै मकहाँ पुग्दैनन्।”"),
"9.04": ("मेरो अव्यक्त रूपले यो सम्पूर्ण संसार मद्वारा व्याप्त छ; सबै प्राणीहरू ममा बस्छन्, तर म तिनमा समाहित छैन।",
         "“म आफ्नो अव्यक्त रूपले यो सम्पूर्ण संसारलाई व्याप्त गर्छु। सबै प्राणी ममा बस्छन्, तैपनि म तिनमा बस्दिनँ।”"),
"9.05": ("र प्राणीहरू ममा बस्दैनन् — मेरो दिव्य योग हेर! म सबै प्राणीलाई धान्छु तर अलग रहन्छु, र मेरो आत्मा नै प्राणीहरूको स्रोत हो।",
         "“प्राणीहरू साँच्चै ममा बस्दैनन् — मेरो दिव्य शक्ति हेर! म सबै प्राणीलाई धान्छु, तर अलग रहन्छु; म नै तिनको स्रोत हुँ।”"),
"9.06": ("जसरी ठूलो, सधैं चलायमान हावा आकाशमा रहन्छ, त्यसरी नै सबै प्राणीहरू ममा रहन्छन् — यो जान।",
         "“जसरी ठूलो हावा जताततै चल्छ तैपनि आकाशमै बस्छ, त्यसरी सबै प्राणी ममा बस्छन् — यो बुझ।”"),
"9.07": ("हे कुन्तीपुत्र, कल्पको अन्त्यमा सबै प्राणीहरू मेरो प्रकृतिमा फर्कन्छन्; कल्पको सुरुमा म तिनलाई फेरि बाहिर पठाउँछु।",
         "“ब्रह्माण्डीय युगको अन्त्यमा सबै प्राणी मेरो प्रकृतिमा विलीन हुन्छन्; युगको उदयमा म तिनलाई फेरि पठाउँछु।”"),
"9.08": ("आफ्नै प्रकृतिलाई समातेर, म प्राणीहरूको यो सम्पूर्ण समूहलाई बारम्बार बाहिर पठाउँछु — प्रकृतिको शक्तिमा असहाय भएका।",
         "“आफ्नै प्रकृतिद्वारा म यो सम्पूर्ण प्राणी-समूहलाई बारम्बार प्रकट गर्छु — प्रकृतिको अधीनमा असहाय प्राणीहरू।”"),
"9.09": ("हे धनञ्जय, यी कर्महरूले मलाई बाँध्दैनन्, किनकि म तिनमा आसक्त नभई, उदासीन बसेको छु।",
         "“यी सबैले मलाई बाँध्दैनन्, अर्जुन — म आसक्तिरहित, बेपरवाह दर्शकझैं अलग बस्छु।”"),
"9.10": ("मेरो अधीनमा, प्रकृतिले चर र अचर — सबै उत्पन्न गर्छे; यसै कारण, हे कुन्तीपुत्र, संसार घुमिरहन्छ।",
         "“मेरो निर्देशनमा प्रकृतिले चल र अचल — सबै उत्पादन गर्छे; त्यसैले संसार घुमिरहन्छ।”"),
"9.11": ("मोहितहरू, मेरो परम अस्तित्व नजानेर, मानव रूप धारण गरेको मलाई हेला गर्छन्।",
         "“मूर्खहरू, मेरो उच्च प्रकृति नदेखेर, मानव शरीर लिएको मलाई तुच्छ ठान्छन्।”"),
"9.12": ("व्यर्थ आशा, व्यर्थ कर्म र व्यर्थ ज्ञान भएका, अविवेकीहरू — ती मोहित, राक्षसी र आसुरी स्वभावमा टाँसिन्छन्।",
         "“तिनका आशा, कर्म र विद्या सबै व्यर्थ हुन्छन्; अलमलिएर हराएर ती भ्रमित, आसुरी प्रकृतिलाई पछ्याउँछन्।”"),
"9.13": ("तर हे पार्थ, महात्माहरू दैवी प्रकृतिको शरण लिएर, प्राणीहरूको अविनाशी स्रोत मलाई जानेर, अविभाजित मनले मेरो पूजा गर्छन्।",
         "“तर उदार आत्माहरू, अर्जुन, दैवी प्रकृतितिर फर्केर एकचित्त भई, सबैको शाश्वत स्रोत मलाई जानेर मेरो पूजा गर्छन्।”"),
"9.14": ("सधैं मेरो स्तुति गर्दै, दृढ व्रतले प्रयत्न गर्दै, भक्तिसाथ मलाई नमस्कार गर्दै, सधैं युक्त भएर — तिनीहरू मेरो पूजा गर्छन्।",
         "“सधैं मेरो प्रशंसा गाउँदै, दृढ संकल्पले प्रयास गर्दै, भक्तिमा मलाई निहुरेर — सधैं एक भएकाहरूले मेरो पूजा गर्छन्।”"),
"9.15": ("र अरूहरू ज्ञानयज्ञले — मलाई एक, अनेक, र सर्वत्र मुख भएको विराट रूपमा पूजा गर्दै — मेरो उपासना गर्छन्।",
         "“अरूले ज्ञानको अर्पण चढाउँछन् — मलाई एक, अनेक, र सबैतिर फैलिएको दिव्य रूपमा पूजेर।”"),
"9.16": ("म क्रिया हुँ, म यज्ञ हुँ, म पितृलाई दिइने स्वधा हुँ, म औषधि हुँ; म मन्त्र हुँ, म घिउ हुँ, म अग्नि हुँ, म आहुति हुँ।",
         "“म अनुष्ठान, अर्पण, पितृ-तर्पण, औषधि, मन्त्र, घिउ, आगो र दान — सबै हुँ।”"),
"9.17": ("म यस संसारको पिता, माता, धर्ता र पितामह हुँ; म जान्नुपर्ने वस्तु, पवित्रकर्ता, प्रणव ॐ, र ऋक्, साम र यजु हुँ।",
         "“म संसारको पिता र माता, यसको आधार र पितामह हुँ; म जान्नयोग्य, पवित्रकर्ता, ॐ र तीनै वेद हुँ।”"),
"9.18": ("म लक्ष्य, धर्ता, स्वामी, साक्षी, आश्रय, शरण र मित्र हुँ; उत्पत्ति, विनाश, आधार, भण्डार र शाश्वत बीज हुँ।",
         "“म लक्ष्य, वाहक, स्वामी, साक्षी, घर, शरण र मित्र हुँ — सबैको स्रोत, अन्त्य, विश्राम, भण्डार र अमर बीज।”"),
"9.19": ("म ताप दिन्छु; म वर्षा रोक्छु र पठाउँछु; म अमरत्व पनि हुँ र मृत्यु पनि; हे अर्जुन, म सत् पनि हुँ र असत् पनि।",
         "“म ताप दिन्छु; म वर्षा रोक्छु र बर्साउँछु। म जीवन र मृत्यु, सत्ता र असत्ता हुँ, अर्जुन।”"),
"9.20": ("तीन वेदका ज्ञाताहरू, सोमपान गरेर, पापबाट शुद्ध भएर, यज्ञद्वारा मेरो पूजा गर्दै, स्वर्गको मार्ग माग्छन्; इन्द्रलोक प्राप्त गरेर तिनीहरू स्वर्गका दिव्य सुख भोग्छन्।",
         "“वेदका अनुष्ठानीहरू, सोम पिएर र पापबाट शुद्ध भएर, यज्ञद्वारा मेरो पूजा गरी स्वर्ग पाउँछन्; इन्द्रको लोकमा दिव्य आनन्द भोग्छन्।”"),
"9.21": ("विशाल स्वर्गलोक भोगेर, पुण्य सकिएपछि तिनीहरू मर्त्यलोकमा फर्कन्छन्; यसरी तीन वेदको धर्म पछ्याउँदै, कामना चाहनेहरू आउँछन् र जान्छन्।",
         "“पुण्य सकिएपछि, विशाल स्वर्गीय सुख भोगेर, तिनीहरू मर्त्य संसारमा फर्कन्छन् — कामनाले बाँधिएर सधैं आउने-जाने गर्छन्।”"),
"9.22": ("जसले मलाई मात्र सम्झेर, सधैं युक्त भएर मेरो पूजा गर्छन् — ती सधैं भक्तहरूका निम्ति, नपाएको कुरा म आफैं पुर्‍याउँछु, र पाएको कुरा जोगाउँछु।",
         "“जसले एकनिष्ठ भक्तिले, सधैं मसँग एक भएर मेरो पूजा गर्छन् — तिनको अभाव म आफैं पुरा गर्छु र तिनको धन जोगाउँछु।”"),
"9.23": ("अरू देवताहरूप्रति समर्पित भएर श्रद्धासाथ तिनको पूजा गर्नेहरूले पनि — हे कुन्तीपुत्र — मलाई नै पूजा गर्छन्, यद्यपि विधिपूर्वक होइन।",
         "“अरू देवताका भक्तहरू पनि, श्रद्धाले तिनको पूजा गर्दा, वास्तवमा मेरै पूजा गर्छन् — यद्यपि उचित विधिबाट होइन।”"),
"9.24": ("किनकि म नै सबै यज्ञको भोक्ता र स्वामी हुँ; तर तिनीहरूले मलाई साँच्चै चिन्दैनन्, र त्यसैले झर्छन्।",
         "“म नै हरेक अर्पणको ग्रहणकर्ता र स्वामी हुँ। तर तिनीहरू मलाई साँच्चै चिन्दैनन्, र त्यसैले पतन हुन्छन्।”"),
"9.25": ("देवताका पूजक देवतामा जान्छन्; पितृका पूजक पितृमा; भूतका पूजक भूतमा; तर मेरा पूजकहरू मकहाँ आउँछन्।",
         "“देव-पूजक देवतामा, पितृ-पूजक पितृमा, भूत-पूजक भूतमा पुग्छन् — तर मेरा भक्तहरू मकहाँ आउँछन्।”"),
"9.26": ("जसले भक्तिले मलाई पात, फूल, फल वा पानी चढाउँछ — शुद्ध हृदयको त्यो अर्पण म स्वीकार गर्छु।",
         "“मलाई प्रेमले एउटा पात, फूल, फल वा पानी देऊ — शुद्ध हृदयको त्यो अर्पण म ग्रहण गर्छु।”"),
"9.27": ("हे कुन्तीपुत्र, जे-जे गर्छौ, जे-जे खान्छौ, जे-जे चढाउँछौ, जे-जे दान गर्छौ, जे-जे तपस्या गर्छौ — ती सबै मेरो अर्पणका रूपमा गर।",
         "“जे-जे गर्छौ, खान्छौ, चढाउँछौ, दान दिन्छौ वा तप गर्छौ — सबै मलाई अर्पण गर।”"),
"9.28": ("यसरी तिमी असल र नराम्रो फल दिने कर्महरूको बन्धनबाट मुक्त हुनेछौ; संन्यासयोगले युक्त आत्मा भएर, मुक्त भएर — तिमी मकहाँ आउनेछौ।",
         "“यसो गरेर तिमी कर्म र यसका असल-नराम्रो फलका बन्धनबाट मुक्त हुन्छौ; योगमा त्याग गरेर, स्वतन्त्र भएर — तिमी मकहाँ आउँछौ।”"),
"9.29": ("म सबै प्राणीप्रति समान छु; कोही मेरा प्रिय वा अप्रिय छैन; तर जसले भक्तिले मेरो पूजा गर्छन् — तिनीहरू ममा छन्, र म तिनमा छु।",
         "“म सबैप्रति समान छु — कोही मेरा प्रिय वा अप्रिय छैन। तैपनि जसले भक्तिले मेरो पूजा गर्छन् — ती ममा बस्छन्, र म तिनमा।”"),
"9.30": ("अति दुष्ट आचरणको मानिसले पनि यदि एकनिष्ठ भक्तिले मेरो पूजा गर्छ भने, ऊ असल नै मानिनुपर्छ, किनकि उसको संकल्प ठीक छ।",
         "“सबैभन्दा दुष्ट व्यक्तिले पनि यदि अविभाजित प्रेमले मेरो पूजा गर्छ भने, उसलाई असलमै गनिनुपर्छ — किनकि उसको संकल्प सही छ।”"),
"9.31": ("ऊ छिट्टै धर्मात्मा बन्छ र स्थायी शान्ति प्राप्त गर्छ; हे कुन्तीपुत्र, निश्चय जान: मेरो भक्त कहिल्यै नष्ट हुँदैन।",
         "“ऊ चाँडै धार्मिक बन्छ र दिगो शान्तिमा पुग्छ। निश्चय जान: मेरो भक्त कहिल्यै बरबाद हुँदैन।”"),
"9.32": ("हे पार्थ, मेरो शरण लिनेहरू — पापी जन्मका, स्त्री, व्यापारी र मजदुरहरू पनि — ती पनि परम लक्ष्यमा पुग्छन्।",
         "“मेरो शरणमा आउने सबै — नीच जन्मका, स्त्री, व्यापारी र मजदुर पनि — सर्वोच्च लक्ष्यमा पुग्छन्।”"),
"9.33": ("पवित्र ब्राह्मण र समर्पित राजर्षिहरूको त कुरै के! यस अनित्य, सुखरहित संसारमा आएर, मेरो पूजा गर।",
         "“शुद्ध ब्राह्मण र समर्पित राजा-ऋषिहरूको त कुरै के! यस क्षणभंगुर, शोकमय संसारमा, मेरो पूजा गर।”"),
"9.34": ("मन ममा लगाऊ, मेरो भक्त बन, मलाई अर्पण गर, मलाई नमस्कार गर — यसरी आत्मालाई ममा युक्त गरेर, ममै तत्पर भएर, तिमी निश्चय मकहाँ आउनेछौ।",
         "“मन ममा राख, मेरो भक्त बन, मेरो पूजा गर, मलाई नमस्कार गर — पूर्ण रूपमा ममै समर्पित भएर, तिमी निश्चय मकहाँ पुग्नेछौ।”"),
"10.01": ("श्रीभगवान्ले भन्नुभयो: हे महाबाहो, फेरि सुन मेरा परम वचनहरू, जुन म तिमीलाई, प्रिय, तिम्रो हित चाहेर भन्छु।",
         "कृष्णले भन्नुभयो: “फेरि सुन, महाबाहु अर्जुन, मेरो सर्वोच्च शिक्षा — जुन म प्रेमले, तिम्रो कल्याणका निम्ति दिन्छु।”"),
"10.02": ("न देवताका समूहहरू न महर्षिहरूले मेरो उत्पत्ति जान्दछन्; किनकि म सबै तरिकाले देवता र महर्षिहरूको सुरुवात हुँ।",
         "“न देवताहरू न महान् ऋषिहरूले म कहाँबाट आएँ भनी जान्दछन् — म नै ती सबैको स्रोत हुँ।”"),
"10.03": ("जसले मलाई अजन्मा, सुरुवातरहित, संसारको महान् स्वामी जान्दछ — मर्त्यहरूमा अमोहित, ऊ सबै पापबाट मुक्त हुन्छ।",
         "“जसले मलाई अजन्मा, आदिरहित, सबै लोकका स्वामी जान्दछ — ऊ फेरि कहिल्यै अलमलिँदैन, र उसका सबै पाप झर्छन्।”"),
"10.04": ("बुद्धि, ज्ञान, असम्मोह, क्षमा, सत्य, संयम, शान्ति — सुख, दुःख, जन्म, मृत्यु, भय र अभय,",
         "“समझ, ज्ञान, स्पष्टता, धैर्य, सत्य, आत्मसंयम, शान्ति — सुख, शोक, जन्म, मृत्यु, डर र साहस,”"),
"10.05": ("अहिंसा, समता, सन्तोष, तप, दान, कीर्ति र अपकीर्ति — प्राणीहरूका यी विविध अवस्थाहरू मबाटै उत्पन्न हुन्छन्।",
         "“— अहिंसा, समदृष्टि, सन्तोष, तपस्या, दान, प्रसिद्धि र अपमान — प्राणीका यी सबै गुणहरू मबाटै आउँछन्।”"),
"10.06": ("सात महर्षिहरू, चार प्राचीन मनुहरू — मेरो मनबाट जन्मेका — तिनीहरूबाट यस संसारका प्राणीहरू उत्पन्न हुन्छन्।",
         "“सात प्राचीन ऋषि र चार मनुहरू — मेरै विचारबाट जन्मेका — तिनीहरूबाट यस संसारका सबै प्राणी उत्पन्न हुन्छन्।”"),
"10.07": ("जसले मेरो यो विभूति र योगलाई साँच्चै जान्दछ, ऊ अविचलित योगले मसँग जोडिन्छ — यसमा कुनै सन्देह छैन।",
         "“जसले साँच्चै मेरा विभूतिहरू र मेरो शक्ति चिन्छ, ऊ अटल योगले मसँग जोडिन्छ — यसमा कुनै सन्देह छैन।”"),
"10.08": ("म सबैको स्रोत हुँ; सबै कुरा मबाटै अघि बढ्छ। यो जानेर ज्ञानीहरू, भक्तिले भरिएर, मेरो पूजा गर्छन्।",
         "“म सबैको उत्पत्ति हुँ; सबै मबाटै बग्छ। ज्ञानीहरू, यो जानेर, प्रेमसाथ मेरो पूजा गर्छन्।”"),
"10.09": ("तिनका विचार ममा, जीवन मलाई दिइएको, एक-अर्कालाई ज्ञान दिँदै, सधैं मेरै कुरा गर्दै — तिनीहरू सन्तुष्ट र आनन्दित हुन्छन्।",
         "“मन ममा, जीवन मप्रति समर्पित, एक-अर्कालाई सिकाउँदै र सधैं मेरै कुरा गर्दै — तिनीहरू तृप्त र प्रसन्न हुन्छन्।”"),
"10.10": ("तिनलाई, सधैं समर्पित, प्रेमसाथ मेरो पूजा गर्नेहरूलाई, म बुद्धियोग दिन्छु — जसद्वारा तिनीहरू मकहाँ आउँछन्।",
         "“सधैं एक भएर भक्तिले मेरो पूजा गर्नेहरूलाई म विवेकयोग दिन्छु — जसद्वारा तिनीहरू मकहाँ पुग्छन्।”"),
"10.11": ("तिनीहरूप्रति दयाले, तिनको हृदयमा बसेर, म तिनको हृदयको अज्ञानजन्य अन्धकारलाई ज्ञानरूपी चम्किलो बत्तीले नष्ट गर्छु।",
         "“करुणाले, तिनीभित्र बसेर, म तिनको अज्ञानको अन्धकारलाई ज्ञानको उज्यालो बत्तीले मेटाउँछु।”"),
"10.12": ("अर्जुनले भने: तपाईं परम ब्रह्म, परम ज्योति, परम पवित्र हुनुहुन्छ; नित्य दिव्य पुरुष, आदि देवता, अजन्मा र सर्वव्यापी।",
         "अर्जुन भन्छन्: “तपाईं परम ब्रह्म, सर्वोच्च आश्रय, सबैभन्दा शुद्ध हुनुहुन्छ; नित्य दिव्य पुरुष, पहिलो देवता, अजन्मा र सर्वत्र।”"),
"10.13": ("यसरी ऋषिहरूले तपाईंलाई भन्छन् — दिव्य ऋषि नारद, असित, देवल, व्यास — र तपाईं आफैं पनि मलाई भन्नुहुन्छ।",
         "“सबै ऋषिहरू यसरी भन्छन् — नारद, असित, देवल, व्यास — र तपाईं आफैंले पनि मलाई पुष्टि गर्नुहुन्छ।”"),
"10.14": ("हे केशव, तपाईंले भन्नुभएको यो सबै म सत्य मान्छु; हे प्रभु, न देवता न दानवहरूले तपाईंको प्रकट रूप जान्दछन्।",
         "“तपाईंले भन्नुभएको सबै म विश्वास गर्छु, केशव। न देवता न दानवले, हे प्रभु, तपाईं कसरी प्रकट हुनुहुन्छ भनी जान्न सक्छन्।”"),
"10.15": ("हे परम पुरुष, तपाईं आफैंले आफूलाई आफैंले चिन्नुहुन्छ — हे प्राणीका स्रोत, प्राणीका स्वामी, देवताका देवता, संसारका स्वामी!",
         "“केवल तपाईं आफैंले आफूलाई चिन्नुहुन्छ, हे सर्वोच्च पुरुष — सबैका सृष्टिकर्ता, देवताका देवता, ब्रह्माण्डका स्वामी!”"),
"10.16": ("यी सबै लोकहरूलाई व्याप्त गरेर रहने तपाईंका दिव्य विभूतिहरू मलाई बिना बाँकी भन्नुहोस्।",
         "“कृपया तपाईंका दिव्य विभूतिहरू पूरै भन्नुहोस् — जसद्वारा तपाईं यी सबै लोकलाई व्याप्त गरेर रहनुहुन्छ।”"),
"10.17": ("हे योगी, सधैं तपाईंको चिन्तन गर्दै म तपाईंलाई कसरी चिनूँ? र हे प्रभु, कुन-कुन रूपमा तपाईंको ध्यान गर्नुपर्छ?",
         "“सधैं तपाईंलाई सम्झेर म तपाईंलाई कसरी जान्न सक्छु? कुन-कुन रूपमा, हे प्रभु, म तपाईंको ध्यान गरूँ?”"),
"10.18": ("हे जनार्दन, तपाईंको योग र विभूति फेरि, विस्तारमा भन्नुहोस्; तपाईंको अमृत सुन्दा म कहिल्यै तृप्त हुँदिनँ।",
         "“तपाईंको शक्ति र विभूतिहरू फेरि, विस्तृत रूपमा भन्नुहोस्, जनार्दन — यो अमृत पिउँदा म कहिल्यै अघाउँदिनँ।”"),
"10.19": ("श्रीभगवान्ले भन्नुभयो: हो, म तिमीलाई मेरा दिव्य विभूतिहरू बताउनेछु — मुख्य-मुख्य, हे कुरुश्रेष्ठ; किनकि मेरो विस्तारको अन्त्य छैन।",
         "कृष्णले भन्नुभयो: “म तिमीलाई मेरा दिव्य विभूतिहरू बताउनेछु — मुख्य-मुख्य, अर्जुन; किनकि मेरो विस्तारको कुनै अन्त्य छैन।”"),
"10.20": ("हे गुडाकेश, म सबै प्राणीको हृदयमा बस्ने आत्मा हुँ; म नै सबै प्राणीको आदि, मध्य र अन्त्य हुँ।",
         "“म सबै प्राणीको हृदयमा बसेको आत्मा हुँ; म नै तिनको आदि, मध्य र अन्त्य हुँ।”"),
"10.21": ("आदित्यहरूमा म विष्णु हुँ; ज्योतिहरूमा तेजस्वी सूर्य; मरुत्हरूमा म मरीचि हुँ; नक्षत्रहरूमा म चन्द्रमा हुँ।",
         "“आदित्यहरूमा म विष्णु; ज्योतिहरूमा दनदनाउने सूर्य; हावाहरूमा मरीचि; ताराहरूमा चन्द्रमा।”"),
"10.22": ("वेदहरूमा म सामवेद हुँ; देवताहरूमा म इन्द्र हुँ; इन्द्रियहरूमा म मन हुँ; प्राणीहरूमा म चेतना हुँ।",
         "“वेदहरूमा म साम; देवताहरूमा इन्द्र; इन्द्रियहरूमा मन; प्राणीहरूमा चेतना।”"),
"10.23": ("रुद्रहरूमा म शङ्कर हुँ; यक्ष र राक्षसहरूमा कुबेर; वसुहरूमा म अग्नि हुँ; पर्वतहरूमा मेरु।",
         "“रुद्रहरूमा म शिव; यक्ष र राक्षसहरूमा कुबेर; वसुहरूमा अग्नि; पर्वतहरूमा मेरु।”"),
"10.24": ("हे पार्थ, पुरोहितहरूमा मलाई प्रमुख बृहस्पति जान; सेनापतिहरूमा म स्कन्द हुँ; जलाशयहरूमा म समुद्र हुँ।",
         "“पुरोहितहरूमा मलाई बृहस्पति जान; सेनापतिहरूमा स्कन्द; पानीका निकायहरूमा समुद्र।”"),
"10.25": ("महर्षिहरूमा म भृगु हुँ; शब्दहरूमा म एकाक्षर ॐ हुँ; यज्ञहरूमा म जपयज्ञ हुँ; स्थावरहरूमा म हिमालय हुँ।",
         "“महर्षिहरूमा म भृगु; शब्दमा पवित्र ॐ; यज्ञहरूमा मौन जप; स्थिरहरूमा हिमालय।”"),
"10.26": ("सबै रूखहरूमा म अश्वत्थ हुँ; देवर्षिहरूमा नारद; गन्धर्वहरूमा चित्ररथ; सिद्धहरूमा मुनि कपिल।",
         "“रूखहरूमा म पवित्र पीपल; देवर्षिहरूमा नारद; दिव्य गायकहरूमा चित्ररथ; सिद्धहरूमा कपिल।”"),
"10.27": ("घोडाहरूमा अमृतबाट जन्मेको उच्चैःश्रवा मलाई जान; गजराजहरूमा ऐरावत; मानिसहरूमा राजा।",
         "“घोडाहरूमा म उच्चैःश्रवा — अमृतबाट जन्मेको; हात्तीहरूमा ऐरावत; मानिसहरूमा तिनको राजा।”"),
"10.28": ("हतियारहरूमा म वज्र हुँ; गाईहरूमा म कामधेनु हुँ; प्रजननकर्ताहरूमा म कामदेव हुँ; सर्पहरूमा वासुकि।",
         "“हतियारहरूमा म वज्र; गाईहरूमा इच्छापूरक गाई; कामीहरूमा कामदेव; सर्पहरूमा वासुकि।”"),
"10.29": ("सर्पहरूमा म अनन्त हुँ; जलमा वरुण; पितृहरूमा अर्यमा; नियन्त्रकहरूमा यम।",
         "“सर्पहरूमा म अनन्त; समुद्रका प्राणीहरूमा वरुण; पितृहरूमा अर्यमा; दण्ड दिनेहरूमा यम।”"),
"10.30": ("दैत्यहरूमा म प्रह्लाद हुँ; गणना गर्नेहरूमा काल; पशुहरूमा म सिंह हुँ; चराहरूमा गरुड।",
         "“दैत्यहरूमा म प्रह्लाद; गणनाकारहरूमा काल; पशुहरूमा सिंह; चराहरूमा गरुड।”"),
"10.31": ("पवित्र गर्नेहरूमा म वायु हुँ; योद्धाहरूमा म राम हुँ; माछाहरूमा म मकर हुँ; नदीहरूमा गङ्गा।",
         "“पवित्र गर्नेहरूमा म वायु; हतियारधारीहरूमा राम; माछाहरूमा मकर; नदीहरूमा गङ्गा।”"),
"10.32": ("हे अर्जुन, सृष्टिहरूमा म आदि, मध्य र अन्त्य पनि हुँ; विद्याहरूमा म अध्यात्मविद्या हुँ; वादीहरूमा तर्क।",
         "“सबै सृष्टिहरूमा म आदि, मध्य र अन्त्य हुँ; विद्याहरूमा आत्मविद्या; वाद-विवादमा ठोस तर्क।”"),
"10.33": ("अक्षरहरूमा म अकार हुँ; समासहरूमा द्वन्द्व; म नै अक्षय काल हुँ; सर्वत्र मुख भएको विधाता म नै हुँ।",
         "“अक्षरहरूमा म 'अ'; समासहरूमा द्वन्द्व; म अनन्त काल हुँ; म सबैतिर फर्केको सृष्टिकर्ता हुँ।”"),
"10.34": ("म सबै निल्ने मृत्यु हुँ, र भविष्यका सबैको उत्पत्ति; स्त्रीहरूमा म कीर्ति, श्री, वाणी, स्मृति, मेधा, धृति र क्षमा हुँ।",
         "“म सबै लैजाने मृत्यु र आउने सबैको स्रोत हुँ; स्त्रीहरूमा कीर्ति, कृपा, वाक्पटुता, स्मरण, बुद्धि, स्थिरता र धैर्य।”"),
"10.35": ("सामहरूमा म बृहत्साम हुँ; छन्दहरूमा गायत्री; महिनाहरूमा म मार्गशीर्ष हुँ; ऋतुहरूमा वसन्त।",
         "“सामगानहरूमा म बृहत्साम; छन्दहरूमा गायत्री; महिनाहरूमा मार्गशीर्ष; ऋतुहरूमा फुल्ने वसन्त।”"),
"10.36": ("म जुवाडीहरूको पासा हुँ; म तेजस्वीहरूको तेज हुँ; म विजय हुँ, म उद्यम हुँ; म असलहरूको असलपन हुँ।",
         "“म जुवाडीको कला, तेजस्वीको तेज; म विजय र संकल्प हुँ; म सज्जनको सद्गुण हुँ।”"),
"10.37": ("वृष्णिहरूमा म वासुदेव हुँ; पाण्डवहरूमा अर्जुन; ऋषिहरूमा म व्यास हुँ; कविहरूमा कवि उशना।",
         "“वृष्णिहरूमा म वासुदेव; पाण्डवहरूमा अर्जुन; ऋषिहरूमा व्यास; कविहरूमा उशना।”"),
"10.38": ("म दण्ड दिनेहरूको दण्ड हुँ; विजय चाहनेहरूमा म नीति हुँ; म गोप्यको मौनता हुँ; ज्ञानीहरूमा म ज्ञान हुँ।",
         "“म शासकहरूको राजदण्ड र विजयीहरूको कूटनीति हुँ; म रहस्यहरूको मौनता हुँ; ज्ञानीहरूमा ज्ञान।”"),
"10.39": ("र जे-जे सबै प्राणीको बीज हो, त्यो म नै हुँ, हे अर्जुन; चर होस् वा अचर, मबिना कुनै प्राणी छैन।",
         "“जुन बीजले सबै प्राणीलाई जन्म दिन्छ — त्यो म नै हुँ। चल होस् वा अचल, मबिना केही अस्तित्वमा छैन।”"),
"10.40": ("हे शत्रुतापन, मेरा दिव्य विभूतिहरूको अन्त्य छैन; मेरो विभूतिको विस्तारको यो केवल संक्षिप्त वर्णन हो।",
         "“मेरा दिव्य विभूतिहरूको अन्त्य छैन, अर्जुन — तिनको विशाल विस्तारको यो केवल छोटो बयान हो।”"),
"10.41": ("जुन-जुन प्राणी विभूतिशाली, तेजस्वी वा शक्तिशाली छ — त्यो मेरो तेजको एक अंशबाट जन्मेको जान।",
         "“जे-जे भव्य, चम्किलो वा शक्तिशाली छ — त्यो मेरो तेजको एउटा कणबाट उठेको जान।”"),
"10.42": ("तर हे अर्जुन, यति विस्तृत ज्ञानको के आवश्यकता? म आफ्नो एक अंशले यो सम्पूर्ण संसारलाई धानेर बसेको छु।",
         "“तर यो सबै विस्तृत जान्नुको के अर्थ, अर्जुन? म आफ्नो एक अंशले यो सम्पूर्ण ब्रह्माण्डलाई धानिरहेको छु।”"),
"11.01": ("अर्जुनले भने: आत्माको परम गोप्य विषयमा तपाईंले दयाले भन्नुभएका वचनहरूद्वारा, मेरो मोह हटेको छ।",
         "अर्जुन भन्छन्: “आत्माको सर्वोच्च रहस्यबारे तपाईंले कृपा गरेर बोल्नुभयो — त्यसैले मेरो भ्रम हराएको छ।”"),
"11.02": ("हे कमलनयन, प्राणीहरूको उत्पत्ति र विनाश मैले तपाईंबाट विस्तारमा सुनेँ, र तपाईंको अनन्त महिमा पनि।",
         "“हे कमलनयन प्रभु, सबै प्राणीको जन्म र नाश, र तपाईंको असीम महिमा — सबै मैले तपाईंबाट सुनेँ।”"),
"11.03": ("हे परमेश्वर, तपाईंले आफूलाई जसरी वर्णन गर्नुभयो, हे पुरुषोत्तम, त्यसरी नै म तपाईंको विश्वरूप देख्न चाहन्छु।",
         "“तपाईंले आफूलाई जसरी बताउनुभयो, हे सर्वोच्च प्रभु, म त्यही विश्वरूप हेर्न चाहन्छु।”"),
"11.04": ("हे प्रभु, यदि मैले देख्न सक्छु भनी तपाईं ठान्नुहुन्छ भने, हे योगेश्वर, तपाईंको अविनाशी स्वरूप मलाई देखाउनुहोस्।",
         "“यदि म यो देख्न सक्छु भनी तपाईं ठान्नुहुन्छ भने, हे योगेश्वर, मलाई आफ्नो नित्य स्वरूप प्रकट गर्नुहोस्।”"),
"11.05": ("श्रीभगवान्ले भन्नुभयो: हे पार्थ, हेर — मेरा सयौं र हजारौं रूपहरू, विभिन्न प्रकारका र विभिन्न रङ्गका।",
         "कृष्णले भन्नुभयो: “अब हेर, अर्जुन, मेरा सयौं-हजारौं रूपहरू — अनेक प्रकारका र अनेक रङ्गका।”"),
"11.06": ("हे भारत, आदित्यहरू, वसुहरू, रुद्रहरू, अश्विनीकुमारहरू र मरुत्हरू हेर; पहिले कहिल्यै नदेखिएका धेरै आश्चर्यहरू हेर।",
         "“सूर्यदेवताहरू, वसुहरू, रुद्रहरू, जुम्ल्याहा अश्विनहरू, आँधी-हावाहरू हेर — तिमीले कहिल्यै नदेखेका आश्चर्यहरू, अर्जुन।”"),
"11.07": ("हे गुडाकेश, अब यहाँ मेरो शरीरमा चर र अचर — सम्पूर्ण ब्रह्माण्ड — एकै ठाउँमा जम्मा भएको हेर, र अरू जे-जे हेर्न चाहन्छौ त्यो पनि।",
         "“मेरो शरीरभित्र सम्पूर्ण ब्रह्माण्ड — चल र अचल — एकै पटक हेर, र जे-जे पनि तिमी देख्न चाहन्छौ।”"),
"11.08": ("तर तिमी आफ्नै आँखाले मलाई देख्न सक्दैनौ; म तिमीलाई दिव्य दृष्टि दिन्छु — मेरो दिव्य ऐश्वर्य हेर।",
         "“तिम्रो मर्त्य आँखाले मलाई देख्न सक्दैन — यो दिव्य दृष्टि लेऊ र मेरो विश्वरूपी शक्ति हेर।”"),
"11.09": ("सञ्जयले भने: हे राजन्, यसरी भनेर, महान् योगेश्वर हरिले पार्थलाई आफ्नो परम दिव्य रूप देखाए।",
         "सञ्जय वर्णन गर्छन्: “यसरी भनेर, हे राजा, महान् योगेश्वर कृष्णले अर्जुनलाई आफ्नो सर्वोच्च विश्वरूप प्रकट गरे।”"),
"11.10": ("असंख्य मुख र आँखाहरू, असंख्य आश्चर्यमय दृश्यहरू, असंख्य दिव्य आभूषणहरू र उठाइएका हतियारहरूसहित,",
         "“— अगणित मुख र आँखा, गन्न नसकिने आश्चर्य, दिव्य आभूषण र चारैतिर उठेका हतियारहरूसहित —”"),
"11.11": ("दिव्य माला र वस्त्र पहिरिएको, दिव्य सुगन्धले लेपित, सबै आश्चर्यले भरिएको — सर्वत्र मुख भएको अनन्त देवता।",
         "“— दिव्य माला र वस्त्रले सजिएको, दिव्य सुगन्धले विभूषित, हरेक दिशामा मुख भएको असीम देवता।”"),
"11.12": ("यदि आकाशमा एकै पटक हजार सूर्यहरूको तेज उठेको भए, त्यो पनि त्यस महापुरुषको तेज बराबर हुँदैन।",
         "“यदि आकाशमा हजार सूर्य एकै साथ बलेको भए, त्यो पनि त्यस महान् व्यक्तिको महिमा बराबर हुँदैन।”"),
"11.13": ("त्यहाँ, देवताका देवताको शरीरमा, पाण्डुपुत्रले सम्पूर्ण ब्रह्माण्डलाई — एक तर अनन्त रूपमा विभाजित — देखे।",
         "“त्यहाँ अर्जुनले देवताका देवताको शरीरभित्र सम्पूर्ण ब्रह्माण्ड — एक तर असीम रूपले विविध — देखे।”"),
"11.14": ("त्यसपछि, आश्चर्यले भरिएर, रौं ठाडो भएर, धनञ्जयले देवतालाई शिर झुकाए, र हात जोडेर बोले।",
         "“त्यसपछि, आश्चर्यले अभिभूत, रौं ठाडो भएको अर्जुनले निहुरेर, हात जोडेर बोल्यो।”"),
"11.15": ("हे देवता, म तपाईंको शरीरमा सबै देवता र प्राणीहरूका समूहहरू देख्छु; कमलमा बसेका ब्रह्मा, र सबै ऋषि र दिव्य सर्पहरू देख्छु।",
         "“तपाईंको शरीरमा म सबै देवता र हरेक प्रकारका प्राणी देख्छु — कमलासनमा बसेका ब्रह्मा, ऋषिहरू र दिव्य सर्पहरू।”"),
"11.16": ("हे विश्वरूप, म तपाईंलाई असंख्य बाहु, उदर, मुख र आँखासहित देख्छु — चारैतिर अनन्त; म तपाईंको न अन्त्य, न मध्य, न आदि देख्छु।",
         "“हे विश्वरूप, म तपाईंलाई गन्न नसकिने बाहु, पेट, मुख र आँखासहित देख्छु — सबै दिशामा असीम; तपाईंको न आदि, न मध्य, न अन्त्य।”"),
"11.17": ("म तपाईंलाई मुकुटधारी, गदा र चक्र समातेको, जताततै चम्कने प्रकाशको पुञ्ज देख्छु — हेर्नै कठिन, आगो र सूर्यझैं बलेको, अप्रमेय।",
         "“म तपाईंलाई मुकुट, गदा र चक्रसहित देख्छु — प्रकाशको ज्वाला, हेर्न नसकिने गरी दैदिप्यमान, आगो र सूर्यजस्तै, अमापनीय।”"),
"11.18": ("तपाईं अविनाशी, जान्नुपर्ने परम वस्तु हुनुहुन्छ; तपाईं यस ब्रह्माण्डको परम आश्रय हुनुहुन्छ; तपाईं धर्मका शाश्वत रक्षक — आदि पुरुष, म यसरी तपाईंलाई ठान्छु।",
         "“तपाईं नित्य, जान्नयोग्य सर्वोच्च हुनुहुन्छ; तपाईं ब्रह्माण्डको परम धाम, धर्मका अपरिवर्तनीय रक्षक — आदि पुरुष हुनुहुन्छ।”"),
"11.19": ("आदि, मध्य र अन्त्यरहित, अनन्त शक्ति भएको, असंख्य बाहु भएको, सूर्य-चन्द्र आँखा भएको — म तपाईंलाई आगोजस्तै मुखले, आफ्नो तेजले सम्पूर्ण संसार निलिरहेको देख्छु।",
         "“आदि-अन्त्यरहित, असीम शक्ति, अगणित बाहु, सूर्य-चन्द्र आँखा भएको — म तपाईंलाई आगोजस्ता मुखले आफ्नो तेजले संसार जलाइरहेको देख्छु।”"),
"11.20": ("पृथ्वी र आकाशको बीचको आकाश र सबै दिशाहरू तपाईंले मात्र भरिएका छन्; तपाईंको भयानक, अद्भुत रूप देखेर तीनै लोक काम्छन्, हे महात्मा।",
         "“स्वर्ग र पृथ्वीको बीच, हरेक दिशामा, तपाईं एक्लैले सबै भर्नुभएको छ — र तीनै लोक तपाईंको भयानक रूप देखेर काम्छन्।”"),
"11.21": ("देवताहरूका समूहहरू तपाईंमा प्रवेश गर्छन्; कोही, डराएर, हात जोडेर तपाईंको स्तुति गर्छन्; महर्षिहरू र सिद्धहरूका समूहहरू तपाईंको स्तोत्र गाउँछन्।",
         "“देवताहरूका सेनाहरू तपाईंभित्र बग्छन्; कोही, त्रसित भएर, जोडिएका हातले तपाईंको महिमा गाउँछन्; ऋषि र सिद्धहरू पवित्र स्तोत्रले तपाईंको प्रशंसा गर्छन्।”"),
"11.22": ("रुद्रहरू, आदित्यहरू, वसुहरू, साध्यहरू, विश्वेदेवहरू, अश्विनीकुमारहरू, मरुत्हरू र पितृहरू — गन्धर्व, यक्ष, दानव र सिद्धहरू — सबै आश्चर्यचकित भएर तपाईंलाई हेर्छन्।",
         "“देवताहरूका सबै वर्ग — रुद्र, सूर्यदेवता, वसु र बाँकी — दिव्य गायक र आत्माहरूसँगै — सबै छक्क परेर तपाईंलाई हेर्छन्।”"),
"11.23": ("हे महाबाहो, धेरै मुख, आँखा, धेरै पेट र धेरै भयानक दाँत भएको तपाईंको विशाल रूप देखेर, लोकहरू काम्छन् — र म पनि।",
         "“तपाईंको विशाल रूप — अनेक मुख, आँखा, पेट र भयानक बङ्गारासहित — देखेर लोकहरू काम्छन्, हे महाबाहो, र म पनि।”"),
"11.24": ("आकाश छुने, दनदनी बलेको, अनेक रङ्गको, खुला मुख र बलेका विशाल आँखा भएको — तपाईंलाई देखेर, मेरो भित्री हृदय काम्छ; मलाई कुनै स्थिरता वा शान्ति भेटिँदैन, हे विष्णु।",
         "आकाश छुने, दनदनी बलेको, अनेक रङ्गको रूप — खुला मुख, फराकिला बलेका आँखा — देखेर मेरो हृदय काम्छ; मलाई न स्थिरता भेटिन्छ न शान्ति, हे विष्णु।"),
"11.25": ("प्रलयकालको आगोजस्तै बलेका, भयानक बङ्गारा भएका तपाईंका भयङ्कर मुखहरू देखेर, म दिशाहरू चिन्दिनँ, न कुनै शरण नै पाउँछु; हे देवताका स्वामी, संसारका आश्रय, कृपा गर्नुहोस्।",
         "विनाशकालको आगोजस्तै दनदनी बलेका, भयानक दाँत भएका मुखहरू देखेर, म दिशा नै चिन्दिनँ र कुनै शरण पाउँदिनँ; कृपा गर्नुहोस्, हे देवताका स्वामी।"),
"11.26": ("धृतराष्ट्रका यी सबै छोराहरू, राजाहरूका समूहहरूसँगै, तपाईंका मुखहरूमा प्रवेश गर्छन् — भीष्म, द्रोण, कर्ण, र हाम्रा प्रमुख योद्धाहरू पनि,",
         "“धृतराष्ट्रका यी छोराहरू, तिनका राजाहरूसँगै, तपाईंका मुखहरूमा छिरिरहेका छन् — भीष्म, द्रोण, कर्ण, र हाम्रा अग्रणी योद्धाहरू,”"),
"11.27": ("तिनका टाउकाहरू तपाईंका दाँतहरूका बीचमा किच्चिएका छन् — कोही, डरले टाँसिएर, तपाईंका भयानक बङ्गाराहरूका खाली ठाउँमा देखिन्छन्।",
         "“— तिनका टाउका तपाईंका दाँतमा पिसिएका छन्; कोही, त्रासले झुन्डिएर, तपाईंका भयानक बङ्गाराका बीचमा देखिन्छन्।”"),
"11.28": ("जसरी धेरै बग्ने नदीहरूका धाराहरू समुद्रमा पुग्छन्, त्यसरी नै यी मर्त्य संसारका वीरहरू तपाईंका दनदनी बलेका मुखहरूमा प्रवेश गर्छन्।",
         "“जसरी नदीहरू आफ्ना असंख्य जलधारासहित समुद्रमा बग्छन्, त्यसरी यी मानव योद्धाहरू तपाईंका बलेका मुखहरूमा बग्छन्।”"),
"11.29": ("जसरी पुतलीहरू आफ्नो विनाशका निम्ति पूरै वेगले बलेको आगोमा उड्छन्, त्यसरी नै यी लोकहरू आफ्नो विनाशका निम्ति तपाईंका मुखहरूमा उड्छन्।",
         "“जसरी पुतलीहरू नष्ट हुनका निम्ति ज्वालामा हाम फाल्छन्, त्यसरी यी लोकहरू नष्ट हुनका निम्ति तपाईंका मुखहरूमा दौडिन्छन्।”"),
"11.30": ("तपाईं आफ्ना बलेका मुखहरूले सबै लोकलाई चाट्नुहुन्छ, चारैतिरबाट निल्नुहुन्छ; तपाईंका भयानक किरणहरूले सम्पूर्ण ब्रह्माण्ड भरिन्छ, हे विष्णु।",
         "“तपाईं आफ्ना बलेका बङ्गाराले लोकहरूलाई चाट्नुहुन्छ, सबैतिरबाट निल्नुहुन्छ; तपाईंको भयानक तेजले ब्रह्माण्ड भरिन्छ, हे विष्णु।”"),
"11.31": ("हे भयानक रूप, तपाईं को हुनुहुन्छ भनी भन्नुहोस्; म तपाईंलाई नमस्कार गर्छु — हे देवतामा श्रेष्ठ, कृपा गर्नुहोस्! म तपाईंलाई, आदि पुरुषलाई, जान्न चाहन्छु; म तपाईंका क्रियाहरू बुझ्दिनँ।",
         "“यस भयानक रूपमा तपाईं को हुनुहुन्छ, भन्नुहोस्; म तपाईंलाई प्रणाम गर्छु — कृपा गर्नुहोस्, प्रभु। म तपाईंलाई, आदिम पुरुषलाई, चिन्न चाहन्छु, किनकि तपाईंका बाटो म बुझ्न सक्दिनँ।”"),
"11.32": ("श्रीभगवान्ले भन्नुभयो: म काल हुँ — संसार-विनाशक, परिपक्व भएको; यी लोकहरू नष्ट गर्न म आएको छु — तिमी नहुँदा पनि, तिम्रो सामु सजिएका यी योद्धाहरूमध्ये कोही बाँच्नेछैन।",
         "कृष्णले भन्नुभयो: “म काल हुँ — लोक नष्ट गर्न परिपक्व भएको। तिमीले प्रहार नगरे पनि यी योद्धाहरूमध्ये कोही बाँच्नेछैन।”"),
"11.33": ("त्यसैले उठ र कीर्ति जित; शत्रुहरूलाई जित र फस्टाउँदो राज्यको भोग गर — तिनीहरू मैले नै मारिसकेको छु; हे सव्यसाची, तिमी त केवल साधन हो।",
         "“त्यसैले उठ र प्रसिद्धि कमाऊ; शत्रुलाई हराऊ र समृद्ध राज्यको आनन्द लेऊ। मैले तिनलाई पहिल्यै मारिसकेको छु — तिमी केवल माध्यम हौ, अर्जुन।”"),
"11.34": ("द्रोण, भीष्म, जयद्रथ, कर्ण र अरू वीर-योद्धाहरूलाई मार — जसलाई मैले पहिल्यै मारिसकेको छु; नडराइकन प्रहार गर, लड — तिमी युद्धमा आफ्ना प्रतिद्वन्द्वीहरूलाई जित्नेछौ।",
         "“द्रोण, भीष्म, जयद्रथ र कर्णलाई मार — मैले तिनलाई पहिल्यै नष्ट गरिसकेको छु। हिचकिचाहट बिना प्रहार गर र लड; तिमी युद्धमा विजयी हुनेछौ।”"),
"11.35": ("सञ्जयले भने: केशवका यी वचन सुनेर, मुकुटधारी अर्जुन, काँप्दै, हात जोडेर, फेरि झुकेर, अवरुद्ध स्वरमा कृष्णलाई भने।",
         "सञ्जय वर्णन गर्छन्: “कृष्णका वचन सुनेर, काँपिरहेको अर्जुनले हात जोड्यो, फेरि निहुरियो, र ठक्कर खाएको स्वरमा बोल्यो।”"),
"11.36": ("हे हृषीकेश, संसार तपाईंको महिमामा रम्छ र आनन्दित हुन्छ भनी उचित नै हो; राक्षसहरू डरले चारै दिशामा भाग्छन्, र सिद्धहरूका समूहहरू तपाईंलाई नमस्कार गर्छन्।",
         "“ठीकै हो, हे कृष्ण, संसार तपाईंको प्रशंसामा रम्छ; दानवहरू त्रासमा भाग्छन्, र सिद्धहरू तपाईंलाई प्रणाम गर्छन्।”"),
"11.37": ("हे महात्मा, आदि सृष्टिकर्ता ब्रह्माभन्दा पनि ठूलो तपाईंलाई तिनीहरूले किन नझुकून् — हे देवताहरूका अनन्त स्वामी, ब्रह्माण्डका आश्रय, तपाईं नै अविनाशी, सत् र असत् र दुवैभन्दा पर हुनुहुन्छ?",
         "“हे महान्, पहिलो सृष्टिकर्ता ब्रह्माभन्दा पनि श्रेष्ठ तपाईंलाई को नझुक्ला? तपाईं नित्य, सत् र असत्, र तिनभन्दा पर — सबै हुनुहुन्छ।”"),
"11.38": ("तपाईं आदि देवता, प्राचीन पुरुष, यस ब्रह्माण्डको परम शरण हुनुहुन्छ; तपाईं ज्ञाता र ज्ञेय, परम धाम हुनुहुन्छ; हे अनन्त रूप, तपाईंद्वारा नै यो ब्रह्माण्ड व्याप्त छ।",
         "“तपाईं पहिलो देवता, प्राचीन पुरुष, ब्रह्माण्डको सर्वोच्च आश्रय हुनुहुन्छ; तपाईं जान्ने र जानिने, परम घर हुनुहुन्छ — र सबै तपाईंमै फैलिएको छ।”"),
"11.39": ("तपाईं वायु, मृत्यु, अग्नि, वरुण, चन्द्रमा र प्रजापति — र महान् पितामह हुनुहुन्छ; म तपाईंलाई हजार पटक नमस्कार गर्छु — फेरि र फेरि तपाईंलाई नमस्कार गर्छु।",
         "“तपाईं वायु, मृत्यु, अग्नि, वरुण, चन्द्रमा — पिता र महान् पूर्वज हुनुहुन्छ। तपाईंलाई हजारौं प्रणाम — बारम्बार, म झुक्छु।”"),
"11.40": ("म तपाईंलाई अगाडिबाट र पछाडिबाट नमस्कार गर्छु; हे सर्व, म तपाईंलाई चारैतिरबाट नमस्कार गर्छु! तपाईं अनन्त शक्ति र अमापनीय वेगका हुनुहुन्छ; तपाईं सबै व्याप्त गर्नुहुन्छ, त्यसैले तपाईं नै सबै हुनुहुन्छ।",
         "“म तपाईंलाई अगाडि र पछाडि प्रणाम गर्छु; हे सर्वव्यापी, म चारैतिरबाट तपाईंलाई नमस्कार गर्छु। तपाईंको शक्ति अनन्त छ — तपाईं सबै हुनुहुन्छ, किनकि तपाईंले सबै भर्नुभएको छ।”"),
"11.41": ("तपाईंको महिमा नजानेर, हतार र अपरिचिततामा — 'हे कृष्ण, हे यादव, हे मित्र' — लापरवाहीले वा प्रेमले जे-जे मैले भनेँ,",
         "“तपाईंको महानता नजानेर, हिम्मत र लापरवाहीले तपाईंलाई कृष्ण, यादव, मेरा मित्र भनेर जे-जे भनेँ — मजाकमा वा मायामा,”"),
"11.42": ("र खेलमा, विश्राममा, बस्दा वा भोजनमा, एक्लै वा अरूको अगाडि तपाईंप्रति जे-जे अनादर गरें — हे अच्युत, हे अप्रमेय, त्यो सबै क्षमा गर्नुहोस्।",
         "“— र खेल, आराम, भोजन वा अरूको संगतमा, तपाईंलाई जे-जे हेला गरें — हे अपरिवर्तनीय, अमापनीय प्रभु, त्यो सबै क्षमा गर्नुहोस्।”"),
"11.43": ("तपाईं यस चर-अचर संसारका पिता हुनुहुन्छ; तपाईं यसको परम पूजनीय र सबैभन्दा श्रद्धेय गुरु हुनुहुन्छ; तीनै लोकमा तपाईंको बराबरी कोही छैन — तपाईंभन्दा माथि कोही कसरी होला, हे अतुल शक्ति भएका?",
         "“तपाईं चल र अचल — सबैका पिता हुनुहुन्छ; तपाईं परम पूज्य र सबैभन्दा ठूला गुरु हुनुहुन्छ। तीनै लोकमा तपाईंको बराबरी केही छैन — तपाईंभन्दा माथि त केही कसरी हुन सक्छ?”"),
"11.44": ("त्यसैले म झुकेर तपाईंको अगाडि शरीर थपथपाउँछु, र तपाईंको कृपा माग्छु, हे पूजनीय प्रभु; जसरी पिताले छोरालाई, मित्रले मित्रलाई, प्रियले प्रियतमलाई क्षमा गर्छ — त्यसरी नै मलाई क्षमा गर्नुहोस्, हे देवता।",
         "“त्यसैले म तपाईंको अगाडि निहुरेर प्रार्थना गर्छु र कृपा माग्छु। जसरी पिता छोरालाई, मित्र मित्रलाई, प्रेमी प्रियतमलाई क्षमा गर्छ — त्यसरी मलाई क्षमा गर्नुहोस्, हे प्रभु।”"),
"11.45": ("पहिले कहिल्यै नदेखेको यो देखेर म प्रसन्न छु, तैपनि मेरो मन डरले काम्छ; हे देवता, तपाईंको मनोहर रूप देखाउनुहोस् — हे विश्वेश्वर, कृपा गर्नुहोस्।",
         "“यो आश्चर्य देखेर म रमाउँछु, तर मेरो हृदय डरले काम्छ; हे प्रभु, आफ्नो कोमल रूप देखाउनुहोस् — कृपा गर्नुहोस्।”"),
"11.46": ("म पहिलेजस्तै — मुकुट, गदा र चक्र हातमा लिएको — तपाईंलाई देख्न चाहन्छु; हे हजार बाहु भएका विश्वरूप, त्यो चतुर्भुज रूपमा प्रकट हुनुहोस्।",
         "“म तपाईंलाई पहिलेजस्तै — मुकुट, गदा र चक्रसहित — फेरि देख्न चाहन्छु; हे विश्वरूप, त्यो चतुर्भुज रूपमा प्रकट हुनुहोस्।”"),
"11.47": ("श्रीभगवान्ले भन्नुभयो: हे अर्जुन, मैले कृपाले तिमीलाई यो परम रूप देखाएँ — तेजोमय, विश्वरूपी, अनन्त, आदिम रूप — जुन तिमीबाहेक अरू कसैले कहिल्यै देखेको छैन।",
         "कृष्णले भन्नुभयो: “कृपाले, अर्जुन, मैले तिमीलाई यो सर्वोच्च, दैदिप्यमान, विश्वरूपी, असीम, आदिम रूप देखाएँ — तिमीभन्दा अघि कसैले नदेखेको।”"),
"11.48": ("हे कुरुनन्दन, वेदको अध्ययन, यज्ञ, दान, अनुष्ठान वा कठोर तपस्या — कुनै पनि विधिबाट, मानव लोकमा, तिमीबाहेक अरू कसैले मलाई यस रूपमा देख्न सक्दैन।",
         "“न वेद-अध्ययन, न यज्ञ, न दान, न अनुष्ठान, न कठोर तप — यस रूपलाई मर्त्य संसारमा तिमीबाहेक कोही देख्न सक्दैन।”"),
"11.49": ("मेरो यो भयानक रूप देखेर नडराऊ, न अलमल; डर हटाएर, प्रसन्न हृदयले, मेरो यो मनोहर रूप फेरि हेर।",
         "“मेरो यो भयानक दृश्य देखेर नडरा, न अलमल। डर गएपछि, सहज हृदयले, मेरो कोमल रूप फेरि हेर।”"),
"11.50": ("सञ्जयले भने: अर्जुनलाई यसरी भनेर, वासुदेवले फेरि आफ्नो निजी रूप देखाए, र महात्माले त्रसित अर्जुनलाई, फेरि आफ्नो मनोहर रूपमा, सान्त्वना दिए।",
         "सञ्जय वर्णन गर्छन्: “यसरी भनेर, कृष्णले फेरि आफ्नो कोमल रूप धारण गरे, र महात्माले त्रसित अर्जुनलाई सान्त्वना दिए।”"),
"11.51": ("अर्जुनले भने: हे जनार्दन, तपाईंको यो मनोहर मानव रूप देखेर, म अब शान्त भएको छु र आफ्नो स्वभावमा फर्केको छु।",
         "अर्जुन भन्छन्: “तपाईंको कोमल मानव रूप देखेर, हे जनार्दन, म फेरि शान्त भएँ, र मेरो मन आफैंमा फर्कियो।”"),
"11.52": ("श्रीभगवान्ले भन्नुभयो: तिमीले देखेको मेरो यो रूप हेर्न अत्यन्तै कठिन छ; देवताहरूले पनि यो रूपको दर्शन सधैं चाहन्छन्।",
         "कृष्णले भन्नुभयो: “तिमीले देखेको यो रूप हेर्न अत्यन्त कठिन छ — देवताहरू पनि यसको दर्शनका निम्ति सधैं तरस्छन्।”"),
"11.53": ("न वेदद्वारा, न तपस्याद्वारा, न दानद्वारा, न पूजाद्वारा म यस रूपमा देखिन सक्छु; तिमीले मलाई जसरी देख्यौ, त्यसरी नै मात्र म देखिन्छु।",
         "“यो दर्शन न वेद-अध्ययनले, न तपले, न दानले, न अनुष्ठानले मिल्छ — मलाई यसरी नै, जसरी तिमीले देख्यौ, देखिन्छ।”"),
"11.54": ("तर हे अर्जुन, एकनिष्ठ भक्तिद्वारा म यसै रूपमा साँच्चै जानिन, देखिन र प्रवेश गर्न सकिन्छु।",
         "“तर अविभाजित भक्तिले, अर्जुन, म यसै रूपमा साँच्चै जानिन, देखिन र प्रवेश गर्न सकिन्छु।”"),
"11.55": ("जसले मेरो कर्म गर्छ, मलाई परम लक्ष्य मान्छ, मप्रति भक्त छ, आसक्तिरहित छ, र कुनै प्राणीप्रति द्वेष राख्दैन — हे पाण्डव, ऊ मकहाँ आउँछ।",
         "“जो मेरा निम्ति काम गर्छ, मलाई आफ्नो परम लक्ष्य बनाउँछ, मप्रति समर्पित छ, आसक्ति र द्वेषबाट मुक्त छ — ऊ मकहाँ पुग्छ, अर्जुन।”"),
"12.01": ("अर्जुनले भने: सधैं युक्त भएर तपाईंको पूजा गर्ने भक्तहरू — र अविनाशी अव्यक्तको पूजा गर्नेहरू — यीमध्ये कुन योगका राम्रो ज्ञाता हुन्?",
         "अर्जुन सोध्छन्: “कुन ठूला योगी हुन् — भक्तिले तपाईंको पूजा गर्ने, वा निराकार, अविनाशी परमात्माको पूजा गर्ने?”"),
"12.02": ("श्रीभगवान्ले भन्नुभयो: जसले मन ममा लगाएर, सधैं युक्त भएर, परम श्रद्धाले मेरो पूजा गर्छन् — तिनैलाई म सबैभन्दा युक्त मान्छु।",
         "कृष्णले भन्नुभयो: “जसले मन ममा राखेर, सधैं समर्पित भएर, परम श्रद्धाले मेरो पूजा गर्छन् — मेरो दृष्टिमा तिनै महान् योगी हुन्।”"),
"12.03": ("तर जो अविनाशी, अवर्णनीय, अव्यक्त — सर्वव्यापी, अचिन्त्य, अपरिवर्तनीय, अचल, नित्य — को पूजा गर्छन्,",
         "“तर जो अव्यक्त — अवर्णनीय, सर्वव्यापी, अचिन्त्य, अपरिवर्तनीय, नित्य — को पूजा गर्छन्,”"),
"12.04": ("— सबै इन्द्रियहरूलाई संयत गरेर, सर्वत्र समान मन भएर, सबै प्राणीको हितमा रमेर — तिनीहरू पनि मकहाँ आउँछन्।",
         "“— जसले इन्द्रियलाई रोकेर, सबैलाई समान देखेर, सबै प्राणीको हितमा रम्छन् — तिनीहरू पनि मकहाँ पुग्छन्।”"),
"12.05": ("जसका मन अव्यक्तमा आसक्त छन्, तिनको परिश्रम बढी हुन्छ; देहधारीहरूका निम्ति अव्यक्त पुग्न गाह्रो छ।",
         "“तर तिनको संघर्ष ठूलो छ, किनकि निराकार परमात्मा शरीरमा बस्नेहरूका निम्ति पुग्न कठिन छ।”"),
"12.06": ("तर जसले सबै कर्म ममा अर्पण गर्छन्, ममै तत्पर भएर, अविभाजित योगले मेरो पूजा गर्छन् र मेरो ध्यान गर्छन्,",
         "“तर जसले आफ्ना सबै कर्म मलाई अर्पण गर्छन्, मलाई परम मान्छन्, र एकाग्र ध्यानले मेरो पूजा गर्छन्,”"),
"12.07": ("हे पार्थ, तिनका निम्ति, जसका मन ममा टिकेका छन्, म चाँडै नै जन्म-मृत्युको सागरबाट उद्धारक बन्छु।",
         "“— जसका हृदय ममा विश्राम गर्छन्, तिनका निम्ति म चाँडै जन्म-मृत्युको सागरबाट उद्धारकर्ता बन्छु।”"),
"12.08": ("केवल ममै मन लगाऊ; ममै बुद्धि स्थिर गर; तब तिमी ममै बाँच्नेछौ — यसमा कुनै सन्देह छैन।",
         "“आफ्नो मन र समझ केवल ममा राख — र तिमी निश्चय ममै बाँच्नेछौ; यसमा कुनै सन्देह छैन।”"),
"12.09": ("यदि तिमी मन ममा स्थिर गर्न सक्दैनौ भने, हे धनञ्जय, अभ्यासयोगद्वारा — अभ्यासले मकहाँ पुग्ने प्रयास गर।",
         "“यदि तिमी मन ममा स्थिर राख्न सक्दैनौ भने, बारम्बार अभ्यासले मकहाँ पुग्ने प्रयास गर, अर्जुन।”"),
"12.10": ("यदि त्यो पनि गर्न सक्दैनौ भने, मेरा निम्ति काम गर्नमा समर्पित होऊ; मेरै निम्ति कर्म गरे पनि तिमी सिद्धि पाउनेछौ।",
         "“यदि त्यो पनि सम्भव छैन भने, मेरा निम्ति काम गर्नमा लाग — मेरै निम्ति काम गरे पनि तिमी सिद्धिमा पुग्नेछौ।”"),
"12.11": ("यदि यो पनि गर्न सक्दैनौ भने, मेरो योगको शरण लिएर, आत्मा संयत गरेर, सबै कर्मको फल त्याग।",
         "“यदि त्यो पनि गर्न सक्दैनौ भने, आत्म-संयमित मनले, आफ्ना सबै कर्मको फल मलाई समर्पण गर।”"),
"12.12": ("अभ्यासभन्दा ज्ञान राम्रो; ज्ञानभन्दा ध्यान राम्रो; ध्यानभन्दा कर्मफलत्याग राम्रो — किनकि त्यागबाट तुरुन्तै शान्ति मिल्छ।",
         "“अभ्यासभन्दा ज्ञान राम्रो; ज्ञानभन्दा ध्यान राम्रो; र त्योभन्दा पनि कर्मको फल त्याग्नु राम्रो — किनकि त्यसले तुरुन्तै शान्ति दिन्छ।”"),
"12.13": ("जसले कुनै प्राणीलाई घृणा गर्दैन, मित्रवत् र दयालु छ, ममता र अहंकारबाट मुक्त छ, सुख-दुःखमा समान छ, क्षमाशील छ —",
         "“जो कसैसँग घृणा गर्दैन, दयालु र करुणामय छ, 'मेरो' र 'म' बाट मुक्त छ, सुख-दुःखमा एकनास छ, धैर्यवान् छ —”"),
"12.14": ("— सधैं सन्तुष्ट, योगी, आत्मसंयमी, दृढ संकल्प भएको, मन र बुद्धि ममा अर्पण गरेको — त्यो मेरो भक्त मलाई प्रिय छ।",
         "“— सधैं सन्तोषी, आत्मविजयी, संकल्पवान्, मन र हृदय मलाई दिएको — यस्तो भक्त मलाई प्रिय छ।”"),
"12.15": ("जसद्वारा संसार विचलित हुँदैन, र जो संसारले विचलित हुँदैन — हर्ष, क्रोध, भय र चिन्ताबाट मुक्त — ऊ मलाई प्रिय छ।",
         "“जसले कसैलाई विचलित गर्दैन र जो कसैले विचलित हुँदैन — हर्ष, क्रोध, भय र चिन्ताबाट मुक्त — ऊ मलाई प्रिय छ।”"),
"12.16": ("जो आसक्तिरहित, शुद्ध, दक्ष, उदासीन, चिन्तारहित, सबै आरम्भ त्याग्ने — त्यो मेरो भक्त मलाई प्रिय छ।",
         "“जो आसक्तिरहित, शुद्ध, निपुण, तटस्थ, चिन्तामुक्त, र सबै स्वार्थी परियोजना छोड्ने — त्यो भक्त मलाई प्रिय छ।”"),
"12.17": ("जो न रम्छ न घृणा गर्छ, न शोक गर्छ न इच्छा राख्छ, असल र नराम्रो दुवै त्याग्ने — त्यो भक्त मलाई प्रिय छ।",
         "“जो न हर्षित हुन्छ न निराश, न शोक गर्छ न लालसा, असल-नराम्रो दुवै छोड्ने — यस्तो भक्त मलाई प्रिय छ।”"),
"12.18": ("मित्र र शत्रु, मान र अपमान, जाडो र गर्मी, सुख र दुःखमा समान, आसक्तिरहित —",
         "“मित्र र शत्रु, प्रशंसा र निन्दा, जाडो-गर्मी, सुख-शोकमा समान, मोहबाट मुक्त —”"),
"12.19": ("— मौन, जे पनि पाए त्यसैमा सन्तुष्ट, घरबारविहीन, स्थिर मन भएको, भक्तिले भरिएको — त्यो मानिस मलाई प्रिय छ।",
         "“— मौन, जे आइपर्छ त्यसैमा सन्तुष्ट, ठाउँप्रति आसक्तिरहित, स्थिर मन, समर्पित — यस्तो व्यक्ति मलाई प्रिय छ।”"),
"12.20": ("तर जसले यो अमृत धर्मलाई, बताइएअनुसार, श्रद्धाले, मलाई परम लक्ष्य बनाएर अनुसरण गर्छन् — ती भक्तहरू मलाई अत्यन्त प्रिय छन्।",
         "“तर जसले यो अमर धर्मलाई श्रद्धाले, मलाई सर्वोच्च लक्ष्य मानेर पछ्याउँछन् — यस्ता भक्तहरू सबैभन्दा प्रिय छन्।”"),
"13.01": ("श्रीभगवान्ले भन्नुभयो: हे कुन्तीपुत्र, यो शरीर क्षेत्र भनिन्छ; जसले यसलाई जान्दछ, ज्ञानीहरूले उसलाई क्षेत्रज्ञ भन्छन्।",
         "कृष्णले भन्नुभयो: “यो शरीर क्षेत्र भनिन्छ; जसले यसलाई चिन्छ, ऊ क्षेत्रज्ञ भनिन्छ।”"),
"13.02": ("हे भारत, सबै क्षेत्रहरूमा मलाई पनि क्षेत्रज्ञ जान; क्षेत्र र क्षेत्रज्ञको ज्ञान नै मेरो दृष्टिमा साँचो ज्ञान हो।",
         "“मलाई हरेक शरीरको क्षेत्रज्ञ जान; क्षेत्र र त्यसका ज्ञाताको विवेक नै म साँचो ज्ञान भन्छु।”"),
"13.03": ("क्षेत्र के हो, कस्तो छ, यसका विकारहरू के हुन्, यो कहाँबाट उत्पन्न हुन्छ, र ऊ को हो र उसका शक्तिहरू के हुन् — यो सब मबाट संक्षेपमा सुन।",
         "“क्षेत्र के हो, यसको स्वरूप, यसका परिवर्तन, यसको स्रोत — र ज्ञाता को हो र उसका शक्तिहरू के हुन् — यो सब मबाट छोटकरीमा सुन।”"),
"13.04": ("ऋषिहरूले यसलाई धेरै तरिकाले, विविध छन्दमा, र ब्रह्मसूत्रहरूमा, कारणसहित, राम्ररी निर्णय गरेर गाएका छन् —",
         "“ऋषिहरूले यसलाई अनेक तरिकाले, विभिन्न छन्दमा, र ब्रह्मसूत्रमा — तर्कसहित, निश्चित रूपमा — गाएका छन्,”"),
"13.05": ("— महाभूतहरू, अहंकार, बुद्धि, अव्यक्त, दश इन्द्रिय र एघारौं मन, र इन्द्रियका पाँच विषयहरू,",
         "“— महाभूतहरू, अहंकार, बुद्धि, अव्यक्त, दश इन्द्रिय र मन, र पाँच इन्द्रिय-विषयहरू,”"),
"13.06": ("— इच्छा, द्वेष, सुख, दुःख, शरीर, चेतना र धृति: यो नै क्षेत्र हो, संक्षेपमा, यसका विकारहरूसहित।",
         "“— इच्छा, अरुचि, आनन्द, शोक, शरीर नै, चेतना र स्थिरता: यो नै क्षेत्र हो, छोटकरीमा, यसका सबै परिवर्तनसहित।”"),
"13.07": ("नम्रता, विनय, अहिंसा, क्षमा, सरलता, गुरुसेवा, शुद्धता, स्थिरता, आत्मसंयम,",
         "“नम्रता, विनम्रता, अहिंसा, धैर्य, इमानदारी, गुरुको सेवा, शुद्धता, दृढता, आत्मसंयम,”"),
"13.08": ("— इन्द्रियका विषयहरूप्रति वैराग्य, अहंकारको अभाव, र जन्म, मृत्यु, बुढ्यौली र रोगको दोषको अनुभव,",
         "“— इन्द्रिय-सुखमा अनासक्ति, अहंकार नहुनु, र जन्म, मृत्यु, बुढ्यौली र रोगको पीडा स्पष्ट देख्नु,”"),
"13.09": ("— आसक्तिरहितता, छोरा, पत्नी र घरमा नटाँसिनु, लाभ-हानिमा निरन्तर समानता,",
         "“— आसक्ति नहुनु, परिवार र घरमा मोह नहुनु, सफलता-असफलतामा स्थिर समत्व,”"),
"13.10": ("— अविभाजित योगद्वारा मप्रति अविचलित भक्ति, एकान्तमा रुचि, मानिसहरूको भीडप्रति अरुचि,",
         "“— एकनिष्ठ योगले मप्रति अटल भक्ति, एकान्तप्रति प्रेम, सांसारिक भीडप्रति अरुचि,”"),
"13.11": ("— आत्मज्ञानमा निरन्तर लगाव, र तत्त्वज्ञानको प्रयोजनको दृष्टि: यो नै ज्ञान भनिन्छ; यसबाहेक जे छ त्यो अज्ञान हो।",
         "“— आत्मज्ञानको निरन्तर खोज, र सत्यज्ञानको उद्देश्य देख्नु: यसलाई ज्ञान भनिन्छ; अरू जे छ त्यो अज्ञान हो।”"),
"13.12": ("म जान्नुपर्ने वस्तु बताउनेछु, जसलाई जानेर मानिस अमरत्व चाख्छ — आदिरहित परम ब्रह्म, जसलाई न सत् भनिन्छ न असत्।",
         "“म तिमीलाई जान्नयोग्य वस्तु बताउँछु, जसलाई जानेर तिमी अमरत्व चाख्नेछौ — आदिरहित परम ब्रह्म, सत् र असत् दुवैभन्दा पर।”"),
"13.13": ("जताततै हात र खुट्टा, जताततै आँखा, शिर र मुख, जताततै कान भएर — यो संसारमा सबै व्याप्त गरेर उभिएको छ।",
         "“यसका हात-खुट्टा सबै दिशामा छन्, आँखा, शिर र मुख सबैतिर, कान सबैतिर — यो सबैलाई अँगालेर उभिएको छ।”"),
"13.14": ("इन्द्रियका सबै गुणहरूसहित देखिने, तर इन्द्रियरहित; आसक्तिरहित, तैपनि सबैलाई धान्ने; गुणरहित, तैपनि गुणहरूको भोग गर्ने।",
         "“यो इन्द्रियका सबै गुण भएको देखिन्छ, तर यसका इन्द्रियहरू छैनन्; यो आसक्तिरहित छ, तैपनि सबैलाई धान्छ; गुणभन्दा पर, तैपनि गुणको भोग गर्छ।”"),
"13.15": ("यो सबै प्राणीको भित्र र बाहिर छ; यो अचल पनि छ र चल पनि; सूक्ष्म भएकोले यो जान्न गाह्रो छ — यो टाढा पनि छ, र नजिक पनि।",
         "“यो सबै प्राणीको भित्र र बाहिर छ; अचल र चल दुवै; यति सूक्ष्म कि समात्न गाह्रो — टाढा पनि, र हातै अगाडि पनि।”"),
"13.16": ("यो अविभाजित छ, तैपनि प्राणीहरूमा विभाजितझैं देखिन्छ; यसलाई प्राणीहरूको धर्ता, भोक्ता र स्रष्टा जान।",
         "“अविभाजित, यो प्राणीहरूमा विभाजितझैं देखिन्छ; यसलाई सबैको धान्ने, भोग्ने र स्रोत जान।”"),
"13.17": ("यो ज्योतिहरूको ज्योति हो, अन्धकारभन्दा पर भनिएको — ज्ञान, ज्ञेय र ज्ञानको लक्ष्य, सबैको हृदयमा बसेको।",
         "“यो सबै ज्योतिको ज्योति, अन्धकारभन्दा पर — ज्ञान नै, यसको विषय, र यसको लक्ष्य — हरेक हृदयमा बस्ने।”"),
"13.18": ("यसरी क्षेत्र, ज्ञान र ज्ञेय संक्षेपमा भनियो; मेरो भक्त, यो जानेर, मेरो अवस्था प्राप्त गर्छ।",
         "“त्यसैले मैले क्षेत्र, ज्ञान र ज्ञेय छोटकरीमा भनेँ; मेरो भक्त, यो बुझेर, मेरो अवस्थामा पुग्छ।”"),
"13.19": ("प्रकृति र पुरुष दुवैलाई आदिरहित जान; र विकारहरू र गुणहरू प्रकृतिबाट जन्मेका जान।",
         "“जान कि प्रकृति र पुरुष दुवै आदिरहित छन्; र सबै परिवर्तन र गुणहरू प्रकृतिबाट उठ्छन्।”"),
"13.20": ("प्रकृति कार्यको सम्पादनमा कर्तृत्वको कारण भनिन्छ; पुरुष सुख-दुःखको भोगको कारण भनिन्छ।",
         "“प्रकृति गर्नेपनको कारण हो; पुरुष सुख-दुःख अनुभव गर्ने कारण हो।”"),
"13.21": ("प्रकृतिमा बसेको पुरुषले प्रकृतिबाट जन्मेका गुणहरूको भोग गर्छ; गुणहरूमा आसक्ति नै असल र नराम्रो योनिमा जन्मको कारण हो।",
         "“प्रकृतिमा विश्राम गर्ने पुरुषले प्रकृतिबाट जन्मेका गुणहरू चाख्छ; ती गुणमा टाँसिनु नै उच्च वा नीच योनिमा जन्मको कारण हो।”"),
"13.22": ("साक्षी, अनुमोदनकर्ता, धर्ता, भोक्ता, महान् स्वामी — र परम आत्मा भनिएको: शरीरमा रहेको यो परम पुरुष।",
         "“साक्षी, स्वीकर्ता, धान्ने, भोग्ने, महान् स्वामी — जसलाई परम आत्मा भनिन्छ: शरीरभित्रको यही सर्वोच्च पुरुष।”"),
"13.23": ("जसले यसरी पुरुष र गुणसहितको प्रकृतिलाई जान्दछ — जस्तोसुकै जीवनशैली भए पनि — ऊ फेरि जन्मँदैन।",
         "“जसले यो पुरुष र गुणसहितको प्रकृतिलाई चिन्छ — जसरी पनि बाँचे पनि — ऊ फेरि कहिल्यै जन्मिँदैन।”"),
"13.24": ("कोही आफूभित्रको आत्मालाई ध्यानद्वारा देख्छन्; कोही ज्ञानयोगद्वारा; अरू कोही कर्मयोगद्वारा।",
         "“कोही आत्मालाई ध्यानले भित्रै देख्छन्; कोही ज्ञानले; अरू कोही निःस्वार्थ कर्मले।”"),
"13.25": ("अरूहरू, नजानेर, अरूबाट सुनेर पूजा गर्छन्; तिनीहरू पनि, सुनिएको कुराप्रति समर्पित भएर, मृत्युलाई पार गर्छन्।",
         "“अरू, प्रत्यक्ष नजानेर, गुरुहरूबाट सुनेर पूजा गर्छन् — र तिनीहरू पनि सुनेको शिक्षाप्रतिको श्रद्धाले मृत्यु पार गर्छन्।”"),
"13.26": ("हे भरतश्रेष्ठ, जुन-जुन प्राणी जन्मिन्छ, चल होस् वा अचल — त्यो क्षेत्र र क्षेत्रज्ञको संयोगबाट उत्पन्न भएको जान।",
         "“जे-जे अस्तित्वमा आउँछ, चल होस् वा स्थिर — त्यो क्षेत्र र त्यसका ज्ञाताको मिलनबाट उठेको जान, अर्जुन।”"),
"13.27": ("जसले सबै प्राणीमा समान रूपमा रहेको, नष्ट हुँदा पनि ननष्ट हुने परम स्वामीलाई देख्छ — उसैले साँच्चै देख्छ।",
         "“जसले सबै प्राणीमा समान रूपमा विद्यमान, मर्नेहरूका बीचमा नमर्ने परम स्वामीलाई देख्छ — उसैले साँच्चै देख्छ।”"),
"13.28": ("किनकि सर्वत्र समान रहेको स्वामीलाई देखेर, ऊ आत्माद्वारा आत्मालाई हानि गर्दैन; त्यसैले ऊ परम लक्ष्यमा पुग्छ।",
         "“सबैमा समान रहेको स्वामीलाई देखेर, ऊ आफ्नो आत्मालाई कहिल्यै होच्याउँदैन; र त्यसैले सर्वोच्च लक्ष्यमा पुग्छ।”"),
"13.29": ("जसले सबै कर्म प्रकृतिले सम्पन्न हुन्छन्, र आत्मा अकर्ता हो — भनी देख्छ, उसैले साँच्चै देख्छ।",
         "“जसले सबै कर्म प्रकृतिले हुन्छन् र आत्मा केही गर्दैन — यो देख्छ, उसैले साँच्चै देख्छ।”"),
"13.30": ("जब ऊ प्राणीहरूका विविध अवस्थाहरू एकै तत्त्वमा विश्राम गरेको र त्यहीबाट फैलिएको देख्छ — तब ऊ ब्रह्म प्राप्त गर्छ।",
         "“जब ऊ सबै प्राणीका विविध अवस्थाहरू एकमा टिकेको र एकैबाट उठेको देख्छ — तब ऊ ब्रह्म हुन्छ।”"),
"13.31": ("आदिरहित र गुणरहित भएकोले, यो परम आत्मा अविनाशी छ — शरीरमा बसे पनि, यो न कर्म गर्छ न दागिन्छ।",
         "“आदिरहित र सबै गुणभन्दा पर भएकोले परम आत्मा नित्य छ — शरीरमा बसे पनि, यो न कर्म गर्छ न लिप्त हुन्छ।”"),
"13.32": ("जसरी सर्वव्यापी आकाश, सूक्ष्म भएर, दागिँदैन, त्यसरी नै हरेक शरीरमा रहेको आत्मा दागिँदैन।",
         "“जसरी व्यापक आकाश, सूक्ष्म हुँदै, कहिल्यै लिप्त हुँदैन, त्यसरी हरेक शरीरमा रहेको आत्मा कहिल्यै लिप्त हुँदैन।”"),
"13.33": ("जसरी एउटै सूर्यले यो सम्पूर्ण संसारलाई उज्यालो बनाउँछ, हे भारत, त्यसरी नै क्षेत्रज्ञले सम्पूर्ण क्षेत्रलाई उज्यालो बनाउँछ।",
         "“जसरी एउटै सूर्यले सम्पूर्ण संसार उज्यालो पार्छ, अर्जुन, त्यसरी क्षेत्रज्ञले सम्पूर्ण क्षेत्र उज्यालो पार्छ।”"),
"13.34": ("जसले ज्ञानको आँखाले क्षेत्र र क्षेत्रज्ञको भेद, र प्रकृतिबाट मुक्ति देख्छन् — तिनीहरू परम तत्त्वमा पुग्छन्।",
         "“जसले ज्ञानको आँखाले क्षेत्र र त्यसका ज्ञाताको अन्तर, र प्रकृतिबाट स्वतन्त्रता देख्छन् — तिनीहरू सर्वोच्चमा पुग्छन्।”"),
"14.01": ("श्रीभगवान्ले भन्नुभयो: म फेरि परम ज्ञान बताउनेछु — सबै ज्ञानमध्ये उत्तम; जसलाई जानेर सबै ऋषिहरू परम सिद्धिमा पुगेका छन्।",
         "कृष्णले भन्नुभयो: “अब म तिमीलाई सर्वोच्च ज्ञान बताउँछु — सबैभन्दा उत्तम; जसलाई जानेर ऋषिहरू परम सिद्धिमा पुगे।”"),
"14.02": ("यस ज्ञानको शरण लिएर, तिनीहरू मेरो स्वरूपसँग एक हुन्छन्; न सृष्टिको आरम्भमा जन्मिन्छन्, न विनाशमा विचलित हुन्छन्।",
         "“यस ज्ञानमा विश्राम गरेर, तिनीहरू मसँग एक हुन्छन्; सृष्टिको उदयमा जन्मँदैनन्, न अन्त्यमा विचलित हुन्छन्।”"),
"14.03": ("मेरो गर्भ महद्ब्रह्म हो; त्यसमा म बीज राख्छु — त्यसबाट सबै प्राणीको जन्म हुन्छ, हे भारत।",
         "“महान् ब्रह्म मेरो गर्भ हो; म त्यसमा बीज राख्छु, र त्यसबाट सबै प्राणी जन्मिन्छन्।”"),
"14.04": ("हे कुन्तीपुत्र, जुन-जुन योनिमा जुन-जुन रूप उत्पन्न हुन्छन् — तिनको गर्भ महद्ब्रह्म हो, र बीज दिने पिता म हुँ।",
         "“जुन-जुन योनिमा जुन-जुन रूप देखा पर्छन् — त्यो योनि महान् ब्रह्म हो, र बीज रोप्ने पिता म हुँ।”"),
"14.05": ("हे महाबाहो, प्रकृतिबाट जन्मेका गुणहरू — सत्त्व, रज र तम — ले शरीरमा अविनाशी देहधारीलाई बाँध्छन्।",
         "“प्रकृतिका गुणहरू — सत्त्व, रज र तम — ले अमर आत्मालाई शरीरमा बाँध्छन्।”"),
"14.06": ("तीमध्ये सत्त्व, शुद्ध भएकोले, प्रकाश दिन्छ र रोगरहित हुन्छ; यसले सुख र ज्ञानमा आसक्ति गराएर बाँध्छ, हे निष्पाप।",
         "“सत्त्व शुद्ध, प्रकाशमय र स्वस्थ छ — तैपनि यसले आनन्द र ज्ञानप्रतिको आसक्तिले बाँध्छ।”"),
"14.07": ("हे कुन्तीपुत्र, रजलाई रागको स्वभाव, तृष्णा र आसक्तिबाट जन्मेको जान; यसले कर्ममा आसक्ति गराएर देहधारीलाई बाँध्छ।",
         "“रज भनेको राग हो, लोभ र मोहबाट जन्मेको; यसले कर्मप्रतिको आसक्तिले देहधारीलाई बाँध्छ।”"),
"14.08": ("हे भारत, तमलाई अज्ञानबाट जन्मेको, सबै देहधारीलाई मोहित गर्ने जान; यसले प्रमाद, आलस्य र निद्राले बाँध्छ।",
         "“तम अज्ञानबाट जन्मेको, सबै प्राणीलाई मोहित गर्ने हो; यसले लापरवाही, अल्छीपन र निद्राले बाँध्छ।”"),
"14.09": ("हे भारत, सत्त्वले सुखमा, रजले कर्ममा टाँस्छ; तमले, ज्ञानलाई ढाकेर, प्रमादमा टाँस्छ।",
         "“सत्त्वले तिमीलाई आनन्दसँग, रजले कर्मसँग, र तम — ज्ञान छोपेर — लापरवाहीसँग जोड्छ।”"),
"14.10": ("रज र तमलाई दबाएर सत्त्व उठ्छ; यसरी सत्त्व र तमलाई दबाएर रज उठ्छ; र दुवैलाई दबाएर तम पनि उठ्छ।",
         "“रज र तममाथि हावी भएर सत्त्व उठ्छ; सत्त्व र तममाथि हावी भएर रज उठ्छ; र दुवैमाथि हावी भएर तम पनि उठ्छ।”"),
"14.11": ("जब यस शरीरका सबै ढोकाहरूबाट ज्ञानको प्रकाश चम्किन्छ, तब सत्त्व बढेको जान।",
         "“जब शरीरका हरेक ढोकाबाट प्रकाश आउँछ, तब बुझ कि सत्त्व प्रबल छ।”"),
"14.12": ("हे भरतश्रेष्ठ, जब रज बढ्छ, तब लोभ, प्रवृत्ति, कर्मको आरम्भ, अशान्ति र तृष्णा उत्पन्न हुन्छन्।",
         "“लोभ, व्यस्तता, परियोजना सुरु गर्नु, बेचैनी र लालसा — यी सबै रज प्रबल हुँदा देखा पर्छन्।”"),
"14.13": ("हे कुरुनन्दन, जब तम बढ्छ, तब अन्धकार, आलस्य, प्रमाद र मोह उत्पन्न हुन्छन्।",
         "“सुस्ती, अकर्मण्यता, लापरवाही र भ्रम — यी तम प्रबल हुँदा उठ्छन्।”"),
"14.14": ("यदि देहधारीले सत्त्व प्रबल हुँदा मृत्यु पाउँछ भने, ऊ परम ज्ञाताहरूका शुद्ध लोकहरूमा पुग्छ।",
         "“सत्त्व प्रबल हुँदा मर्ने व्यक्ति परम जान्नेहरूका शुद्ध लोकमा पुग्छ।”"),
"14.15": ("रजमा मरेर कर्ममा आसक्तहरूका बीच जन्मिन्छ; तममा मरेर मोहितहरूका योनिमा जन्मिन्छ।",
         "“रजमा मर्दा कर्ममा बाँधिएकाहरूका बीच पुनर्जन्म हुन्छ; तममा मर्दा मोहितहरूका बीच।”"),
"14.16": ("असल कर्मको फल शुद्ध र सात्त्विक भनिन्छ; रजको फल दुःख; तमको फल अज्ञान भनिन्छ।",
         "“असल कर्मले सत्त्वको शुद्ध फल दिन्छ; रजले दुःख; तमले अज्ञान।”"),
"14.17": ("सत्त्वबाट ज्ञान उत्पन्न हुन्छ; रजबाट लोभ; तमबाट प्रमाद, मोह र अज्ञान उत्पन्न हुन्छन्।",
         "“सत्त्वबाट ज्ञान; रजबाट लोभ; तमबाट लापरवाही, भ्रम र अज्ञान आउँछ।”"),
"14.18": ("सत्त्वमा स्थितहरू माथि जान्छन्; राजसहरू बीचमा रहन्छन्; सबैभन्दा नीच गुणमा डुबेका तामसहरू तल जान्छन्।",
         "“सात्त्विकहरू माथि उठ्छन्; राजसहरू बीचमा रहन्छन्; नीच गुणमा बाँधिएका तामसहरू तल डुब्छन्।”"),
"14.19": ("जब द्रष्टाले गुणहरूबाहेक अरू कुनै कर्ता देख्दैन, र तिनभन्दा परको तत्त्व जान्दछ — तब ऊ मेरो अवस्था प्राप्त गर्छ।",
         "“जब ज्ञानीले केवल गुणहरूले काम गर्छन् भनी देख्छ, र तिनभन्दा परको तत्त्व चिन्छ — तब ऊ मेरै स्वरूपमा पुग्छ।”"),
"14.20": ("शरीरबाट जन्मेका यी तीन गुणभन्दा माथि उठेर, जन्म, मृत्यु, बुढ्यौली र दुःखबाट मुक्त भएर, देहधारीले अमरत्व चाख्छ।",
         "“शरीरबाट जन्मेका तीन गुणभन्दा पर जाँदा, जन्म, मृत्यु, बुढ्यौली र पीडाबाट मुक्त भएर, देहधारीले अमरत्व चाख्छ।”"),
"14.21": ("अर्जुनले भने: हे प्रभु, यी तीन गुणभन्दा पर गएको मानिसलाई कुन चिह्नले चिनिन्छ? उसको आचरण कस्तो हुन्छ, र उसले तिनलाई कसरी पार गर्छ?",
         "अर्जुन सोध्छन्: “हे प्रभु, तीन गुणभन्दा पर गएको मानिसलाई कसरी चिन्न सकिन्छ? ऊ कसरी बाँच्छ, र तिनलाई कसरी पार गर्छ?”"),
"14.22": ("श्रीभगवान्ले भन्नुभयो: हे पाण्डव, जो न प्रकाश, प्रवृत्ति र मोह आउँदा तिनलाई घृणा गर्छ, न जाँदा तिनको इच्छा गर्छ,",
         "कृष्णले भन्नुभयो: “जो न प्रकाश, क्रिया र भ्रम देखा पर्दा तिनलाई रिसाउँछ, न हराउँदा तिनका लागि तरस्छ,”"),
"14.23": ("— उदासीन बसेको, गुणहरूले नहल्लिएको, 'गुणहरू नै क्रियाशील छन्' भनी सोच्ने र अचल रहने —",
         "“— बेपरवाह दर्शकझैं बसेको, गुणहरूले नहल्लिएको, 'गुणहरू नै काम गर्छन्' भनी सोचेर दृढ उभिने —”"),
"14.24": ("— सुख-दुःखमा समान, आत्मामै स्थित, जसलाई माटो, ढुङ्गा र सुन समान, प्रिय-अप्रियमा समान, दृढ, प्रशंसा-निन्दामा समान —",
         "“— सुख-शोकमा समान, आफूभित्रै सन्तुष्ट, माटो, ढुङ्गा र सुनलाई एकै देख्ने, प्रशंसा-निन्दाले नचल्ने —”"),
"14.25": ("— मान-अपमानमा समान, मित्र-शत्रुमा समान, सबै आरम्भ त्याग्ने — ऊ गुणभन्दा पर गएको भनिन्छ।",
         "“— मान-अपमानमा, मित्र-शत्रुमा समान, सबै स्वार्थी परियोजना छोड्ने — यस्तो व्यक्ति गुणभन्दा पर छ।”"),
"14.26": ("जसले अविचलित भक्तियोगले मेरो सेवा गर्छ — यी गुणहरूलाई पार गरेर, ऊ ब्रह्मको योग्य बन्छ।",
         "“जसले दृढ भक्तिले मेरो सेवा गर्छ — यी गुणहरू पार गरेर — ऊ ब्रह्मको योग्य हुन्छ।”"),
"14.27": ("किनकि म नै ब्रह्मको, अमरत्व र अविनाशीको, सनातन धर्मको र परम सुखको आधार हुँ।",
         "“किनकि म नै ब्रह्मको, अमरत्व र नित्यको — शाश्वत धर्म र परम आनन्दको — आधार हुँ।”"),
"15.01": ("श्रीभगवान्ले भन्नुभयो: माथि जरा र तल हाँगा भएको अविनाशी अश्वत्थको चर्चा गरिन्छ; यसका पातहरू वेदहरू हुन् — जसले यसलाई जान्दछ, ऊ वेदको ज्ञाता हो।",
         "कृष्णले भन्नुभयो: “यसलाई नित्य पीपल भनिन्छ — संसार-वृक्ष, जरा माथि, हाँगा तल। यसका पात वेदहरू हुन्; जसले यसलाई चिन्छ, ऊ वेद चिन्छ।”"),
"15.02": ("यसका हाँगाहरू गुणहरूले पोषित, विषयहरू टुसा भएर, माथि र तल फैलिन्छन्; र तल यसका जराहरू मानव संसारको कर्ममा बाँध्ने गरी फैलिन्छन्।",
         "“यसका हाँगा जताततै फैलिन्छन्, तीन गुणले पोषित, इन्द्रियविषयहरू टुसा भएर; तलका जराहरू मानव संसारमा कर्मसँग बाँध्छन्।”"),
"15.03": ("यसको साँचो रूप यहाँ देखिँदैन, न यसको अन्त्य, न आदि, न आधार; दृढ जरा भएको यस अश्वत्थलाई वैराग्यको बलियो बन्चरोले काटेर,",
         "“यसको साँचो प्रकृति यहाँ देख्न सकिँदैन, न यसको अन्त्य, आदि, न आधार। यस गहिरो जरा भएको पीपललाई वैराग्यको बलियो बन्चरोले काटेर,”"),
"15.04": ("— त्यसपछि त्यो अवस्था खोज्नुपर्छ, जहाँ पुगेर कोही फर्कदैन; म त्यो आदि पुरुषको शरण लिन्छु, जसबाट सनातन प्रवाह बग्छ।",
         "“— र अनि त्यो लक्ष्य खोज्नुपर्छ, जहाँबाट कोही फर्कदैन। म त्यो आदिम पुरुषमा समर्पण गर्छु — शाश्वत धाराको स्रोत।”"),
"15.05": ("अभिमान र मोहबाट मुक्त, आसक्तिको दोष जितेर, सधैं आत्मामै स्थित, कामनाहरू फर्काइएका — सुख-दुःख भनिने द्वन्द्वबाट मुक्त — अमोहितहरू त्यो अविनाशी लक्ष्यमा पुग्छन्।",
         "“अभिमान र भ्रमबाट मुक्त, मोहको दाग जितेर, सधैं आत्मामा बस्ने, इच्छारहित — सुख-शोकभन्दा पर — ज्ञानीहरू त्यो नित्य धाममा पुग्छन्।”"),
"15.06": ("न सूर्य, न चन्द्रमा, न अग्निले मेरो त्यो धामलाई उज्यालो बनाउँछन्; त्यहाँ पुगेर कोही फर्कदैन — त्यही मेरो परम धाम हो।",
         "“मेरो सर्वोच्च घर सूर्य, चन्द्रमा वा आगोले उज्यालो पार्दैन; एकपटक पुगेपछि कोही फर्कदैन — त्यही मेरो परम धाम हो।”"),
"15.07": ("मेरो नै अनन्त अंश, जीवलोकमा जीवात्मा बनेर, प्रकृतिमा रहने इन्द्रियहरूलाई — जसको छैठौं मन हो — आफूतिर तान्छ।",
         "“मेरै नित्य अंश यस संसारमा जीवात्मा बन्छ; यसले प्रकृतिमा रहने पाँच इन्द्रिय र मनलाई आफूतिर तान्छ।”"),
"15.08": ("जब शरीरको स्वामीले शरीर ग्रहण गर्छ, र जब यसलाई छोड्छ — ऊ यी इन्द्रियहरूलाई लिएर जान्छ, जसरी हावाले आफ्नो ठाउँबाट सुगन्ध बोकेर जान्छ।",
         "“जब शरीरको यो स्वामी शरीरमा प्रवेश गर्छ, र जब यसलाई छोड्छ — ऊ इन्द्रियहरूलाई सँगै लैजान्छ, जसरी हावा आफ्नो स्रोतबाट सुगन्ध बोक्छ।”"),
"15.09": ("श्रवण, स्पर्श, दर्शन, रसना र घ्राण, र मनमाथि अधिकार गरेर, ऊ इन्द्रियविषयहरूको भोग गर्छ।",
         "“सुन्ने, छुन, देख्ने, चाख्ने, सुँघ्ने र मनको प्रयोग गरेर, ऊ इन्द्रियका विषयहरूमा रम्छ।”"),
"15.10": ("मोहितहरूले उसलाई — जाँदा, बस्दा वा भोग्दा, वा गुणहरूसँग जोडिएको — देख्दैनन्; तर ज्ञानको आँखा भएकाहरूले देख्छन्।",
         "“मूर्खहरूले उसलाई — जाँदा, बस्दा वा भोग्दा, वा गुणहरूसँग जोडिएको — देख्दैनन्; तर ज्ञानको आँखा भएकाहरूले देख्छन्।”"),
"15.11": ("प्रयत्नशील योगीहरूले उसलाई आत्मामा स्थापित देख्छन्; तर असंयतहरू, प्रयत्न गरे पनि, साँचो समझ नभएर, उसलाई देख्दैनन्।",
         "“प्रयत्नशील योगीहरूले उसलाई आत्मामा स्थापित देख्छन्; तर असंयतहरू, प्रयत्न गरे पनि, साँचो समझ नभएर, उसलाई देख्दैनन्।”"),
"15.12": ("सूर्यमा रहेको, सम्पूर्ण संसारलाई उज्यालो बनाउने ज्योति, र चन्द्रमा र अग्निमा रहेको ज्योति — त्यो ज्योति मेरै हो भनी जान।",
         "“सूर्यको प्रकाश, जसले सम्पूर्ण संसार उज्यालो बनाउँछ, र चन्द्रमा र आगोको प्रकाश — ती सबै मेरै हुन् भनी जान।”"),
"15.13": ("पृथ्वीमा प्रवेश गरेर, म आफ्नो शक्तिले सबै प्राणीलाई धान्छु; रसयुक्त चन्द्रमा बनेर, म सबै औषधि-वनस्पतिलाई पोषण गर्छु।",
         "“म पृथ्वीमा प्रवेश गरेर आफ्नो शक्तिले सबै प्राणी धान्छु; पोषक चन्द्रमा बनेर, म सबै बिरुवालाई स्याहार्छु।”"),
"15.14": ("प्राणीहरूका शरीरमा पाचक अग्नि बनेर, प्राण र अपानसँग जोडिएर, म चार प्रकारको अन्न पकाउँछु।",
         "“सबै जीवित शरीरमा पाचक अग्नि बनेर, श्वाससँग एक भएर, म चार किसिमको अन्न पचाउँछु।”"),
"15.15": ("म सबैको हृदयमा बसेको छु; मबाट नै स्मृति, ज्ञान र तिनको हरण हुन्छ; सबै वेदहरूद्वारा म नै जान्नुपर्ने हुँ — म वेदान्तको कर्ता र वेदको ज्ञाता हुँ।",
         "“म हरेक हृदयमा बस्छु; मबाटै स्मरण, ज्ञान र तिनको हानि आउँछ। सबै वेदले सिकाउने म नै हुँ — तिनका कर्ता र ज्ञाता।”"),
"15.16": ("यस संसारमा दुई पुरुष छन्: क्षर र अक्षर। क्षर त सबै प्राणीहरू हुन्; अपरिवर्तनीय आत्मा अक्षर भनिन्छ।",
         "“संसारमा दुई पुरुष छन्: क्षर र अक्षर। सबै प्राणी क्षर हुन्; अपरिवर्तनीय आत्मा अक्षर हो।”"),
"15.17": ("तर अर्को परम पुरुष छ — परम आत्मा भनिएको — नित्य स्वामी, जसले तीनै लोकमा प्रवेश गरेर तिनलाई धान्छ।",
         "“तर दुवैभन्दा पर सर्वोच्च पुरुष छ — परम आत्मा भनिएको — अपरिवर्तनीय स्वामी, जसले तीनै लोकमा प्रवेश गरेर तिनलाई धान्छ।”"),
"15.18": ("म क्षरभन्दा पर र अक्षरभन्दा माथि भएकोले, संसारमा र वेदमा म पुरुषोत्तम भनी विख्यात छु।",
         "“किनकि म क्षरभन्दा पर र अक्षरभन्दा माथि छु, संसारमा र वेदमा म पुरुषोत्तम — सर्वोच्च पुरुष — भनेर प्रसिद्ध छु।”"),
"15.19": ("हे भारत, जसले, अमोहित भएर, मलाई परम पुरुष जान्दछ — सबै जानेर, ऊ सम्पूर्ण भावले मेरो पूजा गर्छ।",
         "“जो, मोहबाट मुक्त भएर, मलाई परम पुरुष चिन्छ — सबै जानेर, ऊ पूरा हृदयले मेरो पूजा गर्छ, अर्जुन।”"),
"15.20": ("हे निष्पाप, यसरी मैले यो सबैभन्दा गोप्य शास्त्र भनेको छु; यसलाई बुझ्ने मानिस ज्ञानी बन्छ र सबै कर्म पूरा गरेको हुन्छ, हे भारत।",
         "“त्यसैले मैले तिमीलाई यो सबैभन्दा गोप्य शास्त्र सिकाएँ, हे निष्पाप। जसले यसलाई बुझ्छ, ऊ ज्ञानी हुन्छ र आफ्नो सबै उद्देश्य पूरा गर्छ, अर्जुन।”"),
"16.01": ("श्रीभगवान्ले भन्नुभयो: अभय, हृदयको शुद्धता, ज्ञान र योगमा दृढता, दान, संयम, यज्ञ, शास्त्र-अध्ययन, तपस्या र सरलता,",
         "कृष्णले भन्नुभयो: “निर्भयता, हृदयको शुद्धता, ज्ञान र ध्यानमा दृढता, दान, आत्मसंयम, यज्ञ, अध्ययन, तपस्या र इमानदारी,”"),
"16.02": ("— अहिंसा, सत्य, क्रोधरहितता, त्याग, शान्ति, निन्दारहितता, करुणा, अस्पृहता, कोमलता, लज्जा र स्थिरता —",
         "“— अहिंसा, सत्य, क्रोधबाट मुक्ति, त्याग, शान्ति, नकुभल्याउने, करुणा, लोभरहितता, कोमलता, नम्रता र दृढता —”"),
"16.03": ("— तेज, क्षमा, धैर्य, शुद्धता, द्वेषरहितता र अभिमानरहितता — यी हे भारत, दैवी सम्पत्ति भएर जन्मेकाका चिह्न हुन्।",
         "“— ऊर्जा, धैर्य, दृढता, शुद्धता, र द्वेष र अहंकारबाट मुक्ति — यी दैवी प्रकृतिका चिह्न हुन्।”"),
"16.04": ("हे पार्थ, दम्भ, घमण्ड, अभिमान, क्रोध, कठोरता र अज्ञान — यी आसुरी सम्पत्ति भएर जन्मेकाका चिह्न हुन्।",
         "“दम्भ, अहंकार, घमण्ड, क्रोध, कठोरता र अज्ञान — यी आसुरी प्रकृतिका चिह्न हुन्।”"),
"16.05": ("दैवी सम्पत्तिले मुक्ति दिन्छ, आसुरीले बन्धन — हे पाण्डव, शोक नगर, किनकि तिमी दैवी सम्पत्ति लिएर जन्मेका छौ।",
         "“दैवी प्रकृतिले मुक्त गर्छ; आसुरीले बाँध्छ। शोक नगर, अर्जुन — तिमी दैवी प्रकृतिसँग जन्मेका छौ।”"),
"16.06": ("यस संसारमा प्राणीहरूका दुई सृष्टिहरू छन् — दैवी र आसुरी; दैवी विस्तारमा भनियो — हे पार्थ, अब आसुरीको सुन।",
         "“यस संसारमा दुई किसिमका प्राणी छन् — दैवी र आसुरी। दैवीको वर्णन मैले गरें; अब आसुरीको सुन।”"),
"16.07": ("आसुरीहरूले गर्नुपर्ने र नगर्नुपर्ने जान्दैनन्; तिनमा न शुद्धता छ, न सदाचार, न सत्य।",
         "“आसुरीहरू के गर्नुपर्छ र के त्याग्नुपर्छ भनी जान्दैनन् — तिनमा न शुद्धता छ, न असल आचरण, न सत्य।”"),
"16.08": ("तिनीहरू भन्छन्: संसार असत्य छ, आधाररहित छ, स्वामीरहित छ — परस्पर संयोगबाट उत्पन्न, कामनाबाट जन्मेको — अरू के होला र?",
         "“तिनीहरू दाबी गर्छन्: संसार झूटो छ, आधार बिनाको छ, ईश्वर बिनाको छ — संयोग र इच्छाबाट उठेको।”"),
"16.09": ("यो दृष्टि राखेर, यी अल्पबुद्धि नष्ट आत्माहरूले, संसारका शत्रु भएर, यसको विनाशका निम्ति क्रूर कर्म गर्छन्।",
         "“यस दृष्टिकोणले, हराएका मन्दबुद्धि आत्माहरूले, संसारका शत्रु बनेर, यसलाई बर्बाद गर्न निर्दयी काम गर्छन्।”"),
"16.10": ("अतृप्त कामनामा डुबेका, दम्भ, घमण्ड र अहंकारले भरिएका, मोहले झूटा दृष्टि राख्ने तिनीहरू अशुद्ध संकल्पले कर्म गर्छन्।",
         "“कहिल्यै नमेटिने लोभका दास, घमण्ड र अहंकारले फुलेका, तिनीहरू गलत विचारमा टाँसिएर अशुद्ध मनसायले काम गर्छन्।”"),
"16.11": ("मृत्युमा मात्र अन्त्य हुने असीम चिन्ताहरूमा डुबेका, कामनाको भोगमा तत्पर, 'यही नै सबै हो' भनी सोच्ने —",
         "“मृत्युमा मात्र सकिने अनन्त चिन्ताले खपिएर, भोगमा बाँच्ने, तिनीहरू सोच्छन्, 'यही नै सबै छ' —”"),
"16.12": ("— सयौं आशाका बन्धनले बाँधिएका, कामना र क्रोधमा डुबेका, तिनीहरू भोगको निम्ति अन्यायपूर्ण उपायले धन जम्मा गर्न लाग्छन्।",
         "“— सयौं आशाका डोरीले बाँधिएर, इच्छा र क्रोधमा समर्पित, तिनीहरू आफ्ना सुखका निम्ति गलत बाटोबाट धन थुपार्छन्।”"),
"16.13": ("'यो मैले आज पाएँ; यो इच्छा म पूरा गर्नेछु; यो धन मेरो छ — र अझ बढी मेरो हुनेछ,' तिनीहरू सोच्छन् —",
         "“'यो मैले आज पाएँ; त्यो इच्छा भोलि पूरा गर्नेछु; यो मेरो छ, र अझ बढी मेरो हुनेछ,' तिनीहरू घमण्ड गर्छन् —”"),
"16.14": ("'मैले यो शत्रुलाई मारें, र अरूलाई पनि मार्नेछु; म स्वामी हुँ, म भोक्ता हुँ, म सिद्ध, शक्तिशाली र सुखी छु,'",
         "“'मैले त्यो शत्रुलाई मारें, र बाँकीलाई पनि मार्नेछु; म स्वामी, भोगी, सफल, शक्तिशाली र खुसी छु,'”"),
"16.15": ("'म धनी र उच्च कुलको छु; मजस्तो अरू को होला? म यज्ञ गर्नेछु, दान दिनेछु, रम्नेछु' — यसरी अज्ञानले मोहित हुन्छन्।",
         "“'म धनी र कुलीन छु; मेरो बराबरी को हुन सक्छ? म अर्पण गर्नेछु, दान दिनेछु, आनन्द लिनेछु' — यसरी अज्ञानीहरूले आफैंलाई धोका दिन्छन्।”"),
"16.16": ("धेरै विचारले भ्रमित, मोहको जालमा बेरिएका, इन्द्रियसुखमा समर्पित तिनीहरू नराम्रो नरकमा डुब्छन्।",
         "“अगणित विचारले च्यातिएर, भ्रमको जालमा परेर, सुखको लतमा डुबेर — तिनीहरू घृणित नरकमा खस्छन्।”"),
"16.17": ("आत्माभिमानी, जिद्दी, धनको घमण्डले भरिएका, तिनीहरू केवल नामका निम्ति, दम्भले, विधिअनुसार नभई यज्ञ गर्छन्।",
         "“आत्म-महत्त्व र हठले भरिएका, धनको घमण्डमा मात्तिएर, तिनीहरू केवल देखाउन — ढोंगले, शास्त्रअनुसार नभई — यज्ञ गर्छन्।”"),
"16.18": ("अहंकार, बल, घमण्ड, कामना र क्रोधले भरिएका, आफ्नो र अरूको शरीरमा बसेको मलाई घृणा गर्ने यी दुष्ट प्राणीहरू —",
         "“अहंकार, शक्ति, घमण्ड, लोभ र क्रोधले भरिएर, आफ्नो र अरूको हृदयमा बसेको मलाई तुच्छ ठान्ने —”"),
"16.19": ("— यी क्रूर घृणा गर्ने, नराधमहरूलाई, म पुनर्जन्मको चक्रमा बारम्बार आसुरी योनिहरूमा हाल्छु।",
         "“— यी क्रूर, घृणाले भरिएका, सबैभन्दा नीच मानिसहरूलाई म पुनर्जन्मका चक्रहरूमा बारम्बार आसुरी योनिमा फाल्छु।”"),
"16.20": ("आसुरी योनिमा परेर, जन्म-जन्म मोहित भएर, कहिल्यै मकहाँ नपुगी, तिनीहरू सबैभन्दा नीच अवस्थामा डुब्छन्, हे कुन्तीपुत्र।",
         "“आसुरी योनिमा जन्मेर, जीवन-जीवन भ्रममा रहेर, कहिल्यै मलाई नपाएर, तिनीहरू सबैभन्दा नीच अवस्थामा खस्छन्।”"),
"16.21": ("आत्माको नाश गर्ने नरकको यो द्वार त्रिविध छ: कामना, क्रोध र लोभ — त्यसैले यी तीनलाई त्याग।",
         "“नरकतिर जाने र आत्मालाई नष्ट गर्ने तीन ढोका छन्: लोभ, क्रोध र लालच। तीनै छोड।”"),
"16.22": ("हे कुन्तीपुत्र, अन्धकारका यी तीन ढोकाहरूबाट मुक्त भएर, मानिस आफ्नो हितका निम्ति कर्म गर्छ र परम लक्ष्यमा पुग्छ।",
         "“जो यी तीन अन्धकारमय ढोकाबाट बच्छ, अर्जुन, ऊ आफ्नै कल्याणका निम्ति काम गर्छ र सर्वोच्च लक्ष्यमा पुग्छ।”"),
"16.23": ("जसले शास्त्रको विधानलाई थाती राखेर, कामनाको आवेगले कर्म गर्छ — ऊ न सिद्धि पाउँछ, न सुख, न परम लक्ष्य।",
         "“जसले शास्त्रको नियमलाई बेवास्ता गरेर आफ्नो मनोमानीले काम गर्छ — उसलाई न सिद्धि मिल्छ, न आनन्द, न परम लक्ष्य।”"),
"16.24": ("त्यसैले के गर्नुपर्छ र के गर्नु हुँदैन भन्ने निर्णयमा शास्त्र नै तिम्रो प्रमाण होस्; शास्त्रले विधान गरेको जानेर, यहाँ त्यसैअनुसार कर्म गर।",
         "“त्यसैले असल-नराम्रो छुट्याउन शास्त्रलाई नै आफ्नो मार्गदर्शक बनाऊ; यसको आज्ञा जानेर, यहाँ सोहीअनुसार काम गर।”"),
"17.01": ("अर्जुनले भने: हे कृष्ण, जसले शास्त्रको विधानलाई थाती राखेर श्रद्धाले पूजा गर्छन् — तिनको अवस्था के हो? सत्त्व, रज वा तम?",
         "अर्जुन सोध्छन्: “जसले श्रद्धाले पूजा गर्छन् तर शास्त्रका नियम बेवास्ता गर्छन् — तिनको स्थिति के हो, कृष्ण? तिनीहरू सात्त्विक, राजस वा तामस?”"),
"17.02": ("श्रीभगवान्ले भन्नुभयो: देहधारीहरूको श्रद्धा त्रिविध हुन्छ, आफ्नै स्वभावबाट जन्मेको — सात्त्विक, राजस र तामस; यसको बारेमा सुन।",
         "कृष्णले भन्नुभयो: “श्रद्धा तीन किसिमको हुन्छ, आफ्नै प्रकृतिबाट जन्मेको: सात्त्विक, राजस र तामस। सुन।”"),
"17.03": ("हे भारत, हरेकको श्रद्धा उसको स्वभावअनुसार हुन्छ; मानिस श्रद्धाले नै बनेको हुन्छ — जस्तो उसको श्रद्धा, उस्तै ऊ।",
         "“श्रद्धा प्रकृतिलाई पछ्याउँछ, अर्जुन। मानिस आफ्नो श्रद्धाले बन्छ — जसरी विश्वास गर्छ, त्यस्तै बन्छ।”"),
"17.04": ("सात्त्विकहरू देवताहरूको पूजा गर्छन्; राजसहरू यक्ष र राक्षसहरूको; र अरूहरू — तामसहरू — भूत र प्रेतहरूका समूहको पूजा गर्छन्।",
         "“सात्त्विकहरू देवतालाई पुज्छन्; राजसहरू देव-आत्मा र राक्षसलाई; तामसहरू भूत-प्रेत पुज्छन्।”"),
"17.05": ("शास्त्रद्वारा नबताइएका भयानक तपस्या गर्ने, दम्भ र अहंकारले भरिएका, कामना र आसक्तिको बलले प्रेरित मानिसहरू —",
         "“जो घमण्ड र अहंकारले भरिएर, लोभले चलाइएर, शास्त्रले निषेध गरेका कठोर तपस्या गर्छन्,”"),
"17.06": ("— शरीरका तत्त्वहरूलाई र शरीरभित्र बसेको मलाई पनि पीडा दिएर — तिनलाई आसुरी संकल्प भएका जान।",
         "“— शरीरका तत्त्व र शरीरभित्रको मलाई समेत यातना दिएर — तिनलाई आसुरी मनसाय भएका जान।”"),
"17.07": ("खाना पनि, प्रत्येकलाई प्रिय हुने, त्रिविध हुन्छ; र यज्ञ, तपस्या र दान पनि — तिनको भेद सुन।",
         "“खाना, यज्ञ, तपस्या र दान — प्रत्येकका तीन रूप हुन्छन्, स्वभावअनुसार प्रिय। भेद सुन।”"),
"17.08": ("जीवन, शुद्धता, बल, स्वास्थ्य, आनन्द र प्रसन्नता बढाउने — रसिलो, चिल्लो, दृढ र मनपर्ने आहारहरू सात्त्विकहरूलाई प्रिय हुन्छन्।",
         "“जीवन, स्पष्टता, बल, स्वास्थ्य, आनन्द र सन्तोष बढाउने — रसदार, कोमल, पोषक र रमाइलो — यस्ता खाना सात्त्विकलाई मनपर्छ।”"),
"17.09": ("तितो, अमिलो, नुनिलो, धेरै तातो, पिरो, सुक्खा र बल्ने — पीडा, शोक र रोग ल्याउने आहारहरू राजसहरूलाई प्रिय हुन्छन्।",
         "“तितो, अमिलो, नुनिलो, झन्डै बल्ने, पिरो, सुक्खा र जलन दिने — दुःख, शोक र रोग ल्याउने — यस्ता खाना राजसलाई मनपर्छ।”"),
"17.10": ("बासी, स्वादहीन, गलेको र जुठो खाना, र अशुद्ध बचेका — यस्तो खाना तामसहरूलाई प्रिय हुन्छ।",
         "“बासी, बेस्वाद, बिग्रेको वा जुठो खाना, र फोहोर बचेका — यस्तो खाना तामसलाई मनपर्छ।”"),
"17.11": ("शास्त्रद्वारा विधान गरिएको, 'यो गर्नैपर्छ' भनी सोच्नेहरूद्वारा फलको इच्छा बिना गरिएको यज्ञ — त्यो सात्त्विक हो।",
         "“शास्त्रअनुसार, फलको आशा नगरी, 'यो गर्नैपर्छ' भन्ने विश्वासले गरिएको यज्ञ — त्यो सात्त्विक हो।”"),
"17.12": ("तर हे भरतश्रेष्ठ, फल खोजेर र देखावटका निम्ति गरिएको यज्ञ — त्यसलाई राजस जान।",
         "“तर फलका निम्ति वा देखाउनका निम्ति गरिएको यज्ञ — त्यसलाई राजस जान।”"),
"17.13": ("विधि बिना, अन्न-दान बिना, मन्त्र बिना, दक्षिणा बिना, श्रद्धारहित गरिएको यज्ञ — तामस भनिएको छ।",
         "“उचित विधि बिना, अर्पण बिना, मन्त्र बिना, दान बिना र श्रद्धा बिनाको यज्ञ — त्यो तामस हो।”"),
"17.14": ("देवता, द्विज, गुरु र ज्ञानीहरूको पूजा; शुद्धता, सरलता, ब्रह्मचर्य र अहिंसा — यो शरीरको तपस्या हो।",
         "“देवता, विद्वान्, गुरु र ऋषिहरूको सम्मान; शुद्धता, इमानदारी, ब्रह्मचर्य र अहिंसा — यो शारीरिक तपस्या हो।”"),
"17.15": ("दुःख नदिने, सत्य, मीठो र हितकारी वाणी, र नियमित शास्त्र-अध्ययन — यो वाणीको तपस्या हो।",
         "“कोमल, सत्य, रमाइलो र हितकारी बोली, साथै दैनिक शास्त्र पाठ — यो वाणीको तपस्या हो।”"),
"17.16": ("मनको प्रसन्नता, कोमलता, मौनता, आत्मसंयम र हृदयको शुद्धता — यो मनको तपस्या भनिन्छ।",
         "“शान्त मन, दयालुता, मौन, आत्मसंयम र भित्री शुद्धता — यो मानसिक तपस्या हो।”"),
"17.17": ("यो त्रिविध तपस्या, दृढ व्यक्तिहरूद्वारा परम श्रद्धाले, फलको इच्छा बिना गरिएको — सात्त्विक भनिएको छ।",
         "“यो त्रिविध साधना, दृढ संकल्प भएकाहरूद्वारा ठूलो श्रद्धाले, बदलामा केही नचाहेर गरिएको — सात्त्विक भनिन्छ।”"),
"17.18": ("सम्मान, आदर र पूजाका निम्ति, र दम्भले गरिएको तपस्या — यहाँ राजस भनिएको छ, अस्थिर र क्षणिक।",
         "“प्रसिद्धि, सम्मान र प्रशंसाका निम्ति, र ढोंगले गरिएको तप — त्यो राजस हो: अस्थिर र क्षणभंगुर।”"),
"17.19": ("मूर्खतापूर्ण जिद्दीले, आत्म-यातनाले, वा अरूलाई नष्ट गर्नका निम्ति गरिएको तपस्या — तामस भनिएको छ।",
         "“मूर्ख हठले, आफैंलाई यातना दिएर, वा अरूलाई हानि पुर्‍याउनका निम्ति गरिएको तप — त्यो तामस हो।”"),
"17.20": ("दिनैपर्छ भनेर, बदलामा केही नसक्नेलाई, उचित ठाउँ र समयमा, योग्य व्यक्तिलाई दिइएको दान — सात्त्विक मानिन्छ।",
         "“दिनु नै सही हो भनेर, कहिल्यै फर्काउन नसक्नेलाई, उचित ठाउँ-समयमा, योग्य व्यक्तिलाई दिइएको दान — त्यो सात्त्विक हो।”"),
"17.21": ("तर बदलामा केही अपेक्षा गरेर, फेरि फल खोजेर, वा अनिच्छाले दिइएको दान — राजस मानिन्छ।",
         "“केही फर्कने आशाले, पुरस्कार खोजेर, वा मन नलागी दिइएको दान — त्यो राजस हो।”"),
"17.22": ("गलत ठाउँ र समयमा, अयोग्य व्यक्तिलाई, बिना आदर र हेलाले दिइएको दान — तामस भनिएको छ।",
         "“गलत समय-स्थानमा, अयोग्यलाई, बिना सम्मान वा तिरस्कारसहित दिइएको दान — त्यो तामस हो।”"),
"17.23": ("ॐ तत् सत् — ब्रह्मको यो त्रिविध पदनाम हो; यसद्वारा नै प्राचीनकालमा ब्राह्मण, वेद र यज्ञहरू विधान गरिएका थिए।",
         "“ॐ तत् सत् — ब्रह्मको यो त्रिविध नाम हो। यसैद्वारा धेरै अघि ब्राह्मण, वेद र यज्ञहरू सृष्टि गरिएका थिए।”"),
"17.24": ("त्यसैले, ॐ उच्चारण गरेर, शास्त्रद्वारा विधान गरिएका यज्ञ, दान र तपस्या-कर्महरू, ब्रह्मज्ञहरूद्वारा सधैं सुरु गरिन्छन्।",
         "“त्यसैले ब्रह्मज्ञहरू ॐ उच्चारण गरेर — शास्त्रले विधान गरेअनुसार — हरेक यज्ञ, दान र तपस्या सुरु गर्छन्।”"),
"17.25": ("फलको इच्छा नगरी, 'तत्' उच्चारण गरेर, मुक्तिका खोजीहरूद्वारा यज्ञ, तपस्या र विविध दानका कर्महरू गरिन्छन्।",
         "“मुक्तिका खोजीहरू — 'तत्' भनेर, कुनै पुरस्कार नचाहेर — यज्ञ, तपस्या र हरेक किसिमको दान गर्छन्।”"),
"17.26": ("हे पार्थ, 'सत्' शब्द सत्य र असलपनको अर्थमा प्रयोग हुन्छ, र शुभ कर्महरूमा पनि।",
         "“'सत्' को अर्थ सत्य र असलपन हो; यो श्रेष्ठ कर्महरूमा पनि प्रयोग हुन्छ, अर्जुन।”"),
"17.27": ("यज्ञ, तपस्या र दानमा स्थिरता पनि 'सत्' भनिन्छ; र त्यसैका निम्ति गरिएको कर्म पनि 'सत्' भनिन्छ।",
         "“यज्ञ, तपस्या र दानमा दृढता 'सत्' भनिन्छ; त्यसैका निम्ति गरिएको कुनै पनि कर्म पनि 'सत्' हो।”"),
"17.28": ("हे पार्थ, श्रद्धा बिना चढाइएको, दिइएको, गरिएको वा सम्पन्न भएको जे-जे छ — त्यो 'असत्' भनिन्छ; यहाँ वा परलोकमा त्यो केही होइन।",
         "“श्रद्धा बिना चढाइएको, दिइएको, गरिएको वा सम्पन्न भएको जे-जे छ — त्यो 'असत्' हो; यहाँ पनि केही होइन, मृत्युपछि पनि केही होइन।”"),
"18.01": ("अर्जुनले भने: हे महाबाहो, म संन्यासको सत्य जान्न चाहन्छु, हे हृषीकेश, र त्यागको पनि, र दुवैको भेद, हे केशिनिषूदन।",
         "अर्जुन सोध्छन्: “कृपया संन्यास र त्यागको सत्य बताउनुहोस्, कृष्ण — र तिनीहरू कसरी फरक छन्।”"),
"18.02": ("श्रीभगवान्ले भन्नुभयो: कामनापूर्ण कर्महरूको त्यागलाई ज्ञानीहरू संन्यास भन्छन्; सबै कर्मफलको त्यागलाई ज्ञानीहरू त्याग भन्छन्।",
         "कृष्णले भन्नुभयो: “स्वार्थी कर्म त्याग्नुलाई ज्ञानीहरू संन्यास भन्छन्; सबै कर्मको फल त्याग्नुलाई तिनीहरू त्याग भन्छन्।”"),
"18.03": ("केही ज्ञानीहरू कर्म दोषपूर्ण भएर त्याग्नुपर्छ भन्छन्; अरूहरू यज्ञ, दान र तपस्या त्याग्नु हुँदैन भन्छन्।",
         "“केही विचारकहरू कर्म नै दोषपूर्ण र त्याग्न योग्य भन्छन्; अरूहरू यज्ञ, दान र तप कहिल्यै त्याग्नु हुँदैन भन्छन्।”"),
"18.04": ("हे भरतश्रेष्ठ, त्यागबारे मेरो निश्चित निष्कर्ष सुन; हे नरश्रेष्ठ, त्याग त्रिविध भनिएको छ।",
         "“हे अर्जुन, त्यागबारे मेरो स्थिर दृष्टिकोण सुन — किनकि त्याग तीन किसिमको भनिएको छ।”"),
"18.05": ("यज्ञ, दान र तपस्या-कर्महरू त्याग्नु हुँदैन; ती गर्नैपर्छ, किनकि ती ज्ञानीलाई पनि शुद्ध पार्छन्।",
         "“यज्ञ, दान र तप कहिल्यै त्याग्नु हुँदैन — ती ज्ञानीलाई पनि शुद्ध गर्छन् र गर्नैपर्छ।”"),
"18.06": ("तर हे पार्थ, यी कर्महरू पनि आसक्ति र फल त्यागेर गर्नुपर्छ — यो मेरो निश्चित र उत्तम विश्वास हो।",
         "“तैपनि यी पनि आसक्ति र फलको आशा बिना गर्नुपर्छ — यो मेरो दृढ र अन्तिम दृष्टि हो।”"),
"18.07": ("विहित कर्मको त्याग उचित होइन; मोहले त्यसलाई त्याग्नु तामस भनिएको छ।",
         "“आफ्नो विहित कर्तव्य त्याग्नु गलत हो — भ्रमले त्याग्नु तामस हो।”"),
"18.08": ("जसले दुःख आउँछ भनी, शारीरिक कष्टको डरले कर्म त्याग्छ — राजस त्याग गर्ने त्यो व्यक्तिले त्यागको फल पाउँदैन।",
         "“जसले काम गाह्रो वा पीडादायक भएर छोड्छ — ऊ राजस त्याग गर्छ र त्यसबाट केही पाउँदैन।”"),
"18.09": ("तर हे अर्जुन, गर्नैपर्छ भनेर, आसक्ति र फल त्यागेर गरिएको विहित कर्म — त्यो सात्त्विक त्याग मानिन्छ।",
         "“तर कर्तव्य कर्तव्य भएर, बिना आसक्ति र बिना फलको आशा गरिएको — त्यो सात्त्विक त्याग हो।”"),
"18.10": ("सत्त्वयुक्त, दृढ समझ भएको सात्त्विक त्यागीले न अप्रिय कर्मलाई घृणा गर्छ, न प्रिय कर्ममा टाँसिन्छ।",
         "“ज्ञानी र स्पष्ट दृष्टि भएको सात्त्विक त्यागी न त अप्रिय कामलाई रिसाउँछ, न प्रिय काममा आसक्त हुन्छ।”"),
"18.11": ("निश्चय नै देहधारीले सबै कर्म पूरै त्याग्न सक्दैन; तर जसले कर्मफल त्याग्छ, ऊ साँचो त्यागी भनिन्छ।",
         "“कुनै पनि देहधारीले सबै कर्म छोड्न सक्दैन; तर जसले कर्मको फल त्याग्छ, ऊ साँचो त्यागी हो।”"),
"18.12": ("अनन्य त्यागीका निम्ति कर्मको त्रिविध फल — प्रिय, अप्रिय र मिश्रित — मृत्युपछि आउँछ; त्यागीका निम्ति कहिल्यै होइन।",
         "“कर्मका तीन फल — असल, नराम्रो र मिश्रित — मृत्युपछि त्यागी नभएकालाई मिल्छन्; त्यागीलाई कहिल्यै होइन।”"),
"18.13": ("हे महाबाहो, कर्मको अन्त्यको दर्शनमा (साङ्ख्यशास्त्रमा) भनिएका सबै कर्मका यी पाँच कारणहरू मबाट सिक:",
         "“वेदान्तको साङ्ख्यमा सिकाइएका सबै कर्मका पाँच कारणहरू मबाट सिक:”"),
"18.14": ("— आधार, कर्ता, करणहरू, विविध चेष्टाहरू, र पाँचौं दैव।",
         "“— शरीर, कर्ता, इन्द्रियहरू, विविध प्रयासहरू, र पाँचौं भाग्य।”"),
"18.15": ("मानिसले शरीर, वाणी वा मनले जुन-जुन कर्म गर्छ — ठीक वा गलत — यी पाँच नै त्यसका कारण हुन्।",
         "“मानिसले शरीर, वाणी वा मनले जे-जे गर्छ — सही वा गलत — यी पाँच नै त्यसका कारण हुन्।”"),
"18.16": ("त्यसो भएकोले, जसले — अपूर्ण समझले — आत्मालाई मात्र कर्ता देख्छ, उसैले साँच्चै देख्दैन।",
         "“त्यसैले, जसले — सीमित दृष्टिले — आत्मालाई मात्र कर्ता ठान्छ, ऊ ठीकसँग देख्दैन।”"),
"18.17": ("जसको मन अहंकाररहित छ, जसको बुद्धि दागिएको छैन — उसले यी लोकहरूलाई मारे पनि, ऊ मार्दैन, न बाँधिन्छ।",
         "“जो अहंकाररहित छ, जसको बुद्धि निष्कलङ्क छ — यी मानिसहरूलाई मारे पनि, ऊ केही मार्दैन, र बाँधिँदैन।”"),
"18.18": ("ज्ञान, ज्ञेय र ज्ञाता — कर्मको त्रिविध प्रेरणा; करण, कर्म र कर्ता — कर्मको त्रिविध आधार।",
         "“ज्ञान, विषय र ज्ञाता — कर्मको त्रिविध प्रेरणा; साधन, कर्म र कर्ता — यसको त्रिविध आधार।”"),
"18.19": ("गुणहरूको भेदले ज्ञान, कर्म र कर्ता त्रिविध भनिएका छन् — गुणको गणनामा तिनलाई यसरी सुन।",
         "“ज्ञान, कर्म र कर्ता — प्रत्येक गुणअनुसार तीन किसिमका भनिएका छन्; तिनलाई पूरै सुन।”"),
"18.20": ("जसद्वारा सबै प्राणीमा एउटै अविनाशी तत्त्व देखिन्छ, विभाजितमा अविभाजित — त्यो ज्ञान सात्त्विक जान।",
         "“जसले सबै प्राणीमा एउटै नित्य तत्त्व देख्छ, विभाजितमा अविभाजित — त्यो ज्ञान सात्त्विक हो।”"),
"18.21": ("तर जसले सबै प्राणीमा अनेक र पृथक् प्राणीहरू देख्छ — त्यो ज्ञान राजस जान।",
         "“तर जसले सबै प्राणीलाई धेरै र छुट्टाछुट्टै देख्छ — त्यो ज्ञान राजस हो।”"),
"18.22": ("र जुन ज्ञान एउटै कार्यलाई नै सबै हो भनी टाँसिन्छ, बिना कारण, बिना सत्य, तुच्छ — त्यो तामस भनिएको छ।",
         "“र जुन ज्ञान एउटा सानो अंशलाई नै सबै ठान्छ, अतार्किक, असत्य र सतही — त्यो तामस हो।”"),
"18.23": ("विधिअनुसार, आसक्ति बिना, राग-द्वेष बिना, फल नचाहनेले गरिएको कर्म — सात्त्विक भनिएको छ।",
         "“कर्तव्यका रूपमा, बिना आसक्ति, बिना रुचि-अरुचि, पुरस्कार नचाहनेले गरिएको कर्म — त्यो सात्त्विक हो।”"),
"18.24": ("तर ठूलो प्रयासले, कामनाको पूर्ति खोजेर, अहंकारले भरिएर गरिएको कर्म — राजस भनिएको छ।",
         "“ठूलो तनावले, इच्छाहरूको लालसा गरेर, आत्म-महत्त्वले भरिएर गरिएको कर्म — त्यो राजस हो।”"),
"18.25": ("मोहले सुरु गरिएको, परिणाम, हानि र आफ्नो क्षमताको परवाह नगर्ने कर्म — तामस भनिएको छ।",
         "“भ्रममा सुरु गरिएको, परिणाम, त्यसले पुर्‍याउने हानि र आफ्नो शक्तिको बेवास्ता गर्ने कर्म — त्यो तामस हो।”"),
"18.26": ("आसक्तिरहित, अहंकाररहित, दृढ र उत्साही, सफलता-असफलताले नचल्ने कर्ता — सात्त्विक भनिएको छ।",
         "“आसक्ति-रहित, अहंकार-रहित, स्थिर र ऊर्जावान्, जित-हारले नछुने कर्ता — त्यो सात्त्विक हो।”"),
"18.27": ("रागले भरिएको, कर्मफलको लोभी, लोभी, क्रूर, अशुद्ध, हर्ष-शोकले चल्ने कर्ता — राजस भनिएको छ।",
         "“भावुक, फलको भोको, लोभी, क्रूर, अशुद्ध, उल्लास-निराशाले डुल्ने कर्ता — त्यो राजस हो।”"),
"18.28": ("असंयत, असभ्य, जिद्दी, कपटी, दुष्ट, अल्छी, निराश र ढिलाइ गर्ने कर्ता — तामस भनिएको छ।",
         "“अनुशासनहीन, कठोर, जिद्दी, ढोंगी, बेइमान, अल्छी, उदास र ढिलो कर्ता — त्यो तामस हो।”"),
"18.29": ("हे धनञ्जय, गुणअनुसार बुद्धि र धृतिको त्रिविध भेद, पूरै र छुट्टाछुट्टै रूपमा सुन।",
         "“अब सुन, अर्जुन, गुणअनुसार बुद्धि र संकल्प तिन-तिन किसिमका कसरी छुट्याइन्छन्।”"),
"18.30": ("जसले कर्म र अकर्म, असल-नराम्रो, भय र अभय, बन्धन र मुक्ति जान्दछ — त्यो बुद्धि सात्त्विक हो।",
         "“जुन समझले गर्नुपर्ने र नगर्नुपर्ने, असल-नराम्रो, बन्धन र स्वतन्त्रता चिनिन्छ — त्यो सात्त्विक हो।”"),
"18.31": ("जसले असल र नराम्रोलाई गलत रूपमा जान्दछ — त्यो, हे पार्थ, राजस हो।",
         "“जुन समझले असल-नराम्रोलाई उल्टो बुझ्छ — त्यो, अर्जुन, राजस हो।”"),
"18.32": ("अन्धकारले ढाकिएको, नराम्रोलाई राम्रो ठान्ने र सबै कुरा उल्टो देख्ने बुद्धि — तामस हो।",
         "“अन्धकारमा बेरिएको, नराम्रोलाई राम्रो मान्ने र सबै कुरा उल्टो देख्ने समझ — त्यो तामस हो।”"),
"18.33": ("जसद्वारा मन, प्राण र इन्द्रियका क्रियाहरूलाई रोकिन्छ — त्यो दृढ धृति, हे पार्थ, सात्त्विक हो।",
         "“जुन दृढ संकल्पले मन, श्वास र इन्द्रियलाई काबूमा राखिन्छ — त्यो, अर्जुन, सात्त्विक हो।”"),
"18.34": ("तर जुन धृतिले धर्म, काम र अर्थमा, आसक्त भएर र फल चाहेर टाँसिन्छ — त्यो, हे अर्जुन, राजस हो।",
         "“तर जुन संकल्प धर्म, भोग र धनमा, आसक्त भएर र तिनको फलको लोभले टाँसिन्छ — त्यो राजस हो।”"),
"18.35": ("जुन धृतिले मन्द बुद्धिले निद्रा, भय, शोक, निराशा र घमण्ड छोड्न सक्दैन — त्यो तामस हो।",
         "“र जुन संकल्पले मूर्ख मानिस निद्रा, डर, शोक, निराशा र घमण्ड छोड्न सक्दैन — त्यो तामस हो।”"),
"18.36": ("हे भरतश्रेष्ठ, अब मबाट त्रिविध सुख सुन — जसमा अभ्यासले रमिन्छ र दुःखको अन्त्यमा पुगिन्छ।",
         "“अब सुन, अर्जुन, सुखका तीन रूप — त्यो आनन्द जसमा अभ्यासले रमिन्छ र पीडाको अन्त्यमा पुगिन्छ।”"),
"18.37": ("जुन पहिले विषझैं र अन्त्यमा अमृतझैं हुन्छ — आत्माको स्पष्टताबाट जन्मेको — त्यो सात्त्विक सुख भनिएको छ।",
         "“जुन आनन्द पहिले तितो तर अन्त्यमा अमृत हुन्छ — आत्मज्ञानबाट जन्मेको — त्यो सात्त्विक सुख हो।”"),
"18.38": ("इन्द्रिय र विषयको सम्पर्कबाट जन्मेको, पहिले अमृत र अन्त्यमा विषझैं हुने सुख — राजस भनिएको छ।",
         "“इन्द्रिय र विषयको भेटबाट उठ्ने, पहिले मीठो तर अन्त्यमा विषजस्तो हुने आनन्द — त्यो राजस हो।”"),
"18.39": ("सुरु र अन्त्य दुवैमा आत्मालाई मोहित गर्ने, निद्रा, आलस्य र प्रमादबाट जन्मेको सुख — तामस भनिएको छ।",
         "“सुरुदेखि अन्त्यसम्म आत्मालाई स्तब्ध पार्ने, निद्रा, अल्छीपन र लापरवाहीबाट जन्मेको आनन्द — त्यो तामस हो।”"),
"18.40": ("प्रकृतिबाट जन्मेका यी तीन गुणहरूबाट मुक्त — पृथ्वीमा कोही पनि छैन, न स्वर्गका देवताहरूमै।",
         "“पृथ्वीमा कोही पनि — स्वर्गका देवताहरू पनि — प्रकृतिका यी तीन गुणबाट मुक्त छैनन्।”"),
"18.41": ("हे शत्रुतापन, ब्राह्मण, क्षत्रिय, वैश्य र शूद्रका कर्तव्यहरू आफ्नै स्वभावबाट जन्मेका गुणअनुसार विभक्त छन्।",
         "“चार वर्गहरू — पुरोहित, योद्धा, व्यापारी, मजदुर — का कर्तव्य तिनको आफ्नै प्रकृतिका गुणले निर्धारित हुन्छन्।”"),
"18.42": ("शान्ति, संयम, तपस्या, शुद्धता, धैर्य, सरलता, ज्ञान, विज्ञान र श्रद्धा — स्वभावबाट जन्मेको ब्राह्मणको कर्तव्य।",
         "“शान्ति, आत्मसंयम, तप, शुद्धता, धैर्य, इमानदारी, ज्ञान, विवेक र श्रद्धा — यी ब्राह्मणका स्वाभाविक कर्तव्य हुन्।”"),
"18.43": ("शौर्य, तेज, धैर्य, दक्षता, युद्धमा नभाग्नु, दान र स्वामित्व — स्वभावबाट जन्मेको क्षत्रियको कर्तव्य।",
         "“साहस, तेज, दृढता, निपुणता, युद्धमा नपछि हट्नु, उदारता र नेतृत्व — यी योद्धाका स्वाभाविक कर्तव्य हुन्।”"),
"18.44": ("खेती, गोरु पालन र व्यापार — स्वभावबाट जन्मेको वैश्यको कर्तव्य; र सेवा — शूद्रको कर्तव्य।",
         "“खेती, गोठालो र व्यापार वैश्यको स्वाभाविक काम; सेवा शूद्रको।”"),
"18.45": ("आफ्नो कर्तव्यमा समर्पित भएर मानिस सिद्धि पाउँछ — आफ्नै काममा रम्ने व्यक्ति कसरी सिद्ध हुन्छ, त्यो सुन।",
         "“आफ्नो कर्तव्य गर्दा मानिस सिद्धिमा पुग्छ — आफ्नै काममा रम्नेले कसरी सफल हुन्छ, त्यो सुन।”"),
"18.46": ("जसबाट यो सबै व्याप्त छ, सबै प्राणीको स्रोत — त्यसको पूजा आफ्नै कर्तव्यद्वारा गरेर, मानिस सिद्धि पाउँछ।",
         "“आफ्नो कर्तव्य गर्दा मानिसले त्यो एकको पूजा गर्छ जसबाट सबै प्राणी उठ्छन् र जसद्वारा सबै व्याप्त छ — र यसरी सिद्धिमा पुग्छ।”"),
"18.47": ("आफ्नो धर्म, यद्यपि दोषपूर्ण, पराया सुसम्पन्न धर्मभन्दा राम्रो; आफ्नै स्वभावबाट जन्मेको काम गर्दा मानिस पापमा लाग्दैन।",
         "“आफ्नो कर्तव्य त्रुटिपूर्ण भए पनि अरूको पूर्ण गरिएको भन्दा राम्रो। आफ्नो प्रकृतिबाट जन्मेको काम गर्दा कुनै पाप लाग्दैन।”"),
"18.48": ("हे कुन्तीपुत्र, आफ्नो स्वाभाविक कर्म दोषपूर्ण भए पनि त्यसलाई त्याग्नु हुँदैन; किनकि सबै आरम्भहरू दोषले ढाकिएका हुन्छन्, जसरी आगो धुवाँले।",
         "“आफ्नो प्रकृतिबाट जन्मेको काम, त्रुटि भए पनि, कहिल्यै नछोड — सबै परियोजना दोषले रङ्गिएका हुन्छन्, जसरी आगो धुवाँले।”"),
"18.49": ("आसक्तिरहित, आत्मजित, इच्छारहित व्यक्तिले संन्यासद्वारा कर्मरहितताको परम सिद्धि पाउँछ।",
         "“आसक्ति-रहित, आत्मविजयी, लोभरहित व्यक्ति त्यागद्वारा कर्मरहितताको सर्वोच्च सिद्धिमा पुग्छ।”"),
"18.50": ("हे कुन्तीपुत्र, यो सिद्धि पाएको व्यक्ति कसरी ब्रह्ममा पुग्छ — ज्ञानको त्यो परम अवस्था — मबाट सिक।",
         "“हे अर्जुन, यो सिद्धिमा पुगेको व्यक्ति कसरी ब्रह्मतिर जान्छ — ज्ञानको सर्वोच्च अवस्था — मबाट सुन।”"),
"18.51": ("शुद्ध बुद्धिले युक्त, धैर्यले आत्मालाई दृढ गरेर, शब्द आदि विषयहरू त्यागेर, राग-द्वेष छोडेर,",
         "“शुद्ध मनले, आत्मालाई दृढ राखेर, शब्द र अरू इन्द्रियविषयबाट फर्केर, रुचि-अरुचि छाडेर,”"),
"18.52": ("— एकान्तमा बस्दै, थोरै खाँदै, वाणी, शरीर र मन संयत गरेर, सधैं ध्यान र चिन्तनमा लागेर,",
         "“— अलग बसेर, कम खाएर, वाणी, शरीर र मनमाथि विजय पाएर, सधैं ध्यानमा तल्लीन भएर,”"),
"18.53": ("— अहंकार, बल, घमण्ड, कामना, क्रोध र ममता त्यागेर, शान्त, 'मेरो' भन्न नछोड्ने — यस्तो व्यक्ति ब्रह्मको योग्य बन्छ।",
         "“— अहंकार, शक्ति, घमण्ड, लोभ, क्रोध र मोह छाडेर, शान्त, 'मेरो' भन्न नराख्ने — यस्तो व्यक्ति ब्रह्मको योग्य हुन्छ।”"),
"18.54": ("ब्रह्मभूत, प्रसन्न आत्मा भएर, ऊ न शोक गर्छ न इच्छा; सबै प्राणीप्रति समान भएर, ऊ मप्रति परम भक्ति पाउँछ।",
         "“ब्रह्मसँग एक, शान्त हृदय, ऊ न शोक गर्छ न लालसा; सबैलाई समान देखेर, ऊ मप्रति सर्वोच्च भक्ति जित्छ।”"),
"18.55": ("त्यो भक्तिले ऊ मलाई साँच्चै जान्दछ — म को र के हुँ; मलाई साँच्चै जानेर, ऊ तुरुन्तै ममा प्रवेश गर्छ।",
         "“त्यो भक्तिले ऊ मलाई साँच्चै चिन्छ — के र को हुँ; र मलाई साँच्चै चिनेर, ऊ तुरुन्तै ममा प्रवेश गर्छ।”"),
"18.56": ("सबै कर्म सधैं गर्दै, मेरो शरण लिएर, ऊ मेरो कृपाले नित्य, अविनाशी अवस्था पाउँछ।",
         "“सधैं सबै कर्म गर्दै, ममा विश्राम गरेर, ऊ मेरो कृपाले नित्य, अपरिवर्तनीय अवस्थामा पुग्छ।”"),
"18.57": ("विचारले सबै कर्म ममा अर्पण गरेर, मलाई परम मानेर, विवेकयोगको सहारा लिएर, मन ममा स्थिर गर।",
         "“मनमै हरेक कर्म मलाई अर्पण गर, मलाई सर्वोच्च मान, र ज्ञानयोगमा भरोसा गरेर, हृदय ममा राख।”"),
"18.58": ("मन ममा भए तिमी मेरो कृपाले सबै कठिनाइ पार गर्नेछौ; तर अहंकारले नसुन्यौ भने, तिमी नष्ट हुनेछौ।",
         "“मन ममा टिकेपछि तिमी मेरो कृपाले सबै बाधा पार गर्नेछौ। तर अहंकारले अस्वीकार गर्यौ भने — तिमी हराउनेछौ।”"),
"18.59": ("यदि अहंकारले 'म लड्नेछैन' भनी सोच्छौ भने — तिम्रो संकल्प व्यर्थ छ; तिम्रो प्रकृतिले नै तिमीलाई बाध्य गर्नेछ।",
         "“यदि अहंकारले 'म लड्दिनँ' भनी सोच्छौ भने — त्यो संकल्प निरर्थक छ; तिम्रो आफ्नै प्रकृतिले तिमीलाई जबरजस्ती गर्नेछ।”"),
"18.60": ("हे कुन्तीपुत्र, आफ्नै प्रकृतिबाट जन्मेको कर्मले बाँधिएर, तिमीले नचाहेको काम — त्यो पनि असहाय भएर गर्नेछौ।",
         "“आफ्नै प्रकृतिबाट जन्मेको कर्मले बाँधिएर, अर्जुन, तिमी नचाहँदा नचाहँदै पनि, असहाय भएर, जे गर्न चाहँदैनौ त्यही गर्नेछौ।”"),
"18.61": ("हे अर्जुन, भगवान् सबै प्राणीको हृदयमा बस्छन्, आफ्नो मायाले सबै प्राणीलाई, मानौं यन्त्रमा चढेका पुतलीहरूझैं, घुमाइरहन्छन्।",
         "“भगवान् हरेक प्राणीको हृदयमा बस्छन्, आफ्नो शक्तिको चक्रमा सबै प्राणीलाई, यन्त्रमा चढेका पुतलीझैं, घुमाइरहन्छन्।”"),
"18.62": ("हे भारत, सम्पूर्ण भावले केवल उहाँकै शरण जाऊ; उहाँको कृपाले तिमी परम शान्ति र नित्य धाम पाउनेछौ।",
         "“पूरा हृदयले, अर्जुन, केवल उहाँकै शरण लेऊ; उहाँको कृपाले तिमीलाई परम शान्ति र नित्य घर मिल्नेछ।”"),
"18.63": ("यसरी मैले तिमीलाई रहस्यभन्दा पनि गोप्य यो ज्ञान भनें; यसमा पूरै विचार गर, र जे इच्छा लाग्छ त्यही गर।",
         "“त्यसैले मैले तिमीलाई यो ज्ञान सिकाएँ — गोप्यभन्दा पनि गोप्य। यसलाई पूरै मनन गर — अनि जे चाहन्छौ त्यही गर।”"),
"18.64": ("फेरि सुन मेरो परम वचन — सबैभन्दा गोप्य: तिमी मलाई अत्यन्त प्रिय छौ, त्यसैले म तिम्रो हितका निम्ति बोल्छु।",
         "“अब सुन मेरो अन्तिम, सबैभन्दा लुकेको वचन: तिमी मलाई धेरै प्रिय छौ, त्यसैले म यो तिम्रो हितका निम्ति भन्छु।”"),
"18.65": ("मन ममा लगाऊ, मेरो भक्त बन, मलाई अर्पण गर, मलाई नमस्कार गर — तिमी निश्चय मकहाँ आउनेछौ; म सत्य वचन दिन्छु, किनकि तिमी मलाई प्रिय छौ।",
         "“हृदय ममा राख, मेरो पूजा गर, मलाई अर्पण गर, मलाई प्रणाम गर — तिमी निश्चय मकहाँ पुग्नेछौ। यो म वाचा गर्छु, किनकि तिमी मलाई प्रिय छौ।”"),
"18.66": ("सबै धर्महरू त्यागेर केवल मेरो शरण आऊ; म तिमीलाई सबै पापबाट मुक्त गर्नेछु — शोक नगर।",
         "“अरू सबै बाटो छोडेर केवल ममा समर्पण गर। म तिमीलाई सबै पापबाट मुक्त गर्नेछु — शोक नगर।”"),
"18.67": ("यो कुरा न तपस्या बिनाकोलाई भन्नुपर्छ, न श्रद्धारहितलाई, न सेवा नगर्नेलाई, न मलाई निन्दा गर्नेलाई।",
         "“यो शिक्षा अनुशासनहीनलाई, श्रद्धारहितलाई, इच्छुक नभएकालाई वा मलाई घृणा गर्नेलाई नदेऊ।”"),
"18.68": ("जसले मेरा भक्तहरूलाई परम भक्तिसाथ यो परम गोप्य सिकाउँछ — मलाई आफ्नो उच्चतम प्रेम दिएर — ऊ मकहाँ आउनेछ।",
         "“जसले मेरा भक्तहरूलाई, मप्रतिको प्रेमले, यो परम गोप्य कुरा सिकाउँछ — मलाई आफ्नो गहिरो भक्ति दिएर — ऊ मकहाँ पुग्नेछ।”"),
"18.69": ("उसभन्दा बढी मेरो सेवा गर्ने मानिसहरूमा कोही छैन; र पृथ्वीमा उसभन्दा मलाई प्रिय कोही हुनेछैन।",
         "“यस्तो शिक्षकभन्दा बढी मेरो सेवा कोही गर्दैन; पृथ्वीमा उसभन्दा मलाई प्रिय कोही हुनेछैन।”"),
"18.70": ("र जसले हाम्रो यो पवित्र संवादको अध्ययन गर्छ — उसद्वारा म ज्ञानयज्ञले पूजित हुन्छु; यो मेरो विश्वास हो।",
         "“र जसले हाम्रो यो पवित्र संवाद पढ्छ — उसले मलाई ज्ञानको यज्ञले पूजा गरेको म ठान्छु।”"),
"18.71": ("श्रद्धाले, निन्दा बिना, यसलाई सुन्ने मानिस पनि — मुक्त भएर — सत्पुरुषहरूका शुभ लोकहरूमा पुग्छ।",
         "“जो श्रद्धाले र ईर्ष्या बिना मात्र सुन्छ — ऊ पनि मुक्त भएर सज्जनहरूका आनन्दमय लोकमा पुग्छ।”"),
"18.72": ("हे पार्थ, के यो तिमीले एकाग्र मनले सुन्यौ? के अज्ञानको मोह नष्ट भयो?",
         "“के तिमीले यो पूरा ध्यान दिएर सुन्यौ, अर्जुन? के अज्ञानको भ्रम हट्यो?”"),
"18.73": ("अर्जुनले भने: मेरो मोह नष्ट भयो; हे अच्युत, तपाईंको कृपाले मैले स्मृति पाएँ; म स्थिर छु, मेरो सन्देह गयो — म तपाईंको आज्ञा पालन गर्नेछु।",
         "अर्जुन जवाफ दिन्छन्: “मेरो भ्रम हट्यो; हे अपरिवर्तनीय प्रभु, तपाईंको कृपाले मैले स्मृति पाएँ। म स्थिर छु, सन्देहरहित — म तपाईंको आज्ञा पालन गर्नेछु।”"),
"18.74": ("सञ्जयले भने: यसरी मैले वासुदेव र महात्मा पार्थको अद्भुत, रोमाञ्चक संवाद सुनेँ।",
         "सञ्जय वर्णन गर्छन्: “यसरी मैले वासुदेव र उदार पार्थको अद्भुत, रौं ठाडो पार्ने कुराकानी सुनेँ।”"),
"18.75": ("व्यासको कृपाले मैले यो परम, सबैभन्दा गोप्य योग — योगेश्वर कृष्ण आफैं बोलेको — सुनेँ।",
         "“व्यासको कृपाले मैले यो परम, गोप्य योग — योगका स्वामी कृष्ण आफैंले भनेको — सुनेँ।”"),
"18.76": ("हे राजन्, केशव र अर्जुनको यो अद्भुत, पवित्र संवाद बारम्बार सम्झेर, म बारम्बार रमाउँछु।",
         "“हे राजा, केशव र अर्जुनको यो अद्भुत र पवित्र संवाद बारम्बार सम्झेर, म हर्षले गद्गद हुन्छु।”"),
"18.77": ("र हे राजन्, हरिको त्यो सबैभन्दा अद्भुत रूप बारम्बार सम्झेर, मेरो आश्चर्य ठूलो छ — र म बारम्बार रमाउँछु।",
         "“र हे राजा, प्रभुको त्यो सबैभन्दा अद्भुत रूप बारम्बार सम्झेर, म आश्चर्य र आनन्दले भरिन्छु।”"),
"18.78": ("जहाँ योगेश्वर कृष्ण र धनुर्धारी पार्थ छन् — त्यहाँ समृद्धि, विजय, वैभव र निश्चित नीति छन्; यो मेरो विश्वास हो।",
         "“जहाँ योगका स्वामी कृष्ण र धनुर्धारी अर्जुन उभिन्छन् — त्यहाँ भाग्य, विजय, समृद्धि र अटल ज्ञान हुन्छ। यो मेरो दृढ विश्वास हो।”"),
}
